-- ItemType 是暴露給 Lua 的 Java 類別（靜態欄位 CONTAINER…；LuaManager.java:2311）：這裡用哨兵表代替
ItemType = {}
for _, n in ipairs({ "NORMAL", "FOOD", "WEAPON", "LITERATURE", "DRAINABLE", "CONTAINER", "CLOTHING", "KEY", "KEY_RING", "MOVEABLE", "RADIO", "MAP", "ALARM_CLOCK", "ALARM_CLOCK_CLOTHING", "ANIMAL", "WEAPON_PART" }) do
    ItemType[n] = { name = n }
end
local MAIN_TO_TYPE = { Normal = "NORMAL", Food = "FOOD", Weapon = "WEAPON", Literature = "LITERATURE", Drainable = "DRAINABLE", Container = "CONTAINER", Item = "NORMAL" }
ScriptManager = { instance = { FindItem = function(_, name)
    local k = knownItems[name]
    if not k then return nil end
    local itemType = ItemType[k.itemType or MAIN_TO_TYPE[k.main] or "NORMAL"]
    return { name = name, getDisplayName = function() return name end, getDisplayCategory = function() return k.cat end,
        getDaysTotallyRotten = function() return k.rots or 1000000000 end, isItemType = function(_, t) return t == itemType end }
end } }
Fluid = { Get = function(name) return { name = name } end }
-- BloodBodyPartType（BloodBodyPartType.java:10-47，MAX 之前 18 個部位）、ImmutableColor／Color 建構子
BloodBodyPartType = { MAX = { index = function() return 18 end }, parts = {} }
for i = 0, 17 do BloodBodyPartType.parts[i] = { index = function() return i end } end
BloodBodyPartType.FromIndex = function(i) return BloodBodyPartType.parts[i] end
ImmutableColor = { new = function(r, g, b, a) return { getRedFloat = function() return r end, getGreenFloat = function() return g end,
    getBlueFloat = function() return b end, getAlphaFloat = function() return a end } end }
Color = { new = function(r, g, b, a) return { r = r, g = g, b = b, a = a } end }
-- ClothingPatch(tailorLvl, fabricType, hasHole)：防禦值由等級算出（Clothing.java:1419-1428, 1470-1473）
FAKE_FABRIC = { [1] = { 5, 0 }, [2] = { 10, 5 }, [3] = { 20, 10 } }
function fakeClothingPatch(lvl, fabric, hole)
    local f = FAKE_FABRIC[fabric]
    return { fabric = fabric, lvl = lvl, hole = hole == true, gain = 0, scratch = math.floor(math.max(1, f[1] * (lvl / 10))),
        bite = f[2] > 0 and math.floor(math.max(1, f[2] * (lvl / 10))) or 0 }
end
-- 假電台：記錄每次 SendTransmission 與頻道登錄（getZomboidRadio 在 dedicated 上非 nil，A14）
radioSent, radioChannels = {}, {}
-- ZomboidRadio.devices（ZomboidRadio.java:50、123-125）：世界收音機／電視在 addToWorld 登記、
-- removeFromWorld 註銷（IsoWaveSignal.java:332-352 -> :936-958）。假世界的 AddSpecialObject／
-- 刪除／情境的 place 維護它；radioDeviceReads 數 get 次數（每 tick 預算）。radioAbsent＝沒有實例，
-- getZomboidRadio 回 nil（LuaManager.java:2909-2911）。全域：主函式已逼近 200 個 local。
radioDevices, radioDeviceReads, radioAbsent = {}, 0, false
function registerDevice(o, key, sq)
    o.worldKey, o.square = key, sq
    for _, d in ipairs(radioDevices) do if d == o then return end end   -- RegisterDevice 的 contains
    radioDevices[#radioDevices + 1] = o
end
function unregisterDevice(o)
    for i = #radioDevices, 1, -1 do if radioDevices[i] == o then table.remove(radioDevices, i) end end
end
function getZomboidRadio()
    if radioAbsent then return nil end
    return {
        -- 情境直接清空 worldObjects 來模擬 chunk 卸載；引擎卸載會對每個物件 removeFromWorldToMeta
        -- -> UnRegisterDevice（IsoChunk.java:3244-3247），所以格子上已經沒有的登記在這裡離開清單。
        getDevices = function()
            for i = #radioDevices, 1, -1 do
                local o, k, present = radioDevices[i], radioDevices[i].worldKey, false
                if k then
                    for _, w in ipairs(worldObjects[k] or {}) do if w == o then present = true end end
                    if not present then table.remove(radioDevices, i) end
                end
            end
            return { size = function() return #radioDevices end,
                get = function(_, i) radioDeviceReads = radioDeviceReads + 1; return radioDevices[i + 1] end }
        end,
        SendTransmission = function(_, x, y, channel, msg, guid, codes, r, g, b, strength, isTV)
            radioSent[#radioSent + 1] = { x = x, y = y, channel = channel, msg = msg, strength = strength, isTV = isTV }
        end,
        addChannelName = function(_, name, freq, category) radioChannels[#radioChannels + 1] = { name = name, freq = freq, category = category } end,
    }
end
function getModFileReader(modId, path, create)
    local f = io.open("MOD/" .. modId .. "/Contents/mods/" .. modId .. "/42/" .. path, "rb")
    if not f then return nil end
    return { readLine = function() local line = f:read("*l"); return line and (line:gsub("\r$", "")) end,
        close = function() f:close() end }
end
-- getModInfoByID(id):getModVersion()（LuaManager.java:5368、ChooseGameInfo.java:696）：讀真的 mod.info
function getModInfoByID(modId)
    local f = io.open("MOD/" .. modId .. "/Contents/mods/" .. modId .. "/42/mod.info", "rb")
    if not f then return nil end
    local text = f:read("*a")
    f:close()
    local v = string.match(text, "modversion=([^\r\n]+)")
    return { getModVersion = function() return v or "" end }
end
worldHours = 1000                -- getGameTime():getWorldAgeHours() 的假值（全域：主函式已逼近 200 個 local）
function getGameTime() return { getWorldAgeHours = function() return worldHours end } end
-- RolesWrite 是原版角色編輯器自己的閘門（ISRolesList.lua:20/110、RolesEditPacket.java:19）
Capability = { AddItem = "AddItem", SaveWorld = "SaveWorld", RolesWrite = "RolesWrite" }
nextItemId = 1
function instanceItem(fullType)
    local k = knownItems[fullType]
    if not k then return nil end
    local id = nextItemId
    nextItemId = nextItemId + 1
    local it = { fullType = fullType, id = id, modData = {}, condition = 10, uses = 1, age = 0, repaired = 0, readPages = 0,
        equipped = false, favorite = false, broken = false, parts = {} }
    it.getFullType = function() return fullType end
    it.getID = function() return it.id end
    it.getModData = function() return it.modData end
    it.getUnequippedWeight = function() return k.w end
    it.getActualWeight = function() return k.w end
    it.getCategory = function() return k.main end
    it.getDisplayCategory = function() return k.cat end
    it.getScriptItem = function() return ScriptManager.instance:FindItem(fullType) end
    -- 手上拿著也算裝備中（IsoGameCharacter.isEquipped:10380-10382 = 穿著或 isHandItem）
    it.isEquipped = function() return it.equipped or (it.holder ~= nil and (it.holder.primary == it or it.holder.secondary == it)) end
    it.isForceDropHeavyItem = function() return k.heavy == true end
    it.getAttachedSlot = function() return it.attachedSlot or -1 end
    it.isFavorite = function() return it.favorite end
    it.isBroken = function() return it.broken end
    it.getCondition = function() return it.condition end
    it.setCondition = function(_, v) it.condition = v end
    it.getCurrentUses = function() return it.uses end
    it.setCurrentUses = function(_, v) it.uses = v end
    it.getConditionMax = function() return 10 end
    it.getMaxAmmo = function() return k.maxAmmo or 0 end
    -- 保鮮期是每件物品自己的值（新品取腳本值；罐頭與煮好的米飯、麵會改，RecipeCodeOnCooked.java:10-15）
    it.offAge, it.offAgeMax = k.offAge or 1000000000, k.offAgeMax or 1000000000
    it.getOffAge = function() return it.offAge end
    it.setOffAge = function(_, v) it.offAge = v end
    it.getOffAgeMax = function() return it.offAgeMax end
    it.setOffAgeMax = function(_, v) it.offAgeMax = v end
    -- 物品層的其他存檔狀態（InventoryItem.save:1739-1782）：預設值 = 原版新物品
    it.infected, it.keyId, it.remoteId, it.remoteRange, it.ammo = false, -1, -1, 0, 0
    it.isInfected = function() return it.infected end
    it.setInfected = function(_, v) it.infected = v end
    it.getKeyId = function() return it.keyId end
    it.setKeyId = function(_, v) it.keyId = v end
    it.getRemoteControlID = function() return it.remoteId end
    it.setRemoteControlID = function(_, v) it.remoteId = v end
    it.getRemoteRange = function() return it.remoteRange end
    it.setRemoteRange = function(_, v) it.remoteRange = v end
    it.getCurrentAmmoCount = function() return it.ammo end
    it.setCurrentAmmoCount = function(_, v) it.ammo = v end
    -- B42 屬性：刀頭耐久與銳利度（InventoryItem.java:4593-4641, 4789-4823）；銳利度讀取時以
    -- 刀頭（或本體）耐久比例為上限，新物品是腳本預設的滿值
    if k.head then
        it.head, it.headMax, it.headRepaired = k.head, k.head, 0
