        end
        return writer
    end
    sentCommands = {}
    local unreadable = cmd(boss, "admin.catalog", { action = "add", id = "bad_readback", item = "Base.Twine", prices = { survivor = { price = 5 } } })
    getFileWriter = realWriter
    local pushed = false
