fire("OnServerStarted")
onlinePlayers = { boss, zed }
sentItemPackets = {}
cmd(zed, "hello")
local removed = 0
for _, pk in ipairs(sentItemPackets) do if pk.remove ~= nil then removed = removed + 1 end end
check(zed.inventory.count("Base.Lighter") == 0 and L.getBalance("zed", "survivor").available == balanceBefore and removed == 2
    and anomalies("removed-rolled-back") == 1,
    "every item of a claim that rolled back with the world is removed (the money came back)")
-- a durable claim whose entry was pruned after the TTL is left alone
rev = cmd(zed, "shop.list").revision
local b4 = cmd(zed, "shop.buy", { id = "twine", revision = rev })
nowMs = nowMs + M.CLAIMED_TTL_MS + M.PRUNE_EVERY_MS + 1000
fire("OnTickEvenPaused")
check(S.modData().mailbox.byOwner.zed == nil or S.modData().mailbox.byOwner.zed.entries[b4.mailId] == nil, "claimed entries are pruned after the TTL")
cmd(zed, "hello")
check(zed.inventory.count("Base.Twine") >= 1 and anomalies("removed-rolled-back") == 1, "a durable stamped item without an entry is kept")
-- rule five (1): death settles claimed entries; the new character gets nothing again
local b5 = cmd(zed, "shop.buy", { id = "bandage", revision = rev })
check(b5.delivered == true, "setup: bandage delivered before death")
fire("OnCharacterDeath", zed)
check(S.modData().mailbox.byOwner.zed.entries[b5.mailId].state == "settled", "death marks claimed entries settled")
zed.inventory = fakeInventory(20)
zed.modData = {}
cmd(zed, "hello")
check(zed.inventory.count("Base.Bandage") == 0 and anomalies("redelivered") == 1, "a settled entry is never redelivered to the new character")
-- a ready entry survives death and can still be claimed by the new character
zed.inventory.maxWeight = 0
local b6 = cmd(zed, "shop.buy", { id = "plank", revision = rev, acceptMail = true })
check(b6.delivered == false and M.unclaimed("zed") == 1, "setup: parked entry")
fire("OnCharacterDeath", zed)
zed.inventory = fakeInventory(50)
zed.modData = {}
cmd(zed, "hello")
check(M.unclaimed("zed") == 1 and cmd(zed, "mail.claim", { mailId = b6.mailId }).ok == true and zed.inventory.count("Base.Plank") == 5, "ready entries stay claimable after death")
onlinePlayers = {}
end)()

-- ===== 情境二十七之二：客戶端分頁／篩選 helper（shared） =====
io.write("scenario 27b: filterPage\n")
;(function()
-- (the day parser, the kind / day filters and the sort moved to the UI framework's FilterBar and
-- Date in rev 11 and are covered by its own harness; the server pages its recovery rows here)
local rows = {}
for i = 1, 60 do rows[i] = { kind = (i % 3 == 0) and "sold" or "listed", ts = 1788739200000 + i * 3600000, price = (i * 7) % 50, name = "n" .. (61 - i) } end
local page, p, pages, total = EC.filterPage(rows, { perPage = 25, page = 3 })
check(#page == 10 and p == 3 and pages == 3 and total == 60 and page[1] == rows[51], "paging keeps input order and clamps the last page")
page, p = EC.filterPage(rows, { perPage = 25, page = 9 })
check(p == 3 and #page == 10, "a page past the end clamps to the last page")
end)()

-- ===== 情境二十八：白名單與快照 codec =====
io.write("scenario 28: whitelist + codec\n")
;(function()
local Codec = S.Codec
modDataStore[EC.MODDATA_KEY] = nil
files = {}
sentCommands = {}
nowMs = nowMs + 61000
fire("OnServerStarted")
check(files["MinidoracatEconomy/whitelist.json"] ~= nil and Codec.status().errorCode == nil and Codec.status().counts.categories >= 20, "first start writes the default whitelist.json")
local axe = instanceItem("Base.Axe"); axe.condition = 3; axe.repaired = 2
check(Codec.check(axe) == true, "a tool weapon is whitelisted")
local bag = instanceItem("Base.Bag_ALICEpack")
local okB, whyB = Codec.check(bag)
check(okB == false and whyB == "not_whitelisted", "containers are refused whatever the file says")
local apple = instanceItem("Base.Apple")
check(Codec.check(apple) == true, "perishable food is listable (it keeps ageing in escrow, see below)")
apple.rotten = true
local okA, whyA = Codec.check(apple)
check(okA == false and whyA == "perishable", "rotten food is refused")
local corn = instanceItem("Base.CannedCorn")
check(Codec.check(corn) == true, "non-perishable food passes")
local book = instanceItem("Base.BookCarpentry1"); book.readPages = 3
check(Codec.check(book) == true and Codec.rebuild(Codec.snapshot(book)).readPages == 3, "a read book is listable and keeps its page count")
axe.equipped = true
local okE, whyE = Codec.check(axe)
check(okE == false and whyE == "equipped", "an equipped item is refused")
axe.equipped = false
-- modData travels with the snapshot (vanilla writes customName / condition:* there, InventoryItem.java:3255, 3268)
axe.modData.SomeModState = 1
axe.modData.nested = { a = "x", b = { c = true } }
axe:setName("Old Reliable"); axe:setCustomName(true)
check(Codec.check(axe) == true, "mod data is never a reason by itself")
local axeSnap = Codec.snapshot(axe)
check(axeSnap.name == "Old Reliable" and axeSnap.modData.SomeModState == 1 and axeSnap.modData.nested.b.c == true and axeSnap.modData.customName == "Old Reliable",
    "the snapshot carries the custom name and nested modData")
local axeBack = Codec.rebuild(axeSnap)
check(axeBack.name == "Old Reliable" and axeBack.customName == true and axeBack.modData.SomeModState == 1 and axeBack.modData.nested.b.c == true, "rebuild restores name, custom flag and modData")
axe.modData.deep = { a = { b = { c = 1 } } }
local okD, whyD = Codec.check(axe)
check(okD == false and whyD == "moddata_too_big", "modData nested deeper than the snapshot may carry is refused")
axe.modData.deep = nil
axe.modData.big = string.rep("x", 200)
local okS, whyS = Codec.check(axe)
check(okS == false and whyS == "moddata_too_big", "an oversized modData string is refused")
axe.modData.big = nil
axe.modData.SomeModState = nil; axe.modData.nested = nil
axe.modData[EC.PLAYER_MODDATA_KEY] = { mailId = "old" }
check(Codec.check(axe) == true and Codec.snapshot(axe).modData[EC.PLAYER_MODDATA_KEY] == nil, "our own claim stamp never blocks a listing and is not carried")
-- perishable food: state round-trips and the hours spent in escrow age it (Food.java:774)
worldHours = 1000
apple.rotten = false; apple.age = 2; apple.hunger = -4; apple.cooked = true
local appleSnap = Codec.snapshot(apple)
check(appleSnap.food.listedHours == 1000 and appleSnap.food.hunger == -4 and appleSnap.food.cooked == true, "the food snapshot keeps hunger, cooked state and the listing hour")
worldHours = 1048
local appleBack = Codec.rebuild(appleSnap)
check(appleBack.age == 4 and appleBack.hunger == -4 and appleBack.cooked == true, "48 world hours in escrow add two days of age (rot speed 1)")
worldHours = 1000
check(Codec.rebuild(appleSnap).age == 2, "no elapsed time, no extra age")
-- snapshot / rebuild round trip incl. fluid + allowed modData
files["MinidoracatEconomy/whitelist.json"] = { lines = { '{"categories":["ToolWeapon","VehicleMaintenance"],"types":["Base.Nails"],"excludeTypes":["Base.Saw"]}' }, opens = 0 }
check(Codec.load() == true and Codec.status().counts.types == 1, "a hand-edited whitelist loads")
check(Codec.check(instanceItem("Base.Nails")) == true and Codec.check(instanceItem("Base.Saw")) == false and Codec.check(instanceItem("Base.Bandage")) == false,
    "types / excludeTypes / categories from the file are honoured")
local can = instanceItem("Base.PetrolCan"); can:getFluidContainer():addFluid(Fluid.Get("Petrol"), 3.5); can.condition = 7; can.modData.Keep = "yes"; can.modData[EC.PLAYER_MODDATA_KEY] = { mailId = "x" }
local snap = Codec.snapshot(can)
check(snap.type == "Base.PetrolCan" and snap.condition == 7 and snap.fluid.name == "Petrol" and snap.fluid.amount == 3.5 and snap.modData.Keep == "yes" and snap.modData[EC.PLAYER_MODDATA_KEY] == nil,
    "the snapshot keeps condition, fluid and modData and drops the claim stamp")
local back = Codec.rebuild(snap)
check(back ~= nil and back.condition == 7 and back.fluidName == "Petrol" and back.fluidAmount == 3.5 and back.modData.Keep == "yes", "rebuild restores the same fields")
;(function()
    -- a fresh container starts with its script's fluid (FluidContainer.readFromScript); an empty one
    -- leaves no fluid in the snapshot and must not come back full
    local snapEmpty = Codec.snapshot(instanceItem("Base.PetrolCan"))
    local real = instanceItem
    instanceItem = function(t) local it = real(t); it:getFluidContainer():addFluid(Fluid.Get("Petrol"), 10); return it end
    local copy = Codec.rebuild(snapEmpty)
    instanceItem = real
    check(snapEmpty.fluid == nil and copy ~= nil and copy.fluidAmount == 0 and copy.fluidName == "", "an empty container is rebuilt empty even when a fresh one starts full")
end)()
;(function()
    -- the snapshot carries one fluid: a mixture is refused, a single fluid passes
    local mixed, single = instanceItem("Base.PetrolCan"), instanceItem("Base.PetrolCan")
    local base = mixed.getFluidContainer
    mixed.getFluidContainer = function(self) local fc = base(self); fc.isMixture = function() return true end; return fc end
    single.getFluidContainer = function(self) local fc = base(self); fc.isMixture = function() return false end; return fc end
    local okM, whyM = Codec.stateCheck(mixed)
    check(okM == false and whyM == "fluid_mixture" and Codec.stateCheck(single) == true, "a fluid mixture is refused as fluid_mixture, a single fluid is not")
end)()
local weapon = instanceItem("Base.Axe"); local scope = instanceItem("Base.x2Scope"); weapon:attachWeaponPart(scope)
local inv = fakeInventory(50)
check(Codec.detachParts(weapon, inv) == 1 and #weapon.parts == 0 and inv.count("Base.x2Scope") == 1, "weapon parts are detached back into the backpack")
files["MinidoracatEconomy/whitelist.json"] = { lines = { '{"categories": 5}' }, opens = 0 }
local okL, errL = Codec.load()
check(okL == false and type(errL) == "table" and errL.code == "not_array" and errL.field == "categories"
    and Codec.status().errorCode == "whitelist_invalid" and Codec.status().errorDetail.code == "not_array" and Codec.status().error == nil
    and Codec.check(instanceItem("Base.Nails")) == true, "a broken file is rejected as a code with the field it names, and the previous whitelist stays")
-- 家具不再是固定類別：分類開著就能上架（地圖仍固定：情境 BB-8）
files["MinidoracatEconomy/whitelist.json"] = { lines = { '{"categories":["Furniture","Communications","Tool"],"types":[],"excludeTypes":[]}' }, opens = 0 }
check(Codec.load() == true and Codec.check(instanceItem("Base.Mov_Chair")) == true and Codec.check(instanceItem("Base.Saw")) == true,
    "furniture is listable once its category is")
-- 無線電：DeviceData 隨快照走（頻道、電量、開關、音量、耳機、靜音、電池、媒體）
local radio = instanceItem("Base.RadioRed"); radio.dev.channel = 93200; radio.dev.power = 0.4; radio.dev.on = true; radio.dev.volume = 0.8; radio.dev.headphones = 2; radio.dev.battery = false
check(Codec.check(radio) == true, "a radio is listable when its category is on")
local radioSnap = Codec.snapshot(radio)
check(radioSnap.device.channel == 93200 and radioSnap.device.on == true and radioSnap.device.battery == false, "the snapshot keeps the tuned state")
local radioBack = Codec.rebuild(radioSnap)
check(radioBack.dev.channel == 93200 and radioBack.dev.power == 0.4 and radioBack.dev.on == true and radioBack.dev.volume == 0.8 and radioBack.dev.headphones == 2 and radioBack.dev.battery == false,
    "rebuild restores channel, power, switch, volume, headphones and battery")
-- 面板寫回：一次一個分類或一件物品，寫進檔案、重讀、稽核；手改過的檔案先擋 stale
local boss = fakePlayer("boss"); boss.role = "admin"
local mod = fakePlayer("mod"); mod.role = "moderator"
local function wcmd(who, args)
    nowMs = nowMs + 700
    args.requestId = "w" .. nowMs
    fire("OnClientCommand", EC.COMMAND_MODULE, "admin.whitelist", who, args)
    return lastSent("admin.whitelist").args
end
local st = wcmd(mod, { action = "status" })
check(st.ok == true and #st.whitelist.categories == 3 and st.whitelist.categories[1] == "Furniture" and st.perms.write == false, "status carries the lists and the read-only role sees them")
check(wcmd(mod, { action = "set", category = "Tool", allowed = false }).error == "forbidden", "a moderator cannot edit the whitelist")
local off = wcmd(boss, { action = "set", category = "Tool", allowed = false })
local wlText = table.concat(files["MinidoracatEconomy/whitelist.json"].lines, "\n")
check(off.ok == true and #off.whitelist.categories == 2 and string.find(wlText, '"categories": ["Furniture","Communications"]', 1, true) ~= nil
    and Codec.check(instanceItem("Base.Saw")) == false, "turning a category off rewrites the file and takes effect at once")
check(wcmd(boss, { action = "set", category = "Tool", allowed = true }).whitelist.categories[3] == "Tool" and Codec.check(instanceItem("Base.Saw")) == true, "turning it back on appends it")
check(wcmd(boss, { action = "set", category = "Tool", allowed = true }).ok == true and #files["MinidoracatEconomy/whitelist.json"].lines == 5, "a no-op edit does not rewrite the file")
local ex = wcmd(boss, { action = "set", fullType = "Base.Saw", mode = "exclude" })
check(ex.ok == true and ex.whitelist.excludeTypes[1] == "Base.Saw" and Codec.check(instanceItem("Base.Saw")) == false, "an item exclusion beats its allowed category")
local al = wcmd(boss, { action = "set", fullType = "Base.Saw", mode = "allow" })
check(al.ok == true and #al.whitelist.excludeTypes == 0 and al.whitelist.types[1] == "Base.Saw", "switching to allow moves the item between the two lists")
check(wcmd(boss, { action = "set", fullType = "Base.Nails", mode = "allow" }).ok == true and Codec.check(instanceItem("Base.Nails")) == true, "an explicit allow lists an item whose category is off")
local inh = wcmd(boss, { action = "set", fullType = "Base.Nails", mode = "inherit" })
check(inh.ok == true and #inh.whitelist.types == 1 and Codec.check(instanceItem("Base.Nails")) == false, "inherit clears the override")
check(wcmd(boss, { action = "set", fullType = "Base.Nope", mode = "allow" }).error == "unknown_item", "unknown item types are refused")
check(wcmd(boss, { action = "set", category = "bad cat", allowed = true }).error == "invalid_args" and wcmd(boss, { action = "set", fullType = "Base.Saw", mode = "maybe" }).error == "invalid_args", "malformed edits are refused")
files["MinidoracatEconomy/whitelist.json"].lines[1] = files["MinidoracatEconomy/whitelist.json"].lines[1] .. " "
check(wcmd(boss, { action = "set", category = "Communications", allowed = false }).error == "whitelist_stale" and Codec.check(instanceItem("Base.RadioRed")) == true and Codec.status().counts.categories == 3,
    "a file changed outside the panel is refused as stale until reloaded")
check(wcmd(boss, { action = "reload" }).ok == true and wcmd(boss, { action = "set", category = "Communications", allowed = false }).ok == true
    and Codec.check(instanceItem("Base.RadioRed")) == false and Codec.status().counts.categories == 2, "after a reload the edit goes through and the radio category is off")
local wlAudit = 0
for _, e in ipairs(X.auditEntries(30)) do if e.action == "whitelist" then wlAudit = wlAudit + 1 end end
check(wlAudit == 8, "every applied edit and the reload are audited once (no-ops and refusals are not)")
-- FE-3 / FE-4: a refused whitelist.json is a code plus facts (the JSON line, the field and entry),
-- in the reply, the status and the audit line alike
;(function()
    local path = "MinidoracatEconomy/whitelist.json"
    files[path] = { lines = { "{", '  "categories": ["Tool",', '  "types": [] }' }, opens = 0 }
    local json = wcmd(boss, { action = "reload" })
    files[path] = { lines = { '{"categories":["Tool",""],"types":[],"excludeTypes":[]}' }, opens = 0 }
    local okE, entry = Codec.load()
    check(json.ok == false and json.error == "whitelist_invalid" and type(json.detail) == "table" and json.detail.code == "json"
        and json.detail.line == 3 and json.whitelist.errorCode == "whitelist_invalid" and json.whitelist.errorDetail.code == "json"
        and json.whitelist.error == nil and okE == false and entry.code == "bad_entry" and entry.field == "categories"
        and entry.entry == 2 and entry.max == 128,
        "FE-3: a whitelist that is not JSON names the line, a bad entry its field and position; facts only")
    local failed = nil
    for _, e in ipairs(X.auditEntries(5)) do
        if failed == nil and e.action == "whitelist" and e.field == "reload" then failed = e end
    end
    check(failed ~= nil and failed.ok == false and failed.after == nil and failed.errorCode == "whitelist_invalid"
        and failed.errorDetail.code == "json" and failed.errorDetail.line == 3,
        "FE-4: a refused whitelist reload is audited as ok=false with the refusal's code and facts, no composed after text")
    -- FE-4b: a reload that worked carries no refusal code in its event or its audit line
    local seen, emit = {}, X.emit
    X.emit = function(kind, fields)
        if kind == "admin.whitelist" or kind == "admin.catalog" then seen[kind] = fields end
        return emit(kind, fields)
    end
    files[path] = { lines = { '{"categories":["Tool"],"types":[],"excludeTypes":[]}' }, opens = 0 }
    local wlOk = wcmd(boss, { action = "reload" })
    nowMs = nowMs + 700
    fire("OnClientCommand", EC.COMMAND_MODULE, "admin.catalog", boss, { action = "reload", requestId = "c" .. nowMs })
    local catOk = lastSent("admin.catalog").args
    X.emit = emit
    local wlLine, catLine = nil, nil
    for _, e in ipairs(X.auditEntries(5)) do
        if wlLine == nil and e.action == "whitelist" and e.field == "reload" then wlLine = e end
        if catLine == nil and e.action == "catalog" and e.field == "reload" then catLine = e end
    end
    check(wlOk.ok == true and catOk.ok == true and seen["admin.whitelist"] ~= nil and seen["admin.whitelist"].errorCode == nil
        and seen["admin.catalog"] ~= nil and seen["admin.catalog"].errorCode == nil
        and wlLine ~= nil and wlLine.ok == true and wlLine.errorCode == nil and wlLine.errorDetail == nil
        and catLine ~= nil and catLine.ok == true and catLine.errorCode == nil and catLine.errorDetail == nil,
        "FE-4b: a successful whitelist or catalog reload writes no refusal code into its event or audit line")
end)()
-- 卸載 MOD 後留下的 explicit 規則：inherit 不需要 ScriptManager 認得那個 fullType 才能移除
files["MinidoracatEconomy/whitelist.json"] = { lines = { '{"categories":["Tool"],"types":["GoneMod.Relic"],"excludeTypes":["GoneMod.Relic"],"modDataKeys":[]}' }, opens = 0 }
local orphanLoad = wcmd(boss, { action = "reload" })
check(orphanLoad.ok == true and orphanLoad.whitelist.types[1] == "GoneMod.Relic" and orphanLoad.whitelist.excludeTypes[1] == "GoneMod.Relic",
    "an explicit rule whose mod is gone is kept by the load instead of being dropped")
local orphan = wcmd(boss, { action = "set", fullType = "GoneMod.Relic", mode = "inherit" })
check(orphan.ok == true and #orphan.whitelist.types == 0 and #orphan.whitelist.excludeTypes == 0
    and string.find(table.concat(files["MinidoracatEconomy/whitelist.json"].lines, "\n"), "GoneMod.Relic", 1, true) == nil,
    "inherit removes an orphan rule from both lists without asking the item registry")
local wlText = table.concat(files["MinidoracatEconomy/whitelist.json"].lines, "\n")
check(wcmd(boss, { action = "set", fullType = "GoneMod.Relic", mode = "allow" }).error == "unknown_item"
    and wcmd(boss, { action = "set", fullType = 5, mode = "inherit" }).error == "invalid_args"
    and table.concat(files["MinidoracatEconomy/whitelist.json"].lines, "\n") == wlText,
    "an unknown item still cannot be allowed and a fullType that is not a string is refused without rewriting the file")
onlinePlayers = {}
end)()

-- ===== 情境二十八之三：B42 物品狀態跟著快照走；帶不走的拒絕上架 =====
-- 市場與拍賣是「存快照、重建新物品」：沒存進快照的狀態會變回腳本預設。刀頭與銳利度變回滿值
-- 等於上架再取消就免費修好／磨利；槍與彈匣的子彈、本子的字會直接消失。
io.write("scenario 28c: item state the rebuild must not reset\n")
;(function()
local Codec = S.Codec
files["MinidoracatEconomy/whitelist.json"] = nil
check(Codec.load() == true, "the default whitelist is back for the item-state checks")
local fresh = instanceItem("Base.Axe")
local freshSnap = Codec.snapshot(fresh)
check(freshSnap.head == nil and freshSnap.headRepaired == nil and freshSnap.sharpness == nil,
    "a pristine tool carries no head or sharpness fields, so fresh copies still merge into one lot")
local dull = instanceItem("Base.Axe"); dull.head = 4; dull.headRepaired = 2; dull.sharpness = 0.3
check(Codec.check(dull) == true, "a worn tool is still listable")
local dullSnap = Codec.snapshot(dull)
local dullBack = Codec.rebuild(dullSnap)
check(dullBack.head == 4 and dullBack.headRepaired == 2 and math.abs(dullBack:getSharpness() - 0.3) < 1e-9,
    "rebuild keeps the worn head, its repair count and the dull edge (no free repair or sharpening)")
check(Codec.signature(dullSnap) ~= Codec.signature(freshSnap), "a worn tool never merges with a new one")
check(Codec.isCanonical(fresh, "Base.Axe") == true and Codec.isCanonical(dull, "Base.Axe") == false,
    "buyback treats a worn head or a dull edge as not like new")
local gun = instanceItem("Base.Pistol"); gun.ammo = 7; gun.clip = true; gun.chamber = true; gun.jammed = true; gun.fireMode = "Auto"
check(Codec.check(gun) == true, "a loaded gun is listable")
local gunBack = Codec.rebuild(Codec.snapshot(gun))
check(gunBack.ammo == 7 and gunBack.clip == true and gunBack.chamber == true and gunBack.jammed == true and gunBack.fireMode == "Auto",
    "rebuild keeps the inserted magazine, its rounds, the chambered round, the jam and the fire mode")
local mag = instanceItem("Base.9mmClip"); mag.ammo = 12
check(Codec.rebuild(Codec.snapshot(mag)).ammo == 12, "a loaded magazine keeps its rounds")
local note = instanceItem("Base.Notebook")
check(Codec.check(note) == true, "a blank notebook is listable")
note.pages = { [1] = "the car is at the gas station" }
local okW, whyW = Codec.check(note)
check(okW == false and whyW == "written", "a notebook with writing is refused (its text cannot travel)")
note.pages = nil; note.lockedBy = "alice"
local okL, whyL = Codec.check(note)
check(okL == false and whyL == "written", "a locked notebook is refused too")
local corn = instanceItem("Base.CannedCorn"); corn.poison = 3
local okP, whyP = Codec.check(corn)
check(okP == false and whyP == "poisoned" and select(2, Codec.stateCheck(corn)) == "poisoned",
    "poisoned food is refused by the market and by the buyback")
corn.poison = 0; corn.extra = {}
for i = 1, Codec.SPICES_MAX + 1 do corn.extra[i] = "Base.Carrots" end
local okD, whyD = Codec.check(corn)
check(okD == false and whyD == "too_many_ingredients", "a dish with more ingredients than a snapshot carries is refused")
corn.extra = nil; corn.fertilized = true
local okF, whyF = Codec.check(corn)
check(okF == false and whyF == "fertilized", "a fertilized egg is refused")
local half = instanceItem("Base.CannedCorn")
half.hunger = -5; half.calories = 50; half.proteins = 0.5; half.lipids = 0.25; half.carbs = 10
half.thirst = 5; half.burnt = true; half.boredom = 3; half.unhappy = 2; half.stress = -1; half.endurance = 0.1
half.fatigue = 0.2; half.pain = 4; half.flu = 1; half.cookingTime = 12; half.microwave = true; half.chef = "bob"
check(Codec.check(half) == true, "half-eaten plain food is listable")
local halfBack = Codec.rebuild(Codec.snapshot(half))
check(halfBack.hunger == -5 and halfBack.calories == 50 and halfBack.proteins == 0.5 and halfBack.lipids == 0.25 and halfBack.carbs == 10,
    "nutrition keeps what was left instead of refilling to a new can")
check(halfBack.thirst == 5 and halfBack:getThirstChange() == 1 and halfBack.boredom == 3 and halfBack.unhappy == 2 and halfBack.stress == -1
    and halfBack.endurance == 0.1 and halfBack.fatigue == 0.2 and halfBack.pain == 4 and halfBack.flu == 1,
    "raw effects are restored, so a burnt item is not divided again")
check(halfBack.cookingTime == 12 and halfBack.microwave == true and halfBack.chef == "bob" and halfBack.burnt == true,
    "cooking progress and who cooked it travel too")
local pad = instanceItem("Base.Bandage"); pad.infected = true; pad.keyId = 4321; pad.remoteId = 7; pad.remoteRange = 12
local padBack = Codec.rebuild(Codec.snapshot(pad))
check(padBack.infected == true and padBack.keyId == 4321 and padBack.remoteId == 7 and padBack.remoteRange == 12,
    "infection, key id and remote pairing are restored")
local plain = Codec.snapshot(instanceItem("Base.Bandage"))
check(plain.infected == nil and plain.keyId == nil and plain.remote == nil and plain.ammo == nil,
    "a plain item carries none of these fields")
end)()

-- ===== 情境二十八之四：衣物帶著完整狀態上架；買家看到過濾後的狀態預覽 =====
-- 衣物不再是固定拒絕類別：逐部位破洞、血汙、髒污、補丁、整體濕度與外觀都隨快照走。補在破洞上的補丁
-- 帶不走（conditionGain），照「帶不走就拒絕」處理。預覽只給買家需要的欄位，不給 modData 與鑰匙 ID。
io.write("scenario 28d: clothing state and the buyer preview\n")
;(function()
local Codec, Mk, M = S.Codec, S.Market, S.Mailbox
local TEE = "Base.Tshirt_DefaultTEXTURE"
local function part(i) return BloodBodyPartType.FromIndex(i) end
-- Clothing.addPatch（:1074-1115）：加補丁視覺、蓋洞時記 conditionGain 並補回耐久、清掉破洞
local function sew(item, idx, fabric, lvl)
    local p, hole = part(idx), item.vis:getHole(part(idx)) > 0
    local setter = ({ "setBasicPatch", "setDenimPatch", "setLeatherPatch" })[fabric]
    item.vis[setter](item.vis, p)
    local q = fakeClothingPatch(lvl, fabric, hole)
    if hole then q.gain = 2; item.condition = item.condition + 2 end
    item.patchMap[idx] = q
    item.vis.holes[idx] = nil
end
local function leaves(t)
    local n, empty = 0, true
    for _, v in pairs(t) do
        empty = false
        if type(v) == "table" then n = n + leaves(v) else n = n + 1 end
    end
    if empty then return 1 end
    return n
end
files["MinidoracatEconomy/whitelist.json"] = nil
check(Codec.load() == true and select(2, Codec.check(instanceItem(TEE))) == "not_whitelisted"
    and EC.isFixedType(ScriptManager.instance:FindItem(TEE)) == false and EC.isFixedType(ScriptManager.instance:FindItem("Base.Bag_ALICEpack")) == false
    and EC.isFixedType(ScriptManager.instance:FindItem("Base.Map")) == true,
    "clothing and bags are no longer fixed classes, but the shipped default list does not open clothing; maps stay fixed")
files["MinidoracatEconomy/whitelist.json"] = { lines = { EC.jsonEncode({ categories = { "Clothing" } }) }, opens = 0 }
check(Codec.load() == true and Codec.check(instanceItem(TEE)) == true, "a host that enables the Clothing category can list a plain shirt")
local worn = instanceItem(TEE); worn.equipped = true
check(select(2, Codec.check(worn)) == "equipped", "a worn shirt is refused as equipped")
local a, b = instanceItem(TEE), instanceItem(TEE)
local sa, sb = Codec.snapshot(a), Codec.snapshot(b)
check(sa.cloth == nil and type(sa.look) == "table" and sa.look.hue ~= sb.look.hue and Codec.isCanonical(b, TEE) == true,
    "two fresh shirts differ only in their rolled look, which the buyback comparison ignores")
-- 破、補（加襯，不蓋洞）、血、髒、濕、染色、改名
local tee = instanceItem(TEE)
tee.condition = 6
tee.vis:setHole(part(2)); tee.vis:setHole(part(6))
sew(tee, 7, 2, 5)
tee.vis:setBlood(part(6), 0.8); tee.vis:setBlood(part(7), 3 / 255); tee.vis:setDirt(part(0), 0.4); tee.vis:setDirt(part(17), 1)
tee:setBloodLevel(40); tee:setDirtiness(22.5); tee:setWetness(65)
tee:setCustomColor(true); tee:setColor({ r = 0.1, g = 0.2, b = 0.3, a = 1 })
tee.name = "Lucky shirt"; tee:setCustomName(true)
check(Codec.check(tee) == true and tee:getName() == "Bloody, Lucky shirt", "a torn, padded, bloody, dirty, wet, dyed, renamed shirt is listable")
local snap = Codec.snapshot(tee)
check(snap.name == "Lucky shirt" and leaves(snap) <= 64,
    "the snapshot keeps the raw custom name and the whole garment fits in half the journal's 128 leaves")
local back = Codec.rebuild(snap)
local same = back.condition == 6 and back.bloodLv == 40 and back.dirtLv == 22.5 and back.wet == 65 and back.customColor == true
    and back.col.r == 0.1 and back.col.b == 0.3 and back.name == "Lucky shirt" and back:getName() == "Bloody, Lucky shirt"
for i = 0, 17 do
    local p = part(i)
    for _, g in ipairs({ "getHole", "getBasicPatch", "getDenimPatch", "getLeatherPatch", "getBlood", "getDirt" }) do
        if back.vis[g](back.vis, p) ~= tee.vis[g](tee.vis, p) then same = false end
    end
    if back:getDefForPart(p, false) ~= tee:getDefForPart(p, false) or back:getDefForPart(p, true) ~= tee:getDefForPart(p, true) then same = false end
    local q1, q2 = tee.patchMap[i], back.patchMap[i]
    if (q1 == nil) ~= (q2 == nil) or (q1 and (q1.fabric ~= q2.fabric or q1.scratch ~= q2.scratch or q1.bite ~= q2.bite or q1.hole ~= q2.hole)) then same = false end
end
check(same, "rebuild restores every part's holes, patch visuals, blood and dirt bytes, the patch and its defences, the levels, dye and name")
check(back.vis.hue == tee.vis.hue and back.vis.tint:getRedFloat() == tee.vis.tint:getRedFloat() and back.vis.base == tee.vis.base
    and back.vis.choice == tee.vis.choice and back.vis.decal == tee.vis.decal, "the rebuilt shirt keeps the seller's look, not a new roll")
check(Codec.signature(Codec.snapshot(back)) == Codec.signature(snap) and Codec.isCanonical(tee, TEE) == false,
    "a rebuilt copy snapshots to the same signature, and a worn shirt is never bought back as new")
-- 手錶：不再是固定拒絕類別（鬧鐘時間與開關隨快照走）；擺放式鬧鐘仍固定拒絕
local WATCH = "Base.WristWatch_Right_DigitalBlack"
files["MinidoracatEconomy/whitelist.json"] = { lines = { EC.jsonEncode({ categories = { "Clothing", "Accessory", "Electronics" } }) }, opens = 0 }
check(Codec.load() == true and Codec.check(instanceItem(WATCH)) == true and EC.isFixedType(ScriptManager.instance:FindItem("Base.AlarmClock2")) == false
    and Codec.check(instanceItem("Base.AlarmClock2")) == true,
    "a wristwatch and a standing alarm clock in a whitelisted category are both listable")
local watch = instanceItem(WATCH); watch.alarmHour, watch.alarmMinutes, watch.alarmSet = 7, 30, true
local wback = Codec.rebuild(Codec.snapshot(watch))
local fresh = instanceItem(WATCH)
check(wback.alarmHour == 7 and wback.alarmMinutes == 30 and wback.alarmSet == true
    and (fresh.alarmHour ~= 7 or fresh.alarmMinutes ~= 30 or fresh.alarmSet ~= true),
    "the rebuilt watch keeps the seller's alarm time and switch, not a new roll")
local w1, w2 = instanceItem(WATCH), instanceItem(WATCH)
check(Codec.signature(Codec.snapshot(w1)) ~= Codec.signature(Codec.snapshot(w2)) and Codec.isCanonical(w2, WATCH) == true,
    "two fresh watches differ only in their rolled alarm, which the buyback comparison ignores")
-- 補在破洞上的補丁：conditionGain 帶不走 -> 拒絕（上架與收購共用 stateCheck）
local patched = instanceItem(TEE)
patched.vis:setHole(part(4)); sew(patched, 4, 1, 2)
local okP, whyP = Codec.check(patched)
check(okP == false and whyP == "clothing_patch" and select(2, Codec.stateCheck(patched)) == "clothing_patch",
    "a patch sewn over a hole is refused by the market and the buyback")
-- 預覽：有上限、四捨五入、不含 modData 與鑰匙 ID
tee.modData.MIC42_t = "someone 491234"
local pv = Codec.preview(Codec.snapshot(tee))
check(pv.cond == 6 and pv.condMax == 10 and pv.holes == 2 and pv.patches == 1 and pv.blood == 40 and pv.dirt == 23 and pv.wet == 65
    and pv.name == "Lucky shirt" and pv.modData == nil and pv.cloth == nil and pv.look == nil,
    "the preview counts holes and patches, rounds the levels and carries no modData or raw per-part data")
local keyed = instanceItem("Base.Bandage"); keyed.keyId = 4321; keyed.remoteId = 7; keyed.remoteRange = 12
local kp = Codec.preview(Codec.snapshot(keyed))
local leaked = false
for _, v in pairs(kp) do if v == 4321 or v == 7 then leaked = true end end
check(kp.keyed == true and kp.paired == true and not leaked, "key and remote pairings are flags; their ids never reach the buyer")
local can = instanceItem("Base.PetrolCan"); can:getFluidContainer():addFluid(Fluid.Get("Petrol"), 3.456)
local fp = Codec.preview(Codec.snapshot(can))
check(fp.fluid == "Petrol" and math.abs(fp.fluidL - 3.46) < 1e-9 and fp.fluidCap == 10, "fluid carries its type key for translation and the amount rounded to 0.01 L of the capacity")
local axe = instanceItem("Base.Axe"); axe.head = 5; axe.sharpness = 0.3
local gun = instanceItem("Base.Pistol"); gun.ammo = 7; gun.clip = true; gun.jammed = true
local ap, gp = Codec.preview(Codec.snapshot(axe)), Codec.preview(Codec.snapshot(gun))
check(ap.head == 5 and ap.headMax == 10 and ap.sharp == 30 and gp.ammo == 7 and gp.ammoMax == 15 and gp.clip == true and gp.jammed == true and gp.fireMode == "Single",
    "tools show head and edge against their maxima, guns their rounds, magazine, jam and fire mode")
local apple = instanceItem("Base.Apple"); apple.age = 1; apple.cooked = true
local fd = Codec.preview(Codec.snapshot(apple)).food
apple.age = 4
check(fd.cooked == true and math.abs(fd.freshDays - 2) < 1e-9 and Codec.preview(Codec.snapshot(apple)).food.stale == true,
    "food shows how fresh it was when listed, or that it was already stale")
-- 電池裝置：電池在不在、還剩多少（DeviceData getHasBattery／getPower）
local radio = instanceItem("Base.RadioRed"); radio.dev.power = 0.374
local bare = instanceItem("Base.RadioRed"); bare.dev.battery = false; bare.dev.power = 0
local rp, bp = Codec.preview(Codec.snapshot(radio)), Codec.preview(Codec.snapshot(bare))
check(rp.power == 37 and rp.battery == nil and bp.battery == false and bp.power == nil,
    "a battery device shows how full its battery is, or that none is in")
-- 裝置裡的光碟／錄影帶帶不走（mediaItem 沒有 getter、setMediaIndex(short) Lua 呼叫不到）-> 拒絕
local disc = instanceItem("Base.RadioRed"); disc.dev.mediaIndex = 3
check(select(2, Codec.stateCheck(disc)) == "device_media" and Codec.stateCheck(instanceItem("Base.RadioRed")) == true,
    "a device with a disc or tape inside is refused; an empty one passes")
-- 走真的市場流程：上架 -> 瀏覽看到預覽（舊欄位已移除）-> 購買收到同狀態的衣物
modDataStore[EC.MODDATA_KEY] = nil
sentCommands = {}
worldSprites = { ["100,200,0"] = "MinidoracatEconomy_terminal_0" }
nowMs = nowMs + 61000
fire("OnServerStarted")
local boss = fakePlayer("boss"); boss.role = "admin"
local ann = fakePlayer("ann"); ann.x, ann.y = 101, 200; ann.inventory = fakeInventory(50)
local bob = fakePlayer("bob"); bob.x, bob.y = 101, 201; bob.inventory = fakeInventory(50)
onlinePlayers = { boss, ann, bob }
local function cmd(who, name, args)
    nowMs = nowMs + 600
    args = args or {}
    args.requestId = args.requestId or (name .. nowMs)
    withCurrency(name, args)
    fire("OnClientCommand", EC.COMMAND_MODULE, name, who, args)
    local s = lastSent(name)
    return s and s.args or {}
end
cmd(boss, "terminal.register", { x = 100, y = 200, z = 0, kind = "atm" })
L.credit("ann", "survivor", 100, "SYSTEM_MINT", { requestId = "cs-ann", reasonCode = "t" })
L.credit("bob", "survivor", 500, "SYSTEM_MINT", { requestId = "cs-bob", reasonCode = "t" })
tee.modData.MIC42_t = nil
ann.inventory:AddItem(tee)
local cands = cmd(ann, "market.candidates")
check(cands.items[1].ok == true and cands.items[1].state.holes == 2 and cands.items[1].condition == nil, "the seller's picker previews the same state")
local listed = cmd(ann, "market.list", { itemId = tee.id, price = 50, requestId = "tee1" })
local row = cmd(bob, "market.browse", { sort = "time" }).items[1]
check(listed.ok == true and row.state.holes == 2 and row.state.blood == 40 and row.condition == nil and row.uses == nil and row.fluid == nil and row.fluidAmount == nil,
    "browse sends the preview and none of the old raw fields")
local bought = cmd(bob, "market.buy", { listingId = listed.listingId, price = 50, requestId = "teeb" })
local got = bob.inventory.items[#bob.inventory.items]
check(bought.ok == true and bought.delivered == true and got.fullType == TEE and got ~= tee and got.condition == 6 and got.vis:getHole(part(6)) > 0
    and got.patchMap[7] and got.patchMap[7].scratch == tee.patchMap[7].scratch and got.vis.blood[6] == tee.vis.blood[6] and got.wet == 65 and got.vis.decal == tee.vis.decal,
    "the buyer receives a rebuilt shirt with the listed holes, patch, blood, wetness and look")
local mail = M.add("bob", { kind = "return", item = TEE, qty = 1, snapshot = snap, txId = "t-cloth" })
local listedMail = nil
for _, r in ipairs(M.list("bob")) do if r.id == mail.id then listedMail = r end end
check(listedMail ~= nil and listedMail.state.holes == 2 and listedMail.state.patches == 1, "a letter that carries a snapshot lists the same preview")
-- 選物格寫出「穿著中」「手持中」：拒絕理由同是 equipped，候選列另帶 equipped = worn | hand，兩者不合併成一列
do
    local wornTee, heldTee, spareTee = instanceItem(TEE), instanceItem(TEE), instanceItem(TEE)
    for _, it in ipairs({ wornTee, heldTee, spareTee }) do ann.inventory:AddItem(it) end
    wornTee.equipped = true
    ann:setPrimaryHandItem(heldTee)
    local byId, rows = {}, 0
    for _, r in ipairs(cmd(ann, "market.candidates").items) do
        if r.item == TEE then
            rows = rows + 1
            for _, id in ipairs(r.itemIds) do byId[id] = tostring(r.reason) .. "/" .. tostring(r.equipped) end
        end
    end
    check(rows == 3 and byId[wornTee.id] == "equipped/worn" and byId[heldTee.id] == "equipped/hand" and byId[spareTee.id] == "nil/nil",
        "an equipped refusal says whether that item is worn or in hand, the two never fold into one row, a free copy carries neither")
end
onlinePlayers = {}
files["MinidoracatEconomy/whitelist.json"] = nil
Codec.load()
end)()

-- ===== 情境二十九：市場全流程（上架、瀏覽、購買、取消、到期、費稅守恆） =====
io.write("scenario 29: market\n")
;(function()
local Mk, M, T = S.Market, S.Mailbox, S.Terminal
modDataStore[EC.MODDATA_KEY] = nil
files = {}
sentCommands = {}
sentItemPackets = {}
worldSprites = { ["100,200,0"] = "MinidoracatEconomy_terminal_0" }
SandboxVars.MinidoracatEconomy.MarketListingFeePercent = 2
SandboxVars.MinidoracatEconomy.MarketSalesTaxPercent = 5
SandboxVars.MinidoracatEconomy.MarketMaxListings = 2
nowMs = nowMs + 61000
fire("OnServerStarted")
local boss = fakePlayer("boss"); boss.role = "admin"
local ann = fakePlayer("ann"); ann.x, ann.y = 101, 200; ann.inventory = fakeInventory(50)
local bob = fakePlayer("bob"); bob.x, bob.y = 101, 201; bob.inventory = fakeInventory(50)
local cat = fakePlayer("cat"); cat.x, cat.y = 101, 199; cat.inventory = fakeInventory(50)
onlinePlayers = { boss, ann, bob, cat }
local function cmd(who, name, args)
    nowMs = nowMs + 600
    args = args or {}
    args.requestId = args.requestId or (name .. nowMs)
    withCurrency(name, args)
    fire("OnClientCommand", EC.COMMAND_MODULE, name, who, args)
    local s = lastSent(name)
    return s and s.args or {}
end
cmd(boss, "terminal.register", { x = 100, y = 200, z = 0, kind = "atm" })
L.credit("ann", "survivor", 100, "SYSTEM_MINT", { requestId = "s-ann", reasonCode = "t" })
L.credit("bob", "survivor", 500, "SYSTEM_MINT", { requestId = "s-bob", reasonCode = "t" })
L.credit("cat", "survivor", 500, "SYSTEM_MINT", { requestId = "s-cat", reasonCode = "t" })
local axe = instanceItem("Base.Axe"); axe.condition = 4; ann.inventory:AddItem(axe)
local bag = instanceItem("Base.Bag_ALICEpack"); ann.inventory:AddItem(bag)
local cands = cmd(ann, "market.candidates")
local okRows, badRows = 0, 0
for _, r in ipairs(cands.items) do if r.ok then okRows = okRows + 1 else badRows = badRows + 1 end end
check(okRows == 1 and badRows == 1 and cands.feePercent == 2 and cands.priceMin == 1, "candidates list every backpack item with its verdict")
check(cmd(ann, "market.list", { itemId = axe.id, price = 0 }).error == "price_range", "a price outside the sandbox range is refused")
ann.x = 150
check(cmd(ann, "market.list", { itemId = axe.id, price = 200 }).error == "not_at_terminal" and ann.inventory.count("Base.Axe") == 1, "listing away from a terminal is refused and the item stays")
ann.x = 101
check(cmd(ann, "market.list", { itemId = bag.id, price = 50 }).error == "not_whitelisted", "a container cannot be listed")
local listed = cmd(ann, "market.list", { itemId = axe.id, price = 200, requestId = "l1" })
check(listed.ok == true and listed.fee == 4 and ann.inventory.count("Base.Axe") == 0 and L.getBalance("ann", "survivor").available == 96
    and Mk.hasListing(listed.listingId) and #listed.mine == 1, "listing removes the item, burns the 2 percent fee and creates the listing")
local pend = ann.modData[EC.PLAYER_MODDATA_KEY].pendingOuts[listed.listingId]
check(pend ~= nil and pend.itemId == axe.id and pend.snapshot.condition == 4 and pend.price == 200 and ann.transmitted >= 1, "the seller's own modData keeps the pending list-out record with the snapshot")
check(cmd(ann, "market.list", { itemId = axe.id, price = 200, requestId = "l1" }).duplicate == true and #Mk.mine("ann") == 1, "resending the same listing request is idempotent")
-- browse
local page = cmd(bob, "market.browse", { sort = "time" })
check(page.total == 1 and page.items[1].id == listed.listingId and page.items[1].seller == "ann" and page.items[1].state.cond == 4 and page.categories[1] == "ToolWeapon" and page.currency == "survivor",
    "browse lists the listing with its snapshot summary and category")
check(cmd(bob, "market.browse", { query = "axe" }).total == 1 and cmd(bob, "market.browse", { query = "hammer" }).total == 0 and cmd(bob, "market.browse", { category = "Food" }).total == 0,
    "browse filters by query and category")
-- max listings
local n1 = instanceItem("Base.Nails"); ann.inventory:AddItem(n1)
local n2 = instanceItem("Base.Nails"); ann.inventory:AddItem(n2)
check(cmd(ann, "market.list", { itemId = n1.id, price = 5 }).ok == true and cmd(ann, "market.list", { itemId = n2.id, price = 5 }).error == "too_many_listings",
    "the per-player listing cap is enforced")
-- buy: own listing refused, wrong price refused, two buyers race
check(cmd(ann, "market.buy", { listingId = listed.listingId, price = 200 }).error == "own_listing", "a seller cannot buy their own listing")
check(cmd(bob, "market.buy", { listingId = listed.listingId, price = 150 }).error == "price_changed", "a confirmation price that differs is refused")
local bought = cmd(bob, "market.buy", { listingId = listed.listingId, price = 200, requestId = "b1" })
check(bought.ok == true and bought.tax == 10 and bought.delivered == true and bob.inventory.count("Base.Axe") == 1 and bob.inventory.items[#bob.inventory.items].condition == 4
    and L.getBalance("bob", "survivor").available == 300 and L.getBalance("ann", "survivor").available == 285 and not Mk.listingExists(listed.listingId),
    "a sale moves 200 from the buyer, 190 to the seller (96 - 1 nails fee + 190), burns 10 tax and delivers the rebuilt item")
check(cmd(cat, "market.buy", { listingId = listed.listingId, price = 200 }).error == "unknown_listing" and L.getBalance("cat", "survivor").available == 500,
    "the second buyer of the same listing is refused with zero debit")
check(cmd(bob, "market.buy", { listingId = listed.listingId, price = 200, requestId = "b1" }).duplicate == true and L.getBalance("bob", "survivor").available == 300,
    "resending the purchase is idempotent")
check(L.conservation("survivor") == 0, "fee and tax burns keep the currency conserved")
local rc = L.receipts("ann")
check(rc[#rc].kind == "market_buy" and rc[#rc].amount == 190 and rc[#rc].item == "Base.Axe", "the seller's receipt shows the net proceeds and the item")
local brc = L.receipts("bob")
check(rc[#rc].fee == 10 and brc[#brc].kind == "market_buy" and brc[#brc].amount == -200 and brc[#brc].fee == nil,
    "the seller's receipt carries the 10 tax as its fee; the buyer's carries none")
-- cancel: back to the seller through the mailbox
local mine = Mk.mine("ann")
local nailsId = mine[1].id
check(cmd(bob, "market.cancel", { listingId = nailsId }).error == "not_owner", "only the seller can cancel")
local cancelled = cmd(ann, "market.cancel", { listingId = nailsId })
check(cancelled.ok == true and cancelled.delivered == true and ann.inventory.count("Base.Nails") == 2 and not Mk.listingExists(nailsId) and L.getBalance("ann", "survivor").available == 285,
    "cancel returns the item through the mailbox; the fee is not refunded")
-- a listing occupies a mailbox slot: with the capacity at the current usage nothing new can be
-- listed or bought, while a return (expiry here) just converts the slot and never fails
local n3 = cmd(ann, "market.list", { itemId = n2.id, price = 5 })
check(n3.ok == true and M.used("ann") == Mk.ownerCount("ann") + M.unclaimed("ann") and Mk.ownerCount("ann") >= 1, "an active listing counts against the mailbox slots")
SandboxVars.MinidoracatEconomy.MailboxPerAccount = M.used("ann")
local n4 = instanceItem("Base.Nails"); ann.inventory:AddItem(n4)
check(cmd(ann, "market.list", { itemId = n4.id, price = 5 }).error == "mailbox_full" and ann.inventory.count("Base.Nails") >= 1, "a full mailbox refuses a new listing and the item stays")
nowMs = nowMs + 8 * 86400000
fire("OnTickEvenPaused")
check(not Mk.listingExists(n3.listingId) and M.unclaimed("ann") == 1 and M.used("ann") <= M.capacity(), "an expired listing goes back to the seller's mailbox even when it is full, without overshooting")
SandboxVars.MinidoracatEconomy.MailboxPerAccount = nil
local expired = 0
fire("OnTickEvenPaused")
for _, f in pairs(files) do for _, l in ipairs(f.lines) do if string.find(l, '"type":"market.expired"', 1, true) then expired = expired + 1 end end end
check(expired == 1, "expiry is journaled")
-- admin delist
local h1 = instanceItem("Base.Hammer"); cat.inventory:AddItem(h1)
