local arb = cmd(boss, "admin.catalog", { action = "add", id = "plank5", item = "Base.Plank", qty = 5, enabled = false,
    prices = { survivor = { price = 100, bidPrice = 60, buyback = true } } })
check(arb.error == "arbitrage_rejected" and Shop.sku("plank5") == nil,
