radioDevices, radioDeviceReads, radioAbsent = {}, 0, false
onlinePlayers = {}
end)()

;(function()
    local player = fakePlayer("atm-protection")
    local function object(name)
        local obj = { removed = false }
        local sq = { getX = function() return 0 end, getY = function() return 0 end, getZ = function() return 0 end,
            transmitRemoveItemFromSquare = function(_, target) target.removed = true end }
        obj.getSprite = function() return { getName = function() return name end } end
        obj.getSquare = function() return sq end
        return obj
    end
    for i = 64, 67 do
        local atm = object("location_business_bank_01_" .. i)
        local action = { character = player, item = atm }
        check(not ISDestroyStuffAction.isValid(action) and not ISDestroyStuffAction.complete(action) and not atm.removed,
            "native ATM " .. i .. " refuses both sledgehammer admission and server completion")
        local props = { object = atm }
        local result, chance = ISMoveableSpriteProps.canScrapObject(props, player)
        check(not result.canScrap and chance == 0
            and ISMoveableSpriteProps.scrapObjectInternal(props, player, {}, atm:getSquare(), atm, {}, 100, nil) == 0
            and not atm.removed, "native ATM " .. i .. " refuses scrap without removing the object or producing loot")
    end
    player.role = "admin"
    local atm = object("location_business_bank_01_64")
    local action = { character = player, item = atm }
    check(ISDestroyStuffAction.isValid(action) and ISDestroyStuffAction.complete(action) and atm.removed,
        "authorized administrator retains native sledgehammer removal")
    atm = object("location_business_bank_01_65")
    check(ISMoveableSpriteProps.canScrapObject({ object = atm }, player).canScrap
        and ISMoveableSpriteProps.scrapObjectInternal({}, player, {}, atm:getSquare(), atm, {}, 100, nil) == 3
        and atm.removed, "authorized administrator retains native scrap result and removal")
    player.role = "user"
    local cabinet = object("appliances_com_01_52")
    check(ISDestroyStuffAction.complete({ character = player, item = cabinet }) and cabinet.removed,
        "ATM protection does not change unrelated furniture removal")
    player.role = "admin"
    atm = object("location_business_bank_01_64")
    action = { character = player, item = atm }
    local admitted = ISDestroyStuffAction.isValid(action)
    player.role = "user"
    check(admitted and not ISDestroyStuffAction.complete(action) and not atm.removed,
        "revoking permission while queued prevents ATM removal at completion")
    player.role = "admin"; player.caps[Capability.AddItem] = false
    check(not ISDestroyStuffAction.complete(action) and not atm.removed,
        "an admin role without AddItem cannot remove an ATM")
    local previousOverride = EC.optionOverride
    EC.optionOverride = function(key)
        if key == "AdminRoles" then return { "ATM Keeper" } end
        return previousOverride and previousOverride(key)
    end
    player.role = "ATM Keeper"; player.caps[Capability.AddItem] = true
    check(ISDestroyStuffAction.complete(action) and atm.removed,
        "configured custom administrator role retains exact-name ATM removal")
    EC.optionOverride = previousOverride
    check(EC.AtmProtection.blocked(nil, object("location_business_bank_01_67")),
        "missing actor never grants ATM removal permission")
end)()

-- Scenario TG: the mod's own terminal object cannot be destroyed. The build used to leave an
-- IsoThumpable (thumpable, 10 health) on the square: ECTerminal swaps it for a plain IsoObject when
-- it is added and when a chunk holding an older one loads, ECAtmProtection refuses a
-- non-manager's sledgehammer and scrap, and only a terminal manager may build one.
;(function()
    local realLog, logs = EC.log, {}
    EC.log = function(m) logs[#logs + 1] = tostring(m) end
    local function thumpable(name, x, y, z)
        local o = { __class = "IsoThumpable" }
        o.getSprite = function() return { getName = function() return name end } end
        o.getSquare = function() return getCell():getGridSquare(x, y, z) end
        return o
    end
    local function onSquare(x, y, z) return worldObjects[worldKey(x, y, z)] or {} end
    local hooks = 0
    for name in pairs(EC.TERMINAL_SPRITES) do
        local h = mapObjectsOnLoad[name]
        if EC.isOwnTerminalSprite(name) then
            if h and h.priority == 5 then hooks = hooks + 1 end
        elseif h then hooks = -100 end
    end
    check(hooks == 8, "the load hook covers the mod's eight terminal tiles and no vanilla console")
    local load = mapObjectsOnLoad["MinidoracatEconomy_catgirl_2"].fn

    -- a square as an old build left it: a floor, the thumpable terminal, a radio beside it
    worldLoaded["900,900,0"] = true
    local floor = { __class = "IsoObject", getSprite = function() return { getName = function() return "floors_1" end } end }
    local old = thumpable("MinidoracatEconomy_catgirl_2", 900, 900, 0)
    local radio = { __class = "IsoRadio", getSprite = function() return { getName = function() return "x" end } end }
    worldObjects["900,900,0"] = { floor, old, radio }
    load(old)
    local list = onSquare(900, 900, 0)
    check(#list == 3 and list[1] == floor and list[3] == radio and list[2].plainNew == true
        and list[2]:getSprite():getName() == "MinidoracatEconomy_catgirl_2" and list[2].transmitted == true
        and old.removed == true,
        "an old thumpable terminal is replaced in place by a plain object on the same sprite and sent to clients")
    load(list[2])
    check(#onSquare(900, 900, 0) == 3 and onSquare(900, 900, 0)[2] == list[2], "loading the plain object again changes nothing")

    -- the build: OnObjectAdded fires for the object placeMoveableInternal just added
    worldLoaded["901,900,0"] = true
    local built = thumpable("MinidoracatEconomy_terminal_0", 901, 900, 0)
    worldObjects["901,900,0"] = { built }
    fire("OnObjectAdded", built)
    local b = onSquare(901, 900, 0)
    check(#b == 1 and b[1].plainNew == true and b[1]:getSprite():getName() == "MinidoracatEconomy_terminal_0",
        "a freshly built terminal is swapped for a plain object as soon as it is added")

    -- other objects keep theirs
    worldLoaded["902,900,0"] = true
    local console = thumpable("appliances_com_01_52", 902, 900, 0)
    local door = thumpable("fixtures_doors_01_0", 902, 900, 0)
    worldObjects["902,900,0"] = { console, door }
    fire("OnObjectAdded", console)
    fire("OnObjectAdded", door)
    local c = onSquare(902, 900, 0)
    check(#c == 2 and c[1] == console and c[2] == door and not console.removed,
        "a thumpable vanilla console and any other thumpable keep their object")

    -- an engine that removed nothing gets no second object
    worldLoaded["903,900,0"] = true
    local stuck = thumpable("MinidoracatEconomy_catgirl_1", 903, 900, 0)
    worldObjects["903,900,0"] = { stuck }
    worldRemoveRefuses[stuck] = true
    load(stuck)
    worldRemoveRefuses[stuck] = nil
    local s = onSquare(903, 900, 0)
    check(#s == 1 and s[1] == stuck, "a removal the engine refused adds no second terminal on the square")
    check(#logs == 2, "one log line per replaced terminal (" .. #logs .. ")")

    -- sledgehammer and scrap
    local player, boss = fakePlayer("tg-user"), fakePlayer("tg-boss")
    boss.role = "admin"
    local function tile(name)
        local obj = { removed = false }
        local sq = { transmitRemoveItemFromSquare = function(_, target) target.removed = true end }
        obj.getSprite = function() return { getName = function() return name end } end
        obj.getSquare = function() return sq end
        return obj
    end
    local own = tile("MinidoracatEconomy_catgirl_0")
    local action = { character = player, item = own }
    check(not ISDestroyStuffAction.isValid(action) and not ISDestroyStuffAction.complete(action) and not own.removed,
        "a player's sledgehammer is refused on the terminal at admission and at completion")
    local result, chance = ISMoveableSpriteProps.canScrapObject({ object = own }, player)
    check(not result.canScrap and chance == 0
        and ISMoveableSpriteProps.scrapObjectInternal({}, player, {}, own:getSquare(), own, {}, 100, nil) == 0
        and not own.removed, "a player cannot scrap the terminal either")
    local previousOverride = EC.optionOverride
    EC.optionOverride = function(key)
        if key == "MapATMAllowDestruction" then return true end
        return previousOverride and previousOverride(key)
    end
    check(not ISDestroyStuffAction.complete(action) and not own.removed,
        "opening map ATM removal does not open the mod's own terminals")
    EC.optionOverride = previousOverride
    check(ISDestroyStuffAction.complete({ character = boss, item = own }) and own.removed,
        "a terminal manager's sledgehammer still takes it down")

    -- building
    local function buildItem(who, tiles)
        return { character = who, objectInfo = { getScript = function()
            return { getAllTileNames = function() return javaList(tiles) end }
        end } }
    end
    local item = buildItem(player, { "MinidoracatEconomy_catgirl_0", "MinidoracatEconomy_catgirl_1" })
    check(ISBuildIsoEntity.create(item, 1, 2, 0, false, "MinidoracatEconomy_catgirl_0") == false and item.created == nil,
        "a player who is not a terminal manager cannot build a terminal: refused before the build runs")
    item = buildItem(boss, { "MinidoracatEconomy_catgirl_0" })
    check(ISBuildIsoEntity.create(item, 1, 2, 0, false, "MinidoracatEconomy_catgirl_0") == true and item.created == 1,
        "a terminal manager builds it")
    item = buildItem(player, { "carpentry_02_68" })
    check(ISBuildIsoEntity.create(item, 1, 2, 0, false, "carpentry_02_68") == true and item.created == 1,
        "other entities build as before")

    -- a vanilla console is locked while its square is a registered terminal, and only then
    local T = S.Terminal
    worldSprites["910,900,0"] = "appliances_com_01_52"
    local reg = T.register(boss, { x = 910, y = 900, z = 0, kind = "atm" })
    local function console(x)
        local obj = { removed = false }
        local sq = { getX = function() return x end, getY = function() return 900 end, getZ = function() return 0 end,
            transmitRemoveItemFromSquare = function(_, target) target.removed = true end }
        obj.getSprite = function() return { getName = function() return "appliances_com_01_52" end } end
        obj.getSquare = function() return sq end
        return obj
    end
    local function pickUp(who, obj)
        return ISMoveableSpriteProps.pickUpMoveableInternal({}, who, obj:getSquare(), obj, nil, "appliances_com_01_52", true, false)
    end
    local held = console(910)
    local hit = { character = player, item = held }
    check(reg.ok == true and not ISDestroyStuffAction.isValid(hit) and not ISDestroyStuffAction.complete(hit) and not held.removed,
        "a player's sledgehammer is refused on a registered vanilla console at admission and at completion")
    local scrapResult, scrapChance = ISMoveableSpriteProps.canScrapObject({ object = held }, player)
    check(not scrapResult.canScrap and scrapChance == 0
        and ISMoveableSpriteProps.scrapObjectInternal({}, player, {}, held:getSquare(), held, {}, 100, nil) == 0
        and not held.removed, "a player cannot scrap a registered vanilla console")
    local radios = player.inventory.count("Base.RadioRed")
    check(ISMoveableSpriteProps.canPickUpMoveable({}, player, held:getSquare(), held) == false
        and pickUp(player, held) == nil and not held.removed and player.inventory.count("Base.RadioRed") == radios,
        "a player cannot pick a registered vanilla console up: refused at the gate and where the item is made")
    local previousOverride = EC.optionOverride
    EC.optionOverride = function(key)
        if key == "MapATMAllowDestruction" then return true end
        return previousOverride and previousOverride(key)
    end
    check(not ISDestroyStuffAction.complete(hit) and not held.removed,
        "opening map ATM removal does not open a registered console")
    EC.optionOverride = previousOverride
    local other = console(910)
    check(ISDestroyStuffAction.complete({ character = boss, item = held }) and held.removed
        and pickUp(boss, other) ~= nil and other.removed,
        "a terminal manager still sledgehammers and picks up a registered console")
    local loose = console(911)
    check(ISMoveableSpriteProps.canPickUpMoveable({}, player, loose:getSquare(), loose) == true
        and pickUp(player, loose) ~= nil and loose.removed,
        "a vanilla console nobody registered stays an ordinary moveable")
    local freed = console(910)
    check(T.unregister(boss, { id = reg.id }).ok == true
        and ISDestroyStuffAction.complete({ character = player, item = freed }) and freed.removed,
        "unregistering hands the console back to the ordinary rules")
    worldSprites["910,900,0"] = nil
    for _, key in ipairs({ "900,900,0", "901,900,0", "902,900,0", "903,900,0" }) do
        worldObjects[key], worldLoaded[key] = nil, nil
    end
    EC.log = realLog
end)()

;(function()
    modDataStore[EC.MODDATA_KEY] = nil
    files, sentCommands, worldObjects = {}, {}, {}
    worldSprites = { ["100,200,0"] = "location_business_bank_01_64" }
    nowMs = nowMs + 61000
    fire("OnServerStarted")
    local boss, player = fakePlayer("atm-owner"), fakePlayer("atm-user")
    boss.role = "admin"
    player.x, player.y, player.z = 101, 200, 0
    onlinePlayers = { boss, player }
    local T, Shop = S.Terminal, S.Shop
    local atm = { removed = false }
    local square = { transmitRemoveItemFromSquare = function(_, obj) obj.removed = true end }
    atm.getSprite = function() return { getName = function() return "location_business_bank_01_64" end } end
    atm.getSquare = function() return square end
    local action = { character = player, item = atm }
    local function option(who, key, value)
        nowMs = nowMs + 700
        fire("OnClientCommand", EC.COMMAND_MODULE, "admin.option", who,
            { key = key, value = value, requestId = "atm-option-" .. nowMs })
        return lastSent("admin.option").args
    end
    check(T.near(player) and not ISDestroyStuffAction.complete(action) and not atm.removed,
        "map ATMs default to usable terminals protected from ordinary removal")
    check(option(player, "MapATMAsTerminal", false).error == "forbidden" and T.near(player),
        "ordinary players cannot disable automatic ATM access")
    check(option(player, "MapATMAllowDestruction", true).error == "forbidden"
        and not ISDestroyStuffAction.complete(action), "ordinary players cannot grant themselves ATM removal")
    check(option(boss, "MapATMAsTerminal", "false").error == "invalid_args" and T.near(player),
        "ATM access rejects string booleans")
    local reply = option(boss, "MapATMAsTerminal", false)
    check(reply.ok and reply.options.MapATMAsTerminal.value == false and not T.near(player),
        "administrator disabling ATM access changes the server gate immediately")
    check(lastSent("config").args.options.MapATMAsTerminal.value == false,
        "live ATM access denial is published to connected clients")
    check(not ISDestroyStuffAction.complete(action) and not atm.removed,
        "disabling ATM access does not disable its independent protection")
    L.credit("atm-user", "survivor", 100, "SYSTEM_MINT", { requestId = "atm-settings-seed", reasonCode = "t" })
    nowMs = nowMs + 700
    fire("OnClientCommand", EC.COMMAND_MODULE, "shop.buy", player,
        { id = "bandage", currency = "survivor", revision = Shop.revision(), requestId = "atm-disabled-buy" })
    check(lastSent("shop.buy").args.error == "not_at_terminal"
        and L.getBalance("atm-user", "survivor").available == 100 and player.inventory.count("Base.Bandage") == 0,
        "disabled ATM refuses a real purchase without charging or delivering")
    check(option(boss, "MapATMAllowDestruction", true).ok and not T.near(player)
        and ISDestroyStuffAction.complete(action) and atm.removed,
        "removal can be opened while ATM access remains disabled")
    atm.removed = false
    check(ISMoveableSpriteProps.canScrapObject({ object = atm }, player).canScrap
        and ISMoveableSpriteProps.scrapObjectInternal({}, player, {}, square, atm, {}, 100, nil) == 3 and atm.removed,
        "open removal reaches the original furniture scrap result")
    atm.removed = false
    local admitted = ISDestroyStuffAction.isValid(action)
    check(option(boss, "MapATMAllowDestruction", false).ok and admitted
        and not ISDestroyStuffAction.complete(action) and not atm.removed,
        "closing removal blocks an action admitted before the setting changed")
    worldSprites["100,200,0"] = "MinidoracatEconomy_terminal_0"
    nowMs = nowMs + 700
    fire("OnClientCommand", EC.COMMAND_MODULE, "terminal.register", boss, { x = 100, y = 200, z = 0 })
    local registered = lastSent("terminal.register").args
    check(registered.ok and T.near(player), "disabling map ATMs leaves registered custom terminals usable")
    nowMs = nowMs + 700
    fire("OnClientCommand", EC.COMMAND_MODULE, "terminal.demolish", player, { x = 100, y = 200, z = 0 })
    check(lastSent("terminal.demolish").args.error == "forbidden", "ATM settings do not grant custom-terminal demolition")
    nowMs = nowMs + 700
    fire("OnClientCommand", EC.COMMAND_MODULE, "terminal.unregister", boss, { id = registered.id })
    worldSprites["100,200,0"] = "location_business_bank_01_64"
    check(option(boss, "MapATMAsTerminal", nil).ok and T.near(player),
        "resetting ATM access restores the sandbox default")
    check(option(boss, "MapATMAllowDestruction", nil).ok and not ISDestroyStuffAction.complete(action),
        "resetting ATM removal restores protected default")
    check(option(boss, "MapATMAllowDestruction", 1).error == "invalid_args",
        "ATM removal rejects numeric booleans")
    check(option(boss, "MapATMAsTerminal", false).ok and option(boss, "MapATMAllowDestruction", true).ok,
        "both independent overrides can be stored together")
    nowMs = nowMs + 61000
    fire("OnServerStarted")
    check(not T.near(player) and ISDestroyStuffAction.complete(action) and atm.removed,
        "reinitialization preserves both stored ATM overrides")
    onlinePlayers, worldSprites = {}, {}
end)()

-- ===== 情境 LC：每人永久限購（第三種互斥模式）=====
-- 永久份數不回補舊日桶、不因模式／角色／換季而清零；回滾沿用同一份世界資料。
-- 本段新增 25 個 check；事件 writer 使用 harness 記憶體檔，不代表原生落盤驗證。
io.write("scenario LC: a lifetime cap belongs to the account, not to the day\n")
;(function()
local Shop, M = S.Shop, S.Mailbox
local DAY = 86400000
modDataStore[EC.MODDATA_KEY] = nil
files, sentCommands, writerDeny = {}, {}, {}
-- 對齊到獎勵日開始後一小時：整段前半要留在同一個獎勵日內，不能剛好壓在日界上
nowMs = R.nextResetMs(nowMs) + 3600000
-- 部署現場：這個世界的舊版只記每日份數，永久表還不存在
modDataStore[EC.MODDATA_KEY] = { shopDaily = { [R.dayKey(nowMs)] = { ["lc-zed"] = { keepsake = 4 } } } }
files[Shop.FILE] = { lines = { EC.jsonEncode({ items = {
    { id = "keepsake", item = "Base.Bandage", qty = 1, dailyCap = 3, dailyCapScope = "lifetime", category = "medical",
        prices = { survivor = { price = 10 }, cat = { price = 4 } } },
    { id = "ration", item = "Base.Nails", qty = 1, dailyCap = 2, category = "food",
        prices = { survivor = { price = 5 } } },
    { id = "sand", item = "Base.RippedSheets", qty = 1, dailyCap = 0, category = "medical",
        prices = { survivor = { price = 5 } } },
    { id = "crate", item = "Base.Plank", qty = 3, dailyCap = 2, dailyCapScope = "lifetime", category = "tool",
        prices = { survivor = { price = 30 } } },
} }) }, opens = 0 }
fire("OnServerStarted")
worldSprites = { ["100,200,0"] = "MinidoracatEconomy_terminal_0" }
local boss = fakePlayer("lc-admin"); boss.role = "admin"
local zed = fakePlayer("lc-zed"); zed.x, zed.y = 101, 200; zed.inventory = fakeInventory(400)
local kit = fakePlayer("lc-kit"); kit.x, kit.y = 101, 200; kit.inventory = fakeInventory(400)
onlinePlayers = { boss, zed, kit }
local function cmd(who, name, args)
    nowMs = nowMs + 600
    args = args or {}
    args.requestId = args.requestId or (name .. nowMs)
    withCurrency(name, args)
    fire("OnClientCommand", EC.COMMAND_MODULE, name, who, args)
    local s = lastSent(name)
    return s and s.args or {}
end
-- 從事件 writer 輸出的 harness 記憶體檔解碼，不採用 command 回覆當寫檔證據。
local function purchases(username, sku)
    proofSettle()
    local out = {}
    for _, f in pairs(files) do
        for _, line in ipairs(f.lines or {}) do
            if string.find(line, '"type":"shop.purchase"', 1, true) then
                local row = EC.jsonDecode(line)
                if type(row) == "table" and row.username == username and row.sku == sku then out[#out + 1] = row end
            end
        end
    end
    return out
end
local function rowOf(snapshot, id)
    for _, it in ipairs(snapshot.items or {}) do if it.id == id then return it end end
    return nil
end
cmd(boss, "terminal.register", { x = 100, y = 200, z = 0, kind = "atm" })
L.credit("lc-zed", "survivor", 500, "SYSTEM_MINT", { requestId = "lc-seed-s", reasonCode = "t" })
L.credit("lc-zed", "cat", 50, "SYSTEM_MINT", { requestId = "lc-seed-c", reasonCode = "t" })
L.credit("lc-kit", "survivor", 500, "SYSTEM_MINT", { requestId = "lc-seed-k", reasonCode = "t" })
check(Shop.sku("keepsake").dailyCapScope == "lifetime" and Shop.used("lc-zed", "keepsake", nowMs) == 0,
    "a lifetime count starts at zero even in a world where the previous version already wrote day rows")
local toDaily = cmd(boss, "admin.catalog", { action = "set", id = "keepsake", dailyCapScope = "player", revision = Shop.revision() })
local dayView = Shop.used("lc-zed", "keepsake", nowMs)
local back = cmd(boss, "admin.catalog", { action = "set", id = "keepsake", dailyCapScope = "lifetime", revision = Shop.revision() })
check(toDaily.ok and back.ok and dayView == 4 and Shop.used("lc-zed", "keepsake", nowMs) == 0,
    "the day rows the old version wrote are still the daily count and are never adopted as a lifetime head start")
local buyRev = Shop.revision()
local first = cmd(zed, "shop.buy", { id = "keepsake", count = 2, currency = "survivor", revision = buyRev, requestId = "lc-first" })
check(first.ok and first.used == 2 and first.remaining == 1 and zed.inventory.count("Base.Bandage") == 2,
    "the buy reply answers with this account's lifetime shares and the room that is left")
local kitBuy = cmd(kit, "shop.buy", { id = "keepsake", count = 3, currency = "survivor", revision = buyRev, requestId = "lc-kit-fill" })
check(kitBuy.ok and kitBuy.used == 3 and kitBuy.remaining == 0 and Shop.used("lc-zed", "keepsake", nowMs) == 2,
    "one account spending its whole lifetime allowance leaves another account's allowance untouched")
local paidInCat = cmd(zed, "shop.buy", { id = "keepsake", currency = "cat", revision = buyRev, requestId = "lc-cat" })
check(paidInCat.ok and paidInCat.currency == "cat" and paidInCat.used == 3 and paidInCat.remaining == 0
    and L.getBalance("lc-zed", "cat").available == 46,
    "the last lifetime share can be paid in another currency: the allowance belongs to the row, not to the wallet")
local surBefore, catBefore = L.getBalance("lc-zed", "survivor").available, L.getBalance("lc-zed", "cat").available
local mailBefore = M.unclaimed("lc-zed")
local over = cmd(zed, "shop.buy", { id = "keepsake", currency = "survivor", revision = buyRev, requestId = "lc-over" })
check(over.error == "lifetime_cap" and over.used == 3 and over.remaining == 0
    and L.getBalance("lc-zed", "survivor").available == surBefore
    and L.getBalance("lc-zed", "cat").available == catBefore
    and M.unclaimed("lc-zed") == mailBefore and zed.inventory.count("Base.Bandage") == 3,
    "an exhausted lifetime cap has its own refusal code, charges neither wallet and posts no letter")
check(lastSent("shop.stock") == nil,
    "one account's personal allowance is never broadcast to the whole server as shared stock")
local replay = cmd(zed, "shop.buy", { id = "keepsake", count = 2, currency = "survivor", revision = buyRev, requestId = "lc-first" })
local keepRows = purchases("lc-zed", "keepsake")
check(replay.duplicate == true and replay.used == 3 and #keepRows == 2
    and keepRows[2].capScope == "lifetime" and keepRows[2].cap == 3
    and keepRows[2].usedAfter == 3 and keepRows[2].lifetimeUsed == 3,
    "a resend is answered from the record: one share, one published purchase, and the event names the mode, the limit and the totals")
cmd(zed, "shop.buy", { id = "ration", count = 2, currency = "survivor", revision = buyRev, requestId = "lc-ration" })
local rationRows = purchases("lc-zed", "ration")
check(#rationRows == 1 and rationRows[1].capScope == "player" and rationRows[1].cap == 2
    and rationRows[1].usedAfter == 2 and rationRows[1].lifetimeUsed == 2,
    "a sale under a daily cap publishes that day's total and the account's lifetime total side by side")
local rationLife = cmd(boss, "admin.catalog", { action = "set", id = "ration", dailyCapScope = "lifetime", revision = Shop.revision() })
local rationBlocked = cmd(zed, "shop.buy", { id = "ration", currency = "survivor", revision = Shop.revision(), requestId = "lc-ration-2" })
check(rationLife.ok and Shop.used("lc-zed", "ration", nowMs) == 2 and rationBlocked.error == "lifetime_cap",
    "shares sold while the row was a daily row are already counted the moment it becomes a lifetime row")
cmd(zed, "shop.buy", { id = "sand", count = 4, currency = "survivor", revision = Shop.revision(), requestId = "lc-sand" })
local snap = cmd(zed, "shop.list", {})
local sandRow, keepRow = rowOf(snap, "sand"), rowOf(snap, "keepsake")
local sandRows = purchases("lc-zed", "sand")
check(sandRow.used == 4 and sandRow.remaining == nil and keepRow.used == 3 and keepRow.remaining == 0
    and #sandRows == 1 and sandRows[1].cap == 0 and sandRows[1].lifetimeUsed == 4,
    "an unlimited row publishes what the account bought with no room figure at all, and is still counted for good")
local lowered = cmd(boss, "admin.catalog", { action = "set", id = "sand", dailyCapScope = "lifetime", dailyCap = 3, revision = Shop.revision() })
local past = cmd(zed, "shop.buy", { id = "sand", currency = "survivor", revision = Shop.revision(), requestId = "lc-sand-2" })
check(lowered.ok and Shop.used("lc-zed", "sand", nowMs) == 4
    and past.error == "lifetime_cap" and past.used == 4 and past.remaining == 0,
    "a limit set below what an account already bought refuses the next share instead of clearing the count")
local batch = cmd(boss, "admin.catalog", { action = "batch", ids = { "keepsake", "crate" },
    fields = { qty = 4, dailyCap = 5, dailyCapScope = "lifetime" }, revision = Shop.revision() })
check(batch.ok and Shop.sku("keepsake").qty == 4 and Shop.sku("crate").dailyCapScope == "lifetime"
    and Shop.sku("crate").dailyCap == 5 and Shop.used("lc-zed", "keepsake", nowMs) == 3,
    "a batch that rewrites all three limit columns hands nobody the shares they already spent back")
local off = cmd(boss, "admin.catalog", { action = "set", id = "keepsake", enabled = false, revision = Shop.revision() })
local on = cmd(boss, "admin.catalog", { action = "set", id = "keepsake", enabled = true, revision = Shop.revision() })
check(off.ok and on.ok and Shop.used("lc-zed", "keepsake", nowMs) == 3,
    "taking the row off the shelf and putting it back on is not a reset either")
local away = cmd(boss, "admin.catalog", { action = "set", id = "keepsake", dailyCapScope = "player", revision = Shop.revision() })
local dailySide = Shop.used("lc-zed", "keepsake", nowMs)
local home = cmd(boss, "admin.catalog", { action = "set", id = "keepsake", dailyCapScope = "lifetime", revision = Shop.revision() })
check(away.ok and home.ok and dailySide == 7 and Shop.used("lc-zed", "keepsake", nowMs) == 3,
    "every purchase writes both counters: a mode round trip reads its own number and clears neither")
local crateRev = Shop.revision()
zed.inventory.maxWeight = 0
local refusedMail = cmd(zed, "shop.buy", { id = "crate", currency = "survivor", revision = crateRev, requestId = "lc-crate" })
local parked = cmd(zed, "shop.buy", { id = "crate", currency = "survivor", revision = crateRev, requestId = "lc-crate", acceptMail = true })
check(refusedMail.error == "mail_confirmation_required" and refusedMail.used == 0
    and parked.ok and parked.mailed == true and parked.used == 1,
    "a purchase refused for capacity spends nothing, while the one parked in the mailbox spends its lifetime share immediately")
zed.inventory.maxWeight = 400
local claimed = cmd(zed, "mail.claim", { mailId = parked.mailId })
check(claimed.ok and zed.inventory.count("Base.Plank") == 4 and Shop.used("lc-zed", "crate", nowMs) == 1,
    "collecting the letter hands the goods over without spending a second share")
nowMs = nowMs + 2 * DAY
local newDay = cmd(zed, "shop.buy", { id = "ration", currency = "survivor", revision = Shop.revision(), requestId = "lc-newday" })
check(Shop.used("lc-zed", "keepsake", nowMs) == 3 and Shop.used("lc-zed", "ration", nowMs) == 2
    and newDay.error == "lifetime_cap",
    "two reward days later a lifetime row is still exhausted: no day boundary hands the allowance back")
nowMs = nowMs + 1000
fire("OnServerStarted")
check(Shop.used("lc-zed", "keepsake", nowMs) == 3 and Shop.used("lc-kit", "keepsake", nowMs) == 3
    and Shop.used("lc-zed", "sand", nowMs) == 4,
    "reinitialisation reads every account's lifetime counts back out of the world's own data")
zed.dead = true
fire("OnCharacterDeath", zed)
local reborn = fakePlayer("lc-zed"); reborn.x, reborn.y = 101, 200; reborn.inventory = fakeInventory(400)
onlinePlayers = { boss, reborn, kit }
fire("OnNewGame", reborn)
local rebornRow = rowOf(cmd(reborn, "shop.list", {}), "keepsake")
check(rebornRow.used == 3 and rebornRow.remaining == 2,
    "a brand new character on the same account inherits the shares that account already spent")
zed = reborn
local seasonBefore = S.Seasons.currentId()
local rotated = cmd(boss, "admin.seasons", { action = "start", expectedSeason = seasonBefore, reason = "quota isolation" })
check(rotated.ok and S.Seasons.currentId() ~= seasonBefore and Shop.used("lc-zed", "keepsake", nowMs) == 3,
    "a real season rotation leaves this account's lifetime purchase allowance unchanged")
-- 只還原 harness 的假 ModData 世界表（不是原生存檔）：世界回到購買前，錢與份數必須一起回去
local worldBefore = proofSnapshot()
local balBefore = L.getBalance("lc-zed", "survivor").available
local extra = cmd(zed, "shop.buy", { id = "keepsake", currency = "survivor", revision = Shop.revision(), requestId = "lc-extra" })
local spentAfter = L.getBalance("lc-zed", "survivor").available
proofRestartFrom(worldBefore)
check(extra.ok and extra.used == 4 and spentAfter == balBefore - 10
    and Shop.used("lc-zed", "keepsake", nowMs) == 3
    and L.getBalance("lc-zed", "survivor").available == balBefore,
    "a world rolled back to before a purchase takes the lifetime share back together with the money")
local added = cmd(boss, "admin.catalog", { action = "add", id = "relic", item = "Base.Twine", qty = 1,
    dailyCap = 1, dailyCapScope = "lifetime", category = "other",
    prices = { survivor = { price = 6 } }, revision = Shop.revision() })
local once = cmd(zed, "shop.buy", { id = "relic", currency = "survivor", revision = Shop.revision(), requestId = "lc-relic" })
local twice = cmd(zed, "shop.buy", { id = "relic", currency = "survivor", revision = Shop.revision(), requestId = "lc-relic-2" })
check(added.ok and Shop.sku("relic").dailyCapScope == "lifetime" and once.ok and once.remaining == 0
    and twice.error == "lifetime_cap" and zed.inventory.count("Base.Twine") == 1,
    "a row added as a lifetime row sells exactly once per account from the moment it appears")
local disk = table.concat(files[Shop.FILE].lines, "\n")
local badSet = cmd(boss, "admin.catalog", { action = "set", id = "keepsake", dailyCapScope = "server", revision = Shop.revision() })
local badBatch = cmd(boss, "admin.catalog", { action = "batch", ids = { "keepsake", "crate" },
    fields = { dailyCapScope = "daily" }, revision = Shop.revision() })
check(badSet.error == "invalid_args" and badBatch.error == "invalid_args"
    and Shop.sku("keepsake").dailyCapScope == "lifetime"
    and table.concat(files[Shop.FILE].lines, "\n") == disk,
    "there are exactly three modes: an invented scope is refused by the single edit and by the batch without touching the file")
files[Shop.FILE] = { lines = { EC.jsonEncode({ items = {
    { id = "keepsake", item = "Base.Bandage", qty = 1, dailyCap = 1, dailyCapScope = "daily",
        prices = { survivor = { price = 10 } } },
} }) }, opens = 0 }
local reload = cmd(boss, "admin.catalog", { action = "reload" })
check(reload.error == "catalog_invalid" and Shop.sku("keepsake").dailyCap == 5
    and Shop.sku("keepsake").dailyCapScope == "lifetime" and Shop.used("lc-zed", "keepsake", nowMs) == 3,
    "a catalog file naming a mode the shop does not have keeps the previous rows instead of becoming unlimited")
onlinePlayers = {}
end)()

-- ===== 累積在線簽到：晚領不推遲門檻，設定即時重算且不重發 =====
io.write("scenario cumulative check-in: late claims, live settings and payment boundaries\n")
;(function()
modDataStore[EC.MODDATA_KEY] = nil
files, sentCommands = {}, {}
SandboxVars.MinidoracatEconomy.RewardDayResetHour = 0
SandboxVars.MinidoracatEconomy.RewardTimezoneUTC = 8
SandboxVars.MinidoracatEconomy.CheckinAmount = 30
SandboxVars.MinidoracatEconomy.CheckinMinPlaytimeMinutes = 15
SandboxVars.MinidoracatEconomy.CheckinDailyLimit = 2
SandboxVars.MinidoracatEconomy.CheckinIntervalMinutes = 60
SandboxVars.MinidoracatEconomy.CheckinServerDailyCap = 0
nowMs = R.dayStartMs(1788699986478) + 3600000
fire("OnServerStarted")
local late, waiting, boss = fakePlayer("cum-late"), fakePlayer("cum-waiting"), fakePlayer("cum-admin")
boss.role = "admin"
onlinePlayers = { late, waiting, boss }
R.observe(late, nowMs)
R.observe(waiting, nowMs)
local serial = 0
local function cmd(player, name, args)
    serial = serial + 1
    args = args or {}
    args.requestId = args.requestId or ("cum-" .. serial)
    S.handlers[name](player, args)
    return lastSent(name).args
end
local function take(player, index)
    return cmd(player, "rewards.checkin", { day = R.dayKey(nowMs), rewardIndex = index })
end
local function option(key, value)
    return cmd(boss, "admin.option", { key = key, value = value })
end
local function tick(minutes)
    for _ = 1, minutes do nowMs = nowMs + 60000; fire("OnTickEvenPaused") end
end
tick(39)
local first = take(late, 1)
check(first.ok and first.state.requiredOnlineMs == 60 * 60000
    and first.state.remainingOnlineMs == 21 * 60000,
    "claiming the first reward at minute 39 leaves 21 minutes, not another hour")
-- 舊存檔的領取基準不再控制資格；重新初始化不能丟失當日時間或已領次數。
S.modData().claims["cum-late"].claimBasePlayedMs = 39 * 60000
fire("OnServerStarted")
local resumed = cmd(late, "rewards.state")
check(resumed.claimedCount == 1 and resumed.playedMs == 39 * 60000
    and resumed.requiredOnlineMs == 60 * 60000,
    "reinitialising an old interval record preserves progress but no longer postpones its next reward")
local lookup = cmd(boss, "admin.lookup", { username = "cum-late" })
check(lookup.ok and lookup.rewards.requiredOnlineMs == resumed.requiredOnlineMs,
    "the administrative read-only view uses the same cumulative threshold as the player")
R.observe(waiting, nowMs)
tick(21)
local deferredFirst, deferredSecond = take(waiting, 1), take(waiting, 2)
check(deferredFirst.ok and deferredFirst.state.canClaim and deferredSecond.ok
    and L.getBalance("cum-waiting", "survivor").available == 60,
    "at minute 60 a player who never claimed can take both earned rewards in order")
local replay, excess = take(waiting, 1), take(waiting, 3)
check(replay.error == "stale_request" and excess.error == "daily_limit_reached"
    and L.getBalance("cum-waiting", "survivor").available == 60,
    "banked eligibility neither replays a paid index nor bypasses the daily limit")
local raised = option("CheckinIntervalMinutes", 120)
local pushed = lastSent("rewards.state").args
check(raised.ok and pushed.intervalMs == 120 * 60000
    and R.state("cum-late", nowMs).remainingOnlineMs == 60 * 60000,
    "raising the cumulative step updates live snapshots and the unpaid threshold immediately")
check(take(late, 2).error == "interval_not_elapsed" and L.getBalance("cum-late", "survivor").available == 30,
    "an already open claim is checked against the new longer step without consuming it")
local lowered = option("CheckinIntervalMinutes", 30)
local second = take(late, 2)
check(lowered.ok and second.ok and second.state.requiredOnlineMs == 60 * 60000
    and L.getBalance("cum-late", "survivor").available == 60,
    "lowering the step unlocks the unpaid second reward and keeps the third threshold at twice the step")
local expanded = option("CheckinDailyLimit", 3)
local third = take(late, 3)
check(expanded.ok and third.ok and third.state.claimedCount == 3
    and L.getBalance("cum-late", "survivor").available == 90,
    "raising today's limit exposes an already earned third reward without restarting its clock")
local reduced = option("CheckinDailyLimit", 1)
check(reduced.ok and take(late, 4).error == "daily_limit_reached"
    and L.getBalance("cum-late", "survivor").available == 90,
    "lowering the daily limit neither claws back money nor resets paid indices")
option("CheckinDailyLimit", 3)
local high = fakePlayer("cum-high")
onlinePlayers = { high }
R.observe(high, nowMs)
option("CheckinMinPlaytimeMinutes", 90)
tick(60)
check(take(high, 1).error == "not_enough_playtime",
    "a first threshold above the step remains a real minimum, not a shortcut through later rewards")
tick(30)
local highFirst, highSecond = take(high, 1), take(high, 2)
check(highFirst.ok and highFirst.state.requiredOnlineMs == 90 * 60000 and highSecond.ok,
    "later thresholds never fall below the configured first minimum, and time already earned still counts")
local free = fakePlayer("cum-zero")
onlinePlayers = { free }
R.observe(free, nowMs)
local zero = option("CheckinMinPlaytimeMinutes", 0)
local immediate = take(free, 1)
check(zero.ok and immediate.ok and immediate.state.requiredOnlineMs == 30 * 60000
    and take(free, 2).error == "interval_not_elapsed",
    "zero permits only the first claim at login; the following claim still needs the configured step")
local restored = option("CheckinIntervalMinutes", nil)
check(restored.ok and R.state("cum-zero", nowMs).requiredOnlineMs == 60 * 60000,
    "clearing the runtime override restores the sandbox step rather than a hardcoded threshold")
option("CheckinMinPlaytimeMinutes", 15)
option("CheckinDailyLimit", 2)
onlinePlayers = { late }
R.observe(late, nowMs)
nowMs = R.nextResetMs(nowMs) + 1000
local newDay = cmd(late, "rewards.state")
check(newDay.claimedCount == 0 and newDay.playedMs == 1000 and newDay.requiredOnlineMs == 15 * 60000,
    "a new reward day discards banked eligibility and counts only its own connected time")
check(take(late, 1).error == "not_enough_playtime" and L.getBalance("cum-late", "survivor").available == 90,
    "yesterday's unused online time cannot pay today's first reward")
check(L.conservation("survivor") == 0,
    "cumulative claims and runtime changes preserve ledger conservation")
SandboxVars.MinidoracatEconomy.CheckinDailyLimit = nil
SandboxVars.MinidoracatEconomy.CheckinIntervalMinutes = nil
SandboxVars.MinidoracatEconomy.CheckinAmount = nil
SandboxVars.MinidoracatEconomy.CheckinMinPlaytimeMinutes = nil
onlinePlayers = {}
end)()

-- ===== 通用權益 rev 2（情境在 scripts/test_entitlements.lua；共用本檔的假全域與 check）=====
do
    local run = loadfile("scripts/test_entitlements.lua")
    if run == nil then
        check(false, "scripts/test_entitlements.lua loads")
    else
        run({ check = check, fire = fire, fakePlayer = fakePlayer, lastSent = lastSent,
            now = function() return nowMs end, setNow = function(v) nowMs = v end,
            files = function() return files end, clearFiles = function() files = {} end,
            writerDeny = function() return writerDeny end, clearSent = function() sentCommands = {} end,
            setOnline = function(list) onlinePlayers = list end, store = function() return modDataStore end })
    end
end

-- ===== 玩家之間轉帳（ECTransfer；docs/design-proposals/player-transfer.md §2–§3）=====
-- 每個拒絕都用 state() 證明零變更：餘額＋rev、每日桶、最近對象與 meta.seq（任何 L.post 都會推進它）。
;(function()
io.write("scenario: player-to-player transfer\n")
local Tr, G, V, A = EC.Transfer, EC.Integration, EC.v1, EC.Admin
local SV = SandboxVars.MinidoracatEconomy
local savedRoles = SV.AdminRoles
SV.AdminRoles = "admin"
SV.RewardDayResetHour, SV.RewardTimezoneUTC = 4, 8
modDataStore[EC.MODDATA_KEY] = nil
files, writerDeny, sentCommands = {}, {}, {}
worldSprites = { ["100,200,0"] = "MinidoracatEconomy_terminal_0" }
nowMs = 1788699986478                         -- 2026-09-06 13:46 台灣；換日 20:00 UTC
fire("OnServerStarted")
local admin = fakePlayer("xf-admin"); admin.role = "admin"
local ann, cat, newbie = fakePlayer("xf-ann"), fakePlayer("xf-cat"), fakePlayer("xf-new")
onlinePlayers = { admin, ann, cat, newbie }
local function cmd(p, command, args)
    nowMs = nowMs + 700
    local before = #sentCommands
    fire("OnClientCommand", EC.COMMAND_MODULE, command, p, args or {})
    for i = before + 1, #sentCommands do
        local r = sentCommands[i]
        if r.player == p and r.command == command then return r.args end
    end
    return nil
end
local function bal(u) return L.getBalance(u, "survivor").available end
local function state()
    local md = S.modData()
    local parts = {}
    for _, u in ipairs({ "xf-ann", "xf-bob", "xf-cat", "xf-new", "xf-rich", "SYSTEM_BURN" }) do
        local b = L.getBalance(u, "survivor")
        parts[#parts + 1] = u .. "=" .. b.available .. "/" .. b.rev
    end
    parts[#parts + 1] = EC.jsonEncode(md.transferDaily)
    parts[#parts + 1] = EC.jsonEncode(md.transferRecent)
    parts[#parts + 1] = tostring(md.meta.seq)
    return table.concat(parts, ";")
end
local serial = 0
local function send(p, to, amount, fee, extra)
    serial = serial + 1
    local args = { to = to, currency = "survivor", amount = amount, fee = fee, requestId = "xf-" .. serial }
    for k, v in pairs(extra or {}) do args[k] = v end
    return cmd(p, "wallet.transfer", args)
end
-- refused with `code` and nothing changed
local function refused(res, code, before)
    return res ~= nil and res.ok == false and res.error == code and state() == before
end

check(V.API_REVISION == 3 and V.CAPABILITIES.transfer == true and type(V.transfer) == "function"
    and V.CAPABILITIES.entitlements == true and V.CAPABILITIES.post == true,
    "the facade is rev 3 with transfer once ECTransfer has loaded; rev 1 and rev 2 capabilities stay")

-- 1. 遷移：這一版第一次開機前經濟已知的帳號（錢包、領獎紀錄、凍結紀錄）一律視為夠老
L.credit("xf-ann", "survivor", 2000, "SYSTEM_MINT", { requestId = "xf-seed-ann", reasonCode = "t" })
L.credit("xf-bob", "survivor", 100, "SYSTEM_MINT", { requestId = "xf-seed-bob", reasonCode = "t" })
S.modData().claims["xf-claimer"] = { day = nil, playedMs = 0, claimedCount = 0, paid = {}, milestones = 0 }
S.modData().frozen["xf-iced"] = { at = nowMs, by = "xf-admin" }
S.modData().firstSeen = nil                  -- 存檔來自沒有轉帳的舊版
local preVersion = proofSnapshot()
nowMs = nowMs + 1000
fire("OnServerStarted")
local seen = S.modData().firstSeen
check(seen["xf-ann"] == 0 and seen["xf-bob"] == 0 and seen["xf-claimer"] == 0 and seen["xf-iced"] == 0
    and seen.SYSTEM_MINT == nil and seen["xf-new"] == nil,
    "the first boot of this build grandfathers wallets, claim records and freeze marks, never a system account")
cmd(ann, "hello"); cmd(cat, "hello")
local firstNew = nowMs + 700
cmd(newbie, "hello")
check(seen["xf-ann"] == 0 and seen["xf-new"] == firstNew and seen["xf-cat"] == firstNew - 700,
    "hello starts the clock of an account the economy did not know, and never resets a grandfathered one")
cmd(admin, "terminal.register", { x = 100, y = 200, z = 0 })

-- 2. 預設全關：功能關、幣別關都拒絕，且不動帳
local info0 = cmd(ann, "transfer.info", { requestId = "i0" })
check(info0.requestId == "i0" and info0.enabled == false and #info0.currencies == 0 and info0.feePercent == 5
    and info0.min == 1 and info0.maxPerTx == 5000 and info0.dailyLimit == 10000 and info0.remote == false,
    "transfer.info reports the defaults: off, 5%, 1..5000, 10000 a day, terminal required")
local s0 = state()
check(refused(send(ann, "xf-bob", 100, 5), "transfer_disabled", s0), "the feature is off by default and a refusal changes nothing")
SV.TransferEnabled = true
check(refused(send(ann, "xf-bob", 100, 5), "currency_not_transferable", s0),
    "with the feature on, a currency whose directTransfer is off still refuses")
check(cmd(ann, "admin.config", { currency = "survivor", field = "directTransfer", value = true, reason = "x" }).error == "forbidden"
    and Cfg.currency("survivor").directTransfer == false,
    "only the write role may open a currency for transfers")
check(cmd(admin, "admin.config", { currency = "survivor", field = "directTransfer", value = "yes", reason = "x" }).error == "invalid_args",
    "directTransfer takes a boolean only")
local opened = cmd(admin, "admin.config", { currency = "survivor", field = "directTransfer", value = true, reason = "open", requestId = "c1" })
proofSettle()
local auditLine = false
for _, f in pairs(files) do for _, l in ipairs(f.lines) do
    if string.find(l, '"field":"directTransfer"', 1, true) and string.find(l, '"action":"config"', 1, true) then auditLine = true end
end end
check(opened.ok and opened.requestId == "c1" and opened.currencies[1].directTransfer == true and opened.currencies[2].directTransfer == false
    and Cfg.currency("survivor").directTransfer == true and auditLine,
    "admin.config directTransfer is applied per currency, reported in the snapshot and audited")
local info1 = cmd(ann, "transfer.info")
check(info1.enabled and #info1.currencies == 1 and info1.currencies[1] == "survivor" and info1.atTerminal == true
    and info1.sentToday == 0 and info1.remainingToday == 10000 and info1.readyAt == nil,
    "transfer.info lists only transferable currencies and a grandfathered account is ready")

-- 3. 成功：三條分錄、守恆、雙方收據、只推給收款人
sentCommands = {}
local ok1 = send(ann, "xf-cat", 100, 5, { memo = "fare", requestId = "pay-1" })
check(ok1.ok and ok1.requestId == "pay-1" and ok1.to == "xf-cat" and ok1.amount == 100 and ok1.fee == 5 and ok1.total == 105
    and ok1.balance == 1895 and ok1.sentToday == 100 and ok1.remainingToday == 9900 and bal("xf-cat") == 100
    and bal("SYSTEM_BURN") == 5,
    "a transfer moves amount+fee from the payer, the amount to the payee and burns the fee")
check(L.conservation("survivor") == 0, "conservation holds after a transfer")
proofSettle()
local tx = nil
for _, f in pairs(files) do for _, l in ipairs(f.lines) do
    local row = string.find(l, ok1.txId, 1, true) and EC.jsonDecode(l)
    if type(row) == "table" and row.type == "tx.committed" then tx = row end
end end
check(tx and tx.kind == "transfer" and tx.reasonCode == "player_transfer" and tx.reasonText == "fare" and #tx.postings == 3
    and tx.postings[1].account == "xf-ann" and tx.postings[1].amount == -105
    and tx.postings[2].account == "xf-cat" and tx.postings[2].amount == 100
    and tx.postings[3].account == "SYSTEM_BURN" and tx.postings[3].amount == 5
    and tx.payload.from == "xf-ann" and tx.payload.to == "xf-cat" and tx.payload.memo == "fare",
    "one tx.committed of kind transfer with payer, payee, burn postings in that order and the memo in the payload")
local ra, rc = L.receipts("xf-ann"), L.receipts("xf-cat")
check(ra[#ra].kind == "transfer" and ra[#ra].counterparty == "xf-cat" and ra[#ra].amount == -105 and ra[#ra].reasonText == "fare"
    and rc[#rc].counterparty == "xf-ann" and rc[#rc].amount == 100 and rc[#rc].reasonText == "fare",
    "both receipts name the other party and carry the memo")
local payerLine, payeeLine = nil, nil
for _, f in pairs(files) do for _, l in ipairs(f.lines) do
    local row = string.find(l, ok1.txId, 1, true) and EC.jsonDecode(l)
    if type(row) == "table" and row.type == "transfer" then
        if row.delta == -105 then payerLine = row elseif row.delta == 100 then payeeLine = row end
    end
end end
local wr = W.state("xf-ann").receipts
check(ra[#ra].fee == 5 and rc[#rc].fee == nil and payerLine and payerLine.fee == 5 and payeeLine and payeeLine.fee == nil
    and wr[#wr].fee == 5,
    "the fee rides on the sender's receipt (ring, receipt file, wallet.state) and never on the recipient's")
local pushed, pushedToPayer = nil, false
for _, r in ipairs(sentCommands) do
    if r.command == "wallet.transferReceived" then
        if r.player == cat then pushed = r.args else pushedToPayer = true end
    end
end
check(pushed and pushed.from == "xf-ann" and pushed.amount == 100 and pushed.memo == "fare" and pushed.txId == ok1.txId
    and pushed.balance == 100 and pushed.currency == "survivor" and not pushedToPayer and lastSent("wallet.changed") ~= nil,
    "the online recipient alone gets wallet.transferReceived, next to the usual wallet.changed push")

-- 4. 冪等：同 requestId 同內容回原結果；換內容回 request_conflict
local s1 = state()
local dup = send(ann, "xf-cat", 100, 5, { memo = "fare", requestId = "pay-1" })
check(dup.ok and dup.duplicate == true and dup.txId == ok1.txId and dup.fee == 5 and dup.total == 105 and state() == s1,
    "a resend returns the recorded result and moves nothing")
check(refused(send(ann, "xf-cat", 101, 6, { memo = "fare", requestId = "pay-1" }), "request_conflict", s1)
    and refused(send(ann, "xf-cat", 100, 5, { requestId = "pay-1" }), "request_conflict", s1),
    "the same requestId with another amount or without the memo is a conflict, not a second payment")

-- 5. 拒絕全都零變更
check(refused(send(ann, "xf-ann", 10, 1), "self_transfer", s1), "sending to yourself is refused")
check(refused(send(ann, "nobody", 10, 1), "unknown_recipient", s1) and S.modData().wallets.nobody == nil,
    "an account the economy never knew is refused and gets no wallet row")
check(refused(send(ann, "XF-BOB", 10, 1), "unknown_recipient", s1), "account names match exactly: case counts")
check(refused(send(ann, "SYSTEM_BURN", 10, 1), "unknown_recipient", s1)
    and refused(send(ann, "MOD:XferMod", 10, 1), "unknown_recipient", s1),
    "system and MOD accounts are never recipients")
S.modData().frozen["xf-ann"] = { at = nowMs }
ann.x = 500
check(refused(send(ann, "xf-bob", 10, 1), "account_frozen", s1), "a frozen payer cannot send, and is told so before the terminal rule")
ann.x = 100
S.modData().frozen["xf-ann"] = nil
check(refused(send(ann, "xf-iced", 10, 1), "recipient_frozen", s1), "a frozen recipient cannot receive")
ann.x = 500
check(refused(send(ann, "xf-bob", 10, 1), "not_at_terminal", s1), "with TransferRemote off a transfer needs a terminal")
SV.TransferRemote = true
local remote = send(ann, "xf-bob", 10, 1)
check(remote.ok and bal("xf-bob") == 110 and cmd(ann, "transfer.info").remote == true and cmd(ann, "transfer.info").atTerminal == false,
    "with TransferRemote on the same transfer goes through away from any terminal")
SV.TransferRemote = nil
ann.x = 100
local s2 = state()
SV.TransferMin = 10
local low = send(ann, "xf-bob", 9, 1)
local high = send(ann, "xf-bob", 5001, 251)
check(refused(low, "amount_range", s2) and low.min == 10 and low.max == 5000 and refused(high, "amount_range", s2),
    "amounts outside TransferMin..TransferMaxPerTx are refused with the range")
SV.TransferMin = nil
local changed = send(ann, "xf-bob", 100, 4)
check(refused(changed, "fee_changed", s2) and changed.feeNow == 5 and changed.fee == 4,
    "a fee the player did not confirm is refused with the current fee")
local poor = send(ann, "xf-bob", 5000, 250)
check(refused(poor, "insufficient_funds", s2) and poor.needed == 5250 - bal("xf-ann"),
    "insufficient funds says how much is missing")
check(refused(send(ann, "xf-bob", 10, 1, { memo = string.rep("m", 65) }), "invalid_args", s2)
    and refused(send(ann, "xf-bob", 10, 1, { memo = "a\nb" }), "invalid_args", s2)
    and refused(send(ann, "xf-bob", 0, 0), "invalid_args", s2) and refused(send(ann, "xf-bob", 10, -1), "invalid_args", s2),
    "a memo over 64 characters or with control characters, a zero amount and a negative fee are malformed")
local longName = fakePlayer(string.rep("L", 60)); onlinePlayers[#onlinePlayers + 1] = longName
-- its session starts (and takes a seq for its anchor) before the refusal is measured
fire("OnClientCommand", EC.COMMAND_MODULE, "hello", longName, {})
local s3 = state()
check(send(longName, "xf-bob", 10, 1, { requestId = string.rep("r", 90) }).error == "request_too_long" and state() == s3,
    "an idempotency key the ledger cannot store is refused before anything moves")

-- 6. 手續費：無條件進位、開啟時最少 1；0% 時沒有銷毀分錄
check(Tr.fee(1, 5) == 1 and Tr.fee(20, 5) == 1 and Tr.fee(21, 5) == 2 and Tr.fee(100, 5) == 5 and Tr.fee(5000, 50) == 2500
    and Tr.fee(1, 0) == 0 and Tr.fee(999, 1) == 10,
    "fee = ceil(amount * pct / 100), at least 1 while on, 0 when off")
local one = send(ann, "xf-bob", 1, 1)
check(one.ok and one.fee == 1 and one.total == 2, "the minimum fee of 1 applies to the smallest transfer")
SV.TransferFeePercent = 0
local burnBefore = bal("SYSTEM_BURN")
local free = send(ann, "xf-bob", 50, 0)
proofSettle()
local freeTx = nil
for _, f in pairs(files) do for _, l in ipairs(f.lines) do
    local row = string.find(l, free.txId, 1, true) and EC.jsonDecode(l)
    if type(row) == "table" and row.type == "tx.committed" then freeTx = row end
end end
check(free.ok and free.total == 50 and bal("SYSTEM_BURN") == burnBefore and freeTx and #freeTx.postings == 2,
    "with a 0% fee the transaction has no burn posting")
SV.TransferFeePercent = nil

-- 7. 每日轉出上限：剛好用完可以、超過一元不行；獎勵日換日歸零
SV.TransferDailyPerAccount = 300
local used = Tr.sentOn(R.dayKey(nowMs), "xf-ann")          -- 100 + 10 + 1 + 50
local s3 = state()
local over = send(ann, "xf-bob", 300 - used + 1, Tr.fee(300 - used + 1, 5))
check(refused(over, "daily_limit", s3) and over.remainingToday == 300 - used,
    "one coin over the daily limit is refused with what is left today")
local exact = send(ann, "xf-bob", 300 - used, Tr.fee(300 - used, 5))
check(exact.ok and exact.sentToday == 300 and exact.remainingToday == 0, "the daily limit can be used up exactly")
local s4 = state()
local after = send(ann, "xf-bob", 1, 1)
check(refused(after, "daily_limit", s4) and after.remainingToday == 0, "nothing more once the day's limit is used")
nowMs = R.nextResetMs(nowMs) + 1000
local info2 = cmd(ann, "transfer.info")
local nextDay = send(ann, "xf-bob", 1, 1)
check(info2.sentToday == 0 and info2.remainingToday == 300 and nextDay.ok and nextDay.sentToday == 1,
    "the next reward day starts from zero")
SV.TransferDailyPerAccount = 0
check(cmd(ann, "transfer.info").remainingToday == nil and cmd(ann, "transfer.info").dailyLimit == 0,
    "a daily limit of 0 is unlimited and reports no remaining figure")
SV.TransferDailyPerAccount = nil

-- 8. 收款人上限：不透露對方餘額
SV.BalanceMax = 1000
L.credit("xf-bob", "survivor", 950 - bal("xf-bob"), "SYSTEM_MINT", { requestId = "xf-fill-bob", reasonCode = "t" })
local s5 = state()
local capped = send(ann, "xf-bob", 51, 3)
local leaks = false
for k, v in pairs(capped) do if v == 950 or k == "balance" then leaks = true end end
check(refused(capped, "recipient_cap", s5) and not leaks, "a payment that would lift the recipient over the cap is refused without their balance")
check(send(ann, "xf-bob", 50, 3).ok and bal("xf-bob") == 1000, "exactly up to the recipient's cap is allowed")
SV.BalanceMax = nil

-- 9. 餘額剛好等於本金＋手續費
L.credit("xf-new", "survivor", 105, "SYSTEM_MINT", { requestId = "xf-seed-new", reasonCode = "t" })
SV.TransferMinAccountDays = 0
local all = send(newbie, "xf-ann", 100, 5)
check(all.ok and all.balance == 0 and bal("xf-new") == 0, "a balance of exactly amount + fee is enough")
SV.TransferMinAccountDays = nil

-- 10. 新帳號門檻
L.credit("xf-new", "survivor", 500, "SYSTEM_MINT", { requestId = "xf-seed-new2", reasonCode = "t" })
local s6 = state()
local young = send(newbie, "xf-ann", 10, 1)
check(refused(young, "account_too_new", s6) and young.availableAt == firstNew + 3 * 86400000
    and cmd(newbie, "transfer.info").readyAt == firstNew + 3 * 86400000,
    "an account first seen after the upgrade waits TransferMinAccountDays, and both replies say until when")
local ghost = fakePlayer("xf-ghost"); onlinePlayers[#onlinePlayers + 1] = ghost
L.credit("xf-ghost", "survivor", 100, "SYSTEM_MINT", { requestId = "xf-seed-ghost", reasonCode = "t" })
local skipped = send(ghost, "xf-ann", 10, 1)
check(skipped.error == "account_too_new" and skipped.availableAt == nowMs + 3 * 86400000 and S.modData().firstSeen["xf-ghost"] == nil,
    "skipping hello never skips the wait: an unseen account has not started its clock")

-- 11. 回滾重跑遷移：回到舊版存檔再開機，只會得到同一批或更少的豁免帳號
local afterMigration = proofSnapshot()
proofRestartFrom(preVersion)
seen = S.modData().firstSeen
check(seen["xf-ann"] == 0 and seen["xf-bob"] == 0 and seen["xf-claimer"] == 0 and seen["xf-iced"] == 0 and seen["xf-new"] == nil
    and seen["xf-cat"] == nil,
    "a rollback to the pre-upgrade save re-runs the migration over that save's population only")
local reseen = nowMs + 700
cmd(newbie, "hello")
check(seen["xf-new"] == reseen and reseen > firstNew and cmd(newbie, "transfer.info").readyAt == reseen + 3 * 86400000,
    "an account first seen in the lost branch starts again later: a rollback makes the wait longer, never shorter")
proofRestartFrom(afterMigration)
check(S.modData().firstSeen["xf-new"] == firstNew and S.modData().firstSeen["xf-ann"] == 0,
    "an ordinary restart keeps the recorded ages and never grandfathers again")
nowMs = firstNew + 3 * 86400000 + 1
local grown = send(newbie, "xf-ann", 10, 1)
check(grown.ok, "once the wait is over the account can send")

-- 12. 候選收款人
local crowd = {}
for i = 1, 25 do crowd[i] = fakePlayer(string.format("xf-p%02d", i)) end
onlinePlayers = { admin, ann, cat, newbie }
for _, p in ipairs(crowd) do onlinePlayers[#onlinePlayers + 1] = p end
local rc1 = cmd(ann, "transfer.recipients", { query = "XF-", requestId = "q1" })
local names, selfListed = {}, false
for _, it in ipairs(rc1.items) do names[it.username] = it.online; if it.username == "xf-ann" then selfListed = true end end
check(rc1.requestId == "q1" and #rc1.items == 20 and not selfListed and names["xf-bob"] == false and names["xf-cat"] == true,
    "recipients: recent counterparties (offline ones flagged) and online name matches, case-insensitive, never yourself, at most 20")
local exactOffline = cmd(ann, "transfer.recipients", { query = "xf-claimer" })
local wrongCase = cmd(ann, "transfer.recipients", { query = "XF-CLAIMER" })
check(#exactOffline.items == 1 and exactOffline.items[1].username == "xf-claimer" and exactOffline.items[1].online == false
    and #wrongCase.items == 0 and #cmd(ann, "transfer.recipients", { query = "SYSTEM_BURN" }).items == 0,
    "an offline account is only found by its exact name, and system accounts never")
SV.TransferEnabled = nil
check(#cmd(ann, "transfer.recipients", { query = "xf" }).items == 0, "with the feature off no candidates are listed")
SV.TransferEnabled = true
onlinePlayers = { admin, ann, cat, newbie }

-- 13. 整合 API：沒有 allowTransfer 就拒絕；有了之後同一套規則
local src = V.registerSource({ modId = "XferMod", currencies = { "survivor" }, reasonCodes = { "rent" } })
fire("OnTickEvenPaused")
local s7 = state()
local denied = src.transfer("xf-ann", "xf-bob", "survivor", 50, { requestId = "rent-1", reasonCode = "rent" })
local todayRow = S.modData().sourceDaily[R.dayKey(nowMs)]
check(denied.ok == false and denied.error == "transfer_not_allowed" and state() == s7
    and todayRow and todayRow.XferMod.rejected.transfer_not_allowed == 1,
    "a source may not transfer until the host sets allowTransfer, and the refusal is counted")
check(cmd(admin, "admin.sources", { action = "set", modId = "XferMod", allowTransfer = "yes", reason = "rent" }).error == "invalid_args",
    "allowTransfer takes a boolean only")
local setRes = cmd(admin, "admin.sources", { action = "set", modId = "XferMod", allowTransfer = true, reason = "safehouse rent" })
local listed = nil
for _, row in ipairs(setRes.sources) do if row.modId == "XferMod" then listed = row end end
check(setRes.ok and listed and listed.allowTransfer == true, "admin.sources sets allowTransfer and lists it")
fire("OnTickEvenPaused")
local rent = src.transfer("xf-ann", "xf-bob", "survivor", 50, { requestId = "rent-1", reasonCode = "rent", reasonText = "week 1" })
proofSettle()
local rentTx = nil
for _, f in pairs(files) do for _, l in ipairs(f.lines) do
    local row = rent.txId and string.find(l, rent.txId, 1, true) and EC.jsonDecode(l)
    if type(row) == "table" and row.type == "tx.committed" then rentTx = row end
end end
check(rent.ok and rent.fee == 3 and rent.duplicate == false and rentTx and rentTx.kind == "transfer" and rentTx.reasonCode == "rent"
    and rentTx.payload.sourceMod == "XferMod" and rentTx.payload.from == "xf-ann" and rentTx.payload.memo == nil
    and L.conservation("survivor") == 0,
    "an allowed source transfers player to player with the fee, under its own reason code and name")
local s8 = state()
local again = V.transfer("xf-ann", "xf-bob", "survivor", 50, { modId = "XferMod", requestId = "rent-1", reasonCode = "rent", reasonText = "week 1" })
check(again.ok and again.duplicate == true and again.txId == rent.txId and state() == s8
    and src.transfer("xf-ann", "xf-bob", "survivor", 60, { requestId = "rent-1", reasonCode = "rent" }).error == "request_conflict"
    and src.post({ requestId = "rent-1", reasonCode = "rent", postings = { { account = "xf-ann", currency = "survivor", amount = -1 },
        { account = "MOD:XferMod", currency = "survivor", amount = 1 } } }).error == "request_conflict"
    and state() == s8,
    "the top-level E.transfer resends idempotently; the same id for another amount or a post is a conflict")
check(src.transfer("xf-ann", "xf-iced", "survivor", 10, { requestId = "rent-2", reasonCode = "rent" }).error == "recipient_frozen"
    and src.transfer("xf-ghost", "xf-ann", "survivor", 10, { requestId = "rent-3", reasonCode = "rent" }).error == "account_too_new"
    and src.transfer("xf-ann", "xf-ann", "survivor", 10, { requestId = "rent-4", reasonCode = "rent" }).error == "self_transfer"
    and src.transfer("xf-ann", "xf-bob", "survivor", 10, { requestId = "rent-5", reasonCode = "nope" }).error == "invalid_args"
    and state() == s8,
    "the API applies the player rules (freeze, account age, self) and its own reason codes, changing nothing")
G.setSource("XferMod", { enabled = false }, "xf-admin", "pause")
local s8b = state()                          -- the audit line of that switch has its own id
check(src.transfer("xf-ann", "xf-bob", "survivor", 10, { requestId = "rent-6", reasonCode = "rent" }).error == "source_disabled" and state() == s8b,
    "a disabled source cannot transfer")
G.setSource("XferMod", { enabled = true }, "xf-admin", "resume")
fire("OnTickEvenPaused")
local limited = nil
for i = 1, G.CALLS_PER_TICK + 1 do
    limited = src.transfer("xf-ann", "xf-bob", "survivor", 1, { requestId = "burst-" .. i, reasonCode = "rent" })
end
check(limited.error == "rate_limited" and Tr.sentOn(R.dayKey(nowMs), "xf-ann") == 50 + G.CALLS_PER_TICK,
    "a source's calls per tick are capped for transfers like for every other call")

-- 14. 玩家端節流：500 ms 內的第二筆沒有回覆也不動帳
fire("OnTickEvenPaused")
local s9 = state()
local before = #sentCommands
fire("OnClientCommand", EC.COMMAND_MODULE, "wallet.transfer", ann, { to = "xf-bob", currency = "survivor", amount = 5, fee = 1, requestId = "t-1" })
nowMs = nowMs + 100
fire("OnClientCommand", EC.COMMAND_MODULE, "wallet.transfer", ann, { to = "xf-bob", currency = "survivor", amount = 5, fee = 1, requestId = "t-2" })
local replies = 0
for i = before + 1, #sentCommands do if sentCommands[i].command == "wallet.transfer" then replies = replies + 1 end end
check(replies == 1 and Tr.sentOn(R.dayKey(nowMs), "xf-ann") == 50 + G.CALLS_PER_TICK + 5 and state() ~= s9,
    "a second transfer within the command cooldown is dropped: only the first one is answered and booked")
check(A.TX_GROUPS.transfer == true and L.conservation("survivor") == 0 and L.conservation("cat") == 0,
    "the transactions page can filter transfers and every currency is still conserved")

SV.TransferEnabled, SV.AdminRoles = nil, savedRoles
SV.RewardDayResetHour, SV.RewardTimezoneUTC = nil, nil
onlinePlayers = {}
end)()

;(function()
-- 市場／拍賣拒絕碼：之前沒有任何 assertion 點名的分支。每一條都走 client 用的 OnClientCommand，
-- 驗錯誤碼，並驗整體狀態（餘額含保留款、刊登／拍賣數、背包、pending、信箱）一點都沒動。
io.write("scenario EC: market and auction refusals move nothing\n")
local Mk, Au, M = S.Market, S.Auction, S.Mailbox
local KEY = EC.PLAYER_MODDATA_KEY
modDataStore[EC.MODDATA_KEY] = nil
files = {}
sentCommands = {}
nowMs = nowMs + 61000
fire("OnServerStarted")
local boss = fakePlayer("boss"); boss.role = "admin"
local ann = fakePlayer("ann"); ann.x, ann.y = 101, 200; ann.inventory = fakeInventory(50)
local bob = fakePlayer("bob"); bob.x, bob.y = 101, 201; bob.inventory = fakeInventory(50)
onlinePlayers = { boss, ann, bob }
worldSprites = { ["100,200,0"] = "MinidoracatEconomy_catgirl_0" }
local function cmd(who, name, args)
    nowMs = nowMs + 600
    args.requestId = args.requestId or (name .. nowMs)
    withCurrency(name, args)
    sentCommands = {}
    fire("OnClientCommand", EC.COMMAND_MODULE, name, who, args)
    local s = lastSent(name)
    return s and s.args or {}
end
cmd(boss, "terminal.register", { x = 100, y = 200, z = 0, kind = "trade" })
L.credit("ann", "survivor", 500, "SYSTEM_MINT", { requestId = "ec-ann", reasonCode = "t" })
L.credit("bob", "survivor", 500, "SYSTEM_MINT", { requestId = "ec-bob", reasonCode = "t" })
local function state()
    local md = S.modData()
    local parts = { md.market.count, md.auctions.count, Mk.ownerCount("ann"), Au.ownerCount("ann"),
        M.unclaimed("ann"), M.unclaimed("bob"), ann.inventory.count(), bob.inventory.count(), L.conservation("survivor") }
    for _, u in ipairs({ "ann", "bob", "SYSTEM_BURN" }) do
        local b = L.getBalance(u, "survivor")
        parts[#parts + 1] = b.available .. "/" .. b.reserved
    end
    for _, p in ipairs({ ann, bob }) do parts[#parts + 1] = EC.countKeys(p.modData[KEY] and p.modData[KEY].pendingOuts or {}) end
    for id, a in pairs(md.auctions.items) do parts[#parts + 1] = id .. ":" .. tostring(a.bids) .. ":" .. tostring(a.highest and a.highest.amount) end
    return table.concat(parts, ",")
end
local axe = instanceItem("Base.Axe"); ann.inventory:AddItem(axe)
local saw = instanceItem("Base.Saw"); ann.inventory:AddItem(saw)
local bobs = instanceItem("Base.Hammer"); bob.inventory:AddItem(bobs)
-- item_not_found: an id that is not a top-level item of this backpack (here: someone else's hammer)
local s0 = state()
check(cmd(ann, "market.list", { itemId = bobs.id, price = 50 }).error == "item_not_found" and state() == s0,
    "listing an item id that is not in the seller's backpack is item_not_found and moves nothing")
check(cmd(ann, "auction.create", { itemId = bobs.id, startPrice = 50, hours = 24 }).error == "item_not_found" and state() == s0,
    "auctioning an item id that is not in the seller's backpack is item_not_found and moves nothing")
-- market_full: the server-wide cap counts every seller's listings
local maxListings = Mk.MAX_LISTINGS
Mk.MAX_LISTINGS = S.modData().market.count
check(cmd(ann, "market.list", { itemId = axe.id, price = 50 }).error == "market_full" and state() == s0,
    "a market at its server-wide listing cap refuses a new listing, charges no fee and keeps the item")
Mk.MAX_LISTINGS = maxListings
local maxAuctions = Au.MAX_AUCTIONS
Au.MAX_AUCTIONS = S.modData().auctions.count
check(cmd(ann, "auction.create", { itemId = axe.id, startPrice = 50, hours = 24 }).error == "market_full" and state() == s0,
    "an auction house at its server-wide cap refuses a new auction, charges no fee and keeps the item")
Au.MAX_AUCTIONS = maxAuctions
-- too_many_auctions: the per-player cap
SandboxVars.MinidoracatEconomy.AuctionMaxPerPlayer = 1
local first = cmd(ann, "auction.create", { itemId = axe.id, startPrice = 100, hours = 24 })
local s1 = state()
check(first.ok == true and cmd(ann, "auction.create", { itemId = saw.id, startPrice = 50, hours = 24 }).error == "too_many_auctions"
    and state() == s1 and ann.inventory.contains(nil, saw), "a seller at AuctionMaxPerPlayer is refused the next auction, with no fee and the item kept")
SandboxVars.MinidoracatEconomy.AuctionMaxPerPlayer = nil
-- unknown_auction: bidding on / cancelling an id that does not exist
check(cmd(bob, "auction.bid", { auctionId = "no-such-auction", amount = 100 }).error == "unknown_auction" and state() == s1,
    "a bid on an auction id that does not exist is unknown_auction and reserves nothing")
check(cmd(ann, "auction.cancel", { auctionId = "no-such-auction" }).error == "unknown_auction" and state() == s1,
    "cancelling an auction id that does not exist is unknown_auction and returns nothing")
-- auction_ended: past expiresAt, before the once-a-minute sweep has settled it (no tick fired here)
nowMs = S.modData().auctions.items[first.auctionId].expiresAt
check(cmd(bob, "auction.bid", { auctionId = first.auctionId, amount = 100 }).error == "auction_ended" and state() == s1
    and Au.hasAuction(first.auctionId), "a bid after the auction's end but before the sweep settles it is auction_ended and reserves nothing")
onlinePlayers = {}
end)()

;(function()
-- The auction downtime policy reads the previous run's last heartbeat while the server starts.
-- Nothing may rewrite heartbeat.json before it does: an auction that was running when the server
-- went down two hours ago must end two hours later than planned (spec 12 stage F), instead of
-- being judged against a heartbeat written a moment earlier by this very start.
io.write("scenario DT: auction downtime measured across a real restart\n")
modDataStore[EC.MODDATA_KEY] = nil
files = {}
onlinePlayers = {}
nowMs = nowMs + 61000
fire("OnServerStarted")
local md = S.modData()
local ends = nowMs + 3600000
md.auctions.items["dt-1"] = { id = "dt-1", seller = "ann", item = "Base.Axe", snapshot = { type = "Base.Axe" }, qty = 1,
    startPrice = 10, currency = "survivor", tradeSchema = L.TRADE_SCHEMA, fee = 0, bids = 0, bidders = {},
    at = nowMs, expiresAt = ends, hours = 1, weight = 3, category = "other" }
md.auctions.count = md.auctions.count + 1
md.auctions.byOwner.ann = { ["dt-1"] = true }
fire("OnTickEvenPaused")                       -- this run's last heartbeat
local lastBeat = nowMs
nowMs = nowMs + 2 * 3600000                    -- down for two hours
fire("OnServerStarted")
local a = S.modData().auctions.items["dt-1"]
check(a ~= nil and a.expiresAt == ends + (nowMs - lastBeat), "two hours of downtime push a running auction's end back by the downtime")
end)()

;(function()
-- The client's admin checks read the local player's own role, never the connection: once the
-- client is disconnected the deprecated getAccessLevel() dereferences a null GameClient.connection
-- (LuaManager.java:4435-4436) while the engine still renders the destroy cursor one more frame.
io.write("scenario RL: the admin check without a connection\n")
local savedGetPlayer, savedGetAccessLevel, savedIsServer = getPlayer, getAccessLevel, isServer
local role = "admin"
getAccessLevel = function() error("GameClient.connection is null") end
getPlayer = function() return { getRole = function()
    return role and { getName = function() return role end, hasCapability = function() return true end } or nil
end } end
isServer = function() return false end
local okAdmin, admin = pcall(MinidoracatEconomy_AdminBuildOnly)
-- the build entry follows AdminRoles like the server does, not the role's name
local previousOverride = EC.optionOverride
EC.optionOverride = function(key)
    if key == "AdminRoles" then return { "Terminal Keeper" } end
    return previousOverride and previousOverride(key)
end
role = "Terminal Keeper"
local keeper = MinidoracatEconomy_AdminBuildOnly({ player = getPlayer() })
role = "admin"
local unlisted = MinidoracatEconomy_AdminBuildOnly({ player = getPlayer() })
EC.optionOverride = previousOverride
role = nil
local okNone, none = pcall(EC.localRoleName)
getPlayer = function() return nil end
local okNoPlayer, noPlayer = pcall(EC.localRoleName)
getPlayer, getAccessLevel, isServer = savedGetPlayer, savedGetAccessLevel, savedIsServer
check(okAdmin and admin == true and okNone and none == "" and okNoPlayer and noPlayer == "",
    "the admin check reads the local player's role and never the connection, even after a disconnect")
check(keeper == true and unlisted == false,
    "the build entry follows AdminRoles: a listed custom role sees it, the admin role does not once it is not listed")
end)()

;(function()
-- Split-screen seats 2-4 take their name from the client (ConnectCoopPacket.java:72-97 refuses only
-- an empty or an already connected name; GameServer.java:2848 then names the seat with it) and
-- share the main seat's connection and SteamID: the vanilla split-screen UI can name one after an
-- offline account. Such a seat has no economy identity at all - its commands do nothing, no push
-- or lookup finds it, and its death settles nothing of the account it named.
io.write("scenario SP: a split-screen seat is not an economy identity\n")
local KEY = EC.PLAYER_MODDATA_KEY
modDataStore[EC.MODDATA_KEY] = nil
files, sentCommands = {}, {}
nowMs = nowMs + 61000
fire("OnServerStarted")
local md = S.modData()
L.credit("sp-ann", "survivor", 100, "SYSTEM_MINT", { requestId = "sp-fund", reasonCode = "t" })
local seat = fakePlayer("sp-ann"); seat.playerNum = 1
local bob = fakePlayer("sp-bob")
onlinePlayers = { seat, bob }
local function sentTo(p)
    local n = 0
    for _, s in ipairs(sentCommands) do if s.player == p then n = n + 1 end end
    return n
end
sentCommands = {}
nowMs = nowMs + 1000
fire("OnClientCommand", EC.COMMAND_MODULE, "wallet.state", seat, { requestId = "sp-1" })
fire("OnClientCommand", EC.COMMAND_MODULE, "rewards.checkin", seat, checkinArgs("sp-ann", nowMs, "sp-2"))
check(sentTo(seat) == 0 and L.getBalance("sp-ann", "survivor").available == 100,
    "a split-screen seat named after an offline account gets no answer and moves none of that account's money")
check(S.onlinePlayer("sp-ann") == nil and S.onlinePlayer("sp-bob") == bob,
    "an online lookup never finds a split-screen seat, while a main seat is found by its name")
sentCommands = {}
L.credit("sp-ann", "survivor", 5, "SYSTEM_MINT", { requestId = "sp-push", reasonCode = "t" })
S.broadcast("sp.test", {})
check(sentTo(seat) == 0 and sentTo(bob) == 1,
    "neither the account's own push nor a broadcast reaches a split-screen seat")
md.market.byOwner["sp-ann"] = { ["sp-l1"] = true }
sentCommands = {}
nowMs = nowMs + 1000
fire("OnClientCommand", EC.COMMAND_MODULE, "market.sellers", bob, { requestId = "sp-s1", context = "market", query = "sp-" })
local sellers = lastSent("market.sellers").args.players
check(#sellers == 1 and sellers[1].username == "sp-ann" and sellers[1].online == false,
    "the seller picker does not call an account online because a split-screen seat carries its name")
md.market.byOwner["sp-ann"] = nil
md.mailbox.byOwner["sp-ann"] = { entries = { ["sp-m1"] = { id = "sp-m1", owner = "sp-ann", state = "claimed", at = nowMs, claimedAt = nowMs } }, unclaimed = 0 }
seat.modData[KEY] = { pendingOuts = { ["sp-o1"] = { kind = "market", epoch = md.meta.epoch, seq = 1 } } }
seat.dead = true
fire("OnCharacterDeath", seat)
local orphan = fakePlayer("sp-ann")
fire("OnNewGame", orphan, nil)
local carried = orphan.modData[KEY] and orphan.modData[KEY].pendingOuts or {}
check(md.mailbox.byOwner["sp-ann"].entries["sp-m1"].state == "claimed" and EC.countKeys(carried) == 0,
    "the death of a split-screen seat settles none of the account's mail and hands no records to its next character")
local ann = fakePlayer("sp-ann")
onlinePlayers = { ann, bob }
ann.dead = true
fire("OnCharacterDeath", ann)
check(md.mailbox.byOwner["sp-ann"].entries["sp-m1"].state == "settled",
    "the main seat's own death still settles that account's claimed mail")
onlinePlayers = {}
end)()

;(function()
-- Family convention "player identity": the account key stays the login name and the SteamID is
-- the factor that proves a player is that name. Bindings come only from OnNewGame (login name +
-- the connection's SteamID, CreatePlayerPacket.java:296-301), the administrator's whitelist
-- import and the administrator's confirmation of its conflicts; they live in a server file, never
-- in Global ModData. Every check below is written against what a player could do from a client.
io.write("scenario ID: identity bound to the SteamID\n")
local Id = EC.Identity
local KEY = EC.PLAYER_MODDATA_KEY
local FILE = Id.FILE
modDataStore[EC.MODDATA_KEY] = nil
files, sentCommands = {}, {}
nowMs = nowMs + 61000
steamModeActive = true
fire("OnServerStarted")
local md = S.modData()
local function sid(text) return tonumber(text) + 0.0 end   -- the double the engine hands Lua
-- every player object sits on its own seat (onlineID): first sight needs one to judge the occupancy
local nextSeat = 100
local function steamPlayer(name, steamId)
    local p = fakePlayer(name); p.steamId = steamId; p.onlineId = nextSeat; nextSeat = nextSeat + 1
    return p
end
local function fileRecs()
    local out = {}
    for _, line in ipairs(files[FILE] and files[FILE].lines or {}) do out[#out + 1] = EC.jsonDecode(line) end
    return out
end
local function sentTo(p, command)
    local n = 0
    for _, s in ipairs(sentCommands) do
        if s.player == p and (command == nil or s.command == command) then n = n + 1 end
    end
    return n
end
local function ringHas(action, target, field)
    for _, e in ipairs(X.auditEntries()) do
        if e.action == action and e.target == target and (field == nil or e.field == field) then return e end
    end
end
local function fileAudits(action)
    proofSettle()
    local out = {}
    for _, line in ipairs(files[X.auditPath(nowMs)] and files[X.auditPath(nowMs)].lines or {}) do
        local rec = EC.jsonDecode(line)
        if type(rec) == "table" and rec.action == action then out[#out + 1] = rec end
    end
    return out
end
local function admin(who, args)
    nowMs = nowMs + 700
    sentCommands = {}
    fire("OnClientCommand", EC.COMMAND_MODULE, "admin.identity", who, args)
    local s = lastSent("admin.identity")
    return s and s.args or {}
end

local vectorsOk = true
for _, v in ipairs({ { "76561198000000008", "76561198000000000" }, { "76561198000000024", "76561198000000032" },
    { "76561198012345679", "76561198012345680" }, { "76561198097932712", "76561198097932704" },
    { "76561198097932713", "76561198097932720" } }) do
    if Id.sidText(sid(v[1])) ~= v[2] or sid(v[1]) ~= sid(v[2]) then vectorsOk = false end
end
check(vectorsOk, "a whitelist SteamID text and the engine's double land on one number, written back as that double's exact decimal (the family convention's five vectors)")

-- ----- before the first import -----
local SID_ANN, SID_BOB, SID_EVE = sid("76561198000000016"), sid("76561198000000032"), sid("76561198000000048")
fire("OnNewGame", steamPlayer("id-ann", SID_ANN), nil)
local recs = fileRecs()
check(#recs == 1 and recs[1].k == "bind" and recs[1].name == "id-ann" and recs[1].sid == "76561198000000016"
    and recs[1].src == "NEWGAME",
    "a new character binds its login name to the connection's SteamID in the server's identity file")
local ann = steamPlayer("id-ann", SID_ANN)
local fake = steamPlayer("id-ann", SID_EVE)            -- another Steam account wearing ann's name
local bob = steamPlayer("id-bob", SID_BOB)             -- has not made a character since the update: unbound
-- (first-sight binding replaced "an unbound name is taken at its word": bob's first sighting binds
-- the name to his SteamID - LOGIN - instead of trusting it on every command)
check(Id.principal(ann) == "id-ann" and Id.principal(fake) == nil and Id.principal(bob) == "id-bob"
    and fileRecs()[2].src == "LOGIN" and fileRecs()[2].name == "id-bob",
    "before the first import a bound name needs its own SteamID, while an unbound name is bound on first sight")
local seat = steamPlayer("id-ann", SID_ANN); seat.playerNum = 1
steamModeActive = false
local noSteam = Id.principal(fake)
steamModeActive = true
check(Id.principal(seat) == nil and Id.principal(steamPlayer("", SID_ANN)) == nil and noSteam == "id-ann",
    "a split-screen seat and an empty name are nobody, and a server without Steam has no factor to check")
fire("OnNewGame", steamPlayer("id-ann", SID_EVE), nil)
local afterWrong = { Id.principal(ann), Id.principal(fake) }
fire("OnNewGame", steamPlayer("id-ann", SID_ANN), nil)
check(#fileRecs() == 2 and afterWrong[1] == "id-ann" and afterWrong[2] == nil
    and Id.principal(ann) == "id-ann" and Id.principal(fake) == nil
    and ringHas("BIND_CONFLICT", "id-ann", "SID_MISMATCH") ~= nil,
    "a new character with another SteamID never moves a binding: it is audited as a conflict and the name stays with its owner")
steamModeActive = false
fire("OnNewGame", steamPlayer("id-nos", SID_EVE), nil)
steamModeActive = true
check(#fileRecs() == 2, "without Steam mode a new character binds nothing: there is no SteamID to trust")
local bindRing = ringHas("BIND", "id-ann", "NEWGAME")
local bindFile = fileAudits("BIND")[1]
check(bindRing ~= nil and bindRing.steamId == nil and bindFile ~= nil and bindFile.steamId == "76561198000000016",
    "the SteamID of a binding reaches the audit file only, never the audit ring every client can read")

-- ----- someone wearing a bound name -----
L.credit("id-ann", "survivor", 100, "SYSTEM_MINT", { requestId = "id-fund", reasonCode = "t" })
onlinePlayers = { fake, bob }
sentCommands = {}
nowMs = nowMs + 1000
fire("OnClientCommand", EC.COMMAND_MODULE, "hello", fake, {})
fire("OnClientCommand", EC.COMMAND_MODULE, "wallet.state", fake, { requestId = "id-w1" })
L.credit("id-ann", "survivor", 5, "SYSTEM_MINT", { requestId = "id-push", reasonCode = "t" })
check(sentTo(fake, "hello.ack") == 0 and sentTo(fake, "wallet.state") == 0 and sentTo(fake, "wallet.changed") == 0
    and sentTo(fake, "identity.unverified") == 1 and S.onlinePlayer("id-ann") == nil,
    "a name worn with the wrong SteamID gets neither the account's replies nor its pushes, only one notice saying why")
nowMs = nowMs + 30000
fire("OnClientCommand", EC.COMMAND_MODULE, "wallet.state", fake, { requestId = "id-w2" })
local within = sentTo(fake, "identity.unverified")
nowMs = nowMs + 31000
fire("OnClientCommand", EC.COMMAND_MODULE, "wallet.state", fake, { requestId = "id-w3" })
check(within == 1 and sentTo(fake, "identity.unverified") == 2,
    "the notice is repeated at most once a minute, never once per command")
fire("OnTickEvenPaused")
local unv = ringHas("IDENTITY_UNVERIFIED", "id-ann", "commands")
check(unv ~= nil and unv.after == 4, "the minute's four refused commands (a hello and three reads) become one IDENTITY_UNVERIFIED audit line for that name")
md.mailbox.byOwner["id-ann"] = { entries = { ["id-m1"] = { id = "id-m1", state = "claimed", at = nowMs, claimedAt = nowMs } }, unclaimed = 0 }
fake.dead = true
fire("OnCharacterDeath", fake)
check(md.mailbox.byOwner["id-ann"].entries["id-m1"].state == "claimed",
    "the death of someone wearing the name settles none of the account's mail")

-- ----- the whitelist import -----
SandboxVars.MinidoracatEconomy.AdminRoles = "admin"
local boss = steamPlayer("id-boss", sid("76561198000000080")); boss.role = "admin"
onlinePlayers = { boss, bob }
fire("OnNewGame", steamPlayer("id-fay", sid("76561198000000096")), nil)   -- fay's old Steam account
L.credit("id-gone", "survivor", 7, "SYSTEM_MINT", { requestId = "id-gone", reasonCode = "t" })   -- a deleted account
md.claims["id-seat"] = {}                                                                      -- a split-screen name of old
local ROWS = {
    { u = "id-boss", s = "76561198000000080" },
    { u = "id-ann", s = "76561198000000016" },          -- same
    { u = "id-bob", s = "76561198000000032" },          -- new
    { u = "id-cat", s = "" },                           -- never logged in with Steam
    { u = "id-dan", s = "76561198000000066" },          -- 66 and 67 round to the same double
    { u = "id-dee", s = "76561198000000067" },
    { u = "id-fay", s = "76561198000000112" },          -- fay's account moved to another Steam account
    { u = "SYSTEM_X", s = "" },
}
Id.principal(boss)     -- the administrator's own first sighting binds id-boss (LOGIN) before the import
local linesBefore = #fileRecs()
local bad = admin(boss, { action = "import", requestId = "i0", rows = { { u = "id-x", s = "7.6561198E16" } } })
local dup = admin(boss, { action = "import", requestId = "i1", rows = { { u = "id-x", s = "" }, { u = "id-x", s = "" } } })
local user = admin(bob, { action = "import", requestId = "i2", rows = ROWS })
check(bad.ok == false and bad.error == "invalid_steamid" and bad.name == "id-x" and dup.error == "invalid_args"
    and user.error == "forbidden" and #fileRecs() == linesBefore and bad.status.imported == false,
    "a SteamID text parseDouble would accept, a repeated name or a caller without the write role imports nothing at all")
steamModeActive = false
local noSteamImport = admin(boss, { action = "import", requestId = "i3", rows = ROWS })
steamModeActive = true
check(noSteamImport.error == "not_steam" and #fileRecs() == linesBefore,
    "a server without Steam has nothing to import")
local imp = admin(boss, { action = "import", requestId = "i4", rows = ROWS })
local last = imp.last or {}
local reserved = table.concat(last.reserved or {}, ",")
local collisions = table.concat(last.collisions or {}, ",")
-- (first sight bound id-boss and id-bob before the import: they are upgraded now, not new)
check(imp.ok == true and last.rows == 8 and last.bound == 2 and last.same == 0 and last.upgraded == 3 and last.ignored == 1
    and table.concat(last.missing or {}, ",") == "id-cat" and reserved == "id-gone,id-seat"
    and collisions == "id-dan,id-dee" and last.conflicts == 1 and imp.status.conflicts[1].name == "id-fay"
    and imp.status.conflicts[1].reason == "SID_MISMATCH" and imp.status.conflicts[1].whitelist == "76561198000000112",
    "the import reports new, upgraded (a NEWGAME or first-sight double the whitelist text rounds to), no-SteamID, reserved, conflicting and colliding names - and system accounts are left out")
recs = fileRecs()
check(recs[linesBefore + 1].k == "import" and recs[linesBefore + 1].by == "id-boss"
    and imp.status.imported == true and imp.perms.write == true,
    "the import marker is written before the bindings it brings, so a cut-short write keeps the strict mode")
local fay = steamPlayer("id-fay", sid("76561198000000112"))
local fayOld = steamPlayer("id-fay", sid("76561198000000096"))
check(Id.principal(bob) == "id-bob" and Id.principal(steamPlayer("id-zed", SID_EVE)) == nil
    and Id.principal(steamPlayer("id-cat", SID_EVE)) == nil and Id.principal(steamPlayer("id-gone", SID_EVE)) == nil
    and Id.principal(steamPlayer("id-gone", nil)) == nil and Id.principal(fay) == nil and Id.principal(fayOld) == "id-fay",
    "after the first import an unbound or reserved name is nobody (even for a SteamID that reads as nil), and a conflict leaves the old binding in force until it is confirmed")
check(Id.principal(steamPlayer("id-dee", sid("76561198000000066"))) == "id-dee",
    "two Steam accounts that round to one number cannot be told apart: they are bound and listed, not guessed")
check(ringHas("IDENTITY_IMPORT", "whitelist") ~= nil and ringHas("BIND_RESERVED", "id-gone", "IMPORT") ~= nil
    and ringHas("BIND_CONFLICT", "id-fay", "SID_MISMATCH") ~= nil and ringHas("BIND_CONFLICT", "id-dan", "COLLISION") ~= nil,
    "the import, each reservation, each conflict and each collision are audited")

-- ----- confirming a conflict -----
onlinePlayers = { boss, fay }
local noReason = admin(boss, { action = "rebind", requestId = "r0", names = { "id-fay" } })
local rb = admin(boss, { action = "rebind", requestId = "r1", names = { "id-fay", "id-nobody" }, reason = "moved to a new Steam account" })
local moved = ringHas("BIND_MOVE", "id-fay", "REBIND")
check(noReason.ok == false and noReason.error == "reason_too_short" and rb.ok == true and rb.rebound == 1
    and table.concat(rb.stale, ",") == "id-nobody" and moved ~= nil and moved.reason == "moved to a new Steam account"
    and moved.steamId == nil,
    "a confirmation needs a reason, moves only the listed conflicts and is audited without the SteamID in the ring")
check(Id.principal(fay) == "id-fay" and Id.principal(fayOld) == nil and sentTo(fay, "identity.verified") == 1
    and fileRecs()[#fileRecs()].src == "REBIND",
    "the name now follows the whitelist's SteamID, and the player it now verifies is told to say hello again")

-- ----- an administrator whose own name is not verified -----
local lost = steamPlayer("id-lost", sid("76561198000000128")); lost.role = "admin"
onlinePlayers = { lost }
local st = admin(lost, { action = "status", requestId = "s1" })
sentCommands = {}
nowMs = nowMs + 700
-- (admin.system is exempt as well since the one-account policy: server-wide figures, read role;
-- admin.lookup reads one account and stays behind the identity gate)
fire("OnClientCommand", EC.COMMAND_MODULE, "admin.lookup", lost, { username = "id-bob" })
check(st.ok == true and st.perms.write == true and lastSent("admin.lookup") == nil and sentTo(lost, "identity.unverified") == 1,
    "an administrator without a verified name still reaches the identity pages by role, and nothing else")
local fix = admin(lost, { action = "import", requestId = "i5", rows = { { u = "id-lost", s = "76561198000000128" } } })
check(fix.ok == true and Id.principal(lost) == "id-lost" and ringHas("IDENTITY_IMPORT", "whitelist").admin == "?id-lost"
    and sentTo(lost, "identity.verified") == 1,
    "that administrator can import the whitelist to repair their own name, audited under the name they claimed")

-- ----- the tracked life of a name moved away -----
local hal = steamPlayer("id-hal", sid("76561198000000144")); hal.hours = 10
fire("OnNewGame", steamPlayer("id-hal", sid("76561198000000144")), nil)
onlinePlayers = { hal }
nowMs = nowMs + 60000; fire("OnTickEvenPaused")
hal.hours = 12
nowMs = nowMs + 60000; fire("OnTickEvenPaused")
local halBefore = S.Seasons.progress("id-hal").bestHours
onlinePlayers = { boss }
admin(boss, { action = "import", requestId = "i6", rows = { { u = "id-hal", s = "76561198000000160" } } })
admin(boss, { action = "rebind", requestId = "r2", names = { "id-hal" }, reason = "moved" })
hal.hours, hal.dead = 20, true
fire("OnCharacterDeath", hal)
check(halBefore == 2 and S.Seasons.progress("id-hal").bestHours == 2,
    "a tracked character whose name was moved to another SteamID closes no life with its death")

-- ----- a restart replays the file; memory-only state does not survive -----
nowMs = nowMs + 1000
fire("OnServerStarted")
local again = admin(boss, { action = "rebind", requestId = "r3", names = { "id-fay" }, reason = "again" })
check(Id.principal(bob) == "id-bob" and Id.principal(fay) == "id-fay" and Id.principal(fayOld) == nil
    and Id.principal(steamPlayer("id-gone", SID_EVE)) == nil and Id.principal(steamPlayer("id-zed", SID_EVE)) == nil
    and again.error == "import_first",
    "after a restart every binding, reservation and the strict mode come back from the file; unconfirmed conflicts need a new import")
local savedReader = getFileReader
getFileReader = function(path, create) if path == FILE then return nil end return savedReader(path, create) end
nowMs = nowMs + 1000
fire("OnServerStarted")
local broken = admin(boss, { action = "import", requestId = "i7", rows = ROWS })
local brokenBob = Id.principal(bob)
getFileReader = savedReader
nowMs = nowMs + 1000
fire("OnServerStarted")
check(brokenBob == nil and broken.error == "unreadable" and broken.status.unreadable == true and Id.principal(bob) == "id-bob",
    "an identity file that exists but cannot be read verifies nobody and imports nothing, instead of trusting every name")
SandboxVars.MinidoracatEconomy.AdminRoles = "admin;gm"
steamModeActive = false
onlinePlayers = {}
end)()

-- ===== 情境 MA：兩個登入名共用一個帳號（身分 v2 第 2a 步；合併標記手動寫入 ModData）=====
-- 2a 只拆名字：S.login = 存檔（登入名）、S.principal = 帳號。這裡直接寫 md.identity.merged，
-- 驗證每個「以存檔為範圍」與「以帳號為範圍」的分界都守住。
io.write("scenario MA: two login names sharing one account\n")
;(function()
local M, Mk, Se, V = S.Mailbox, S.Market, S.Seasons, EC.v1
local KEY = EC.PLAYER_MODDATA_KEY
local SV = SandboxVars.MinidoracatEconomy
modDataStore[EC.MODDATA_KEY] = nil
files, sentCommands = {}, {}
nowMs = nowMs + 61000
fire("OnServerStarted")
local md = S.modData()
local initOk = type(md.identity) == "table" and type(md.identity.merged) == "table"
md.identity.merged["ma-alt"] = { into = "ma-main" }
local main, alt, seat = fakePlayer("ma-main"), fakePlayer("ma-alt"), fakePlayer("ma-seat")
main.role, main.hours, alt.hours, seat.playerNum = "admin", 100, 5, 1
onlinePlayers = { alt, main, seat }
local function cmd(who, name, args)
    nowMs = nowMs + 600
    sentCommands = {}
    fire("OnClientCommand", EC.COMMAND_MODULE, name, who, args or {})
    local s = lastSent(name)
    return s and s.args or {}
end
local group = {}
for _, name in ipairs(S.groupOf("ma-alt")) do group[name] = true end
check(initOk and S.login(alt) == "ma-alt" and S.principal(alt) == "ma-main" and S.principal(main) == "ma-main"
    and S.accountOf("ma-alt") == "ma-main" and S.accountOf("ma-main") == "ma-main" and S.sameAccount("ma-alt", "ma-main")
    and group["ma-main"] and group["ma-alt"] and EC.countKeys(group) == 2,
    "a merged login name is its own login but its account's principal, one hop, and both names are one group")
cmd(alt, "hello")
local ack = lastSent("hello.ack") and lastSent("hello.ack").args or {}
check(ack.account == "ma-main" and ack.login == "ma-alt", "hello.ack tells the client its account and the login it came in with")
local visits = {}
S.forEachOnline(function(p, account) visits[#visits + 1] = account end)
check(S.onlinePlayer("ma-main") == alt and S.onlinePlayer("ma-alt") == nil and S.onlineLogin("ma-alt") == alt
    and S.onlineLogin("ma-main") == main and S.onlineLogin("ma-seat") == nil and S.onlineNames()["ma-seat"] == true
    and #visits == 2 and visits[1] == "ma-main" and visits[2] == "ma-main",
    "onlinePlayer finds any seat of the account, onlineLogin only that very login, onlineNames every raw seat")
-- ledger: an alias is never a wallet of its own
local credited = L.credit("ma-alt", "survivor", 100, "SYSTEM_MINT", { requestId = "ma-c1", reasonCode = "t" })
check(credited.ok and md.wallets["ma-alt"] == nil and L.getBalance("ma-main", "survivor").available == 100
    and L.getBalance("ma-alt", "survivor").available == 100 and #L.receipts("ma-alt") == 1,
    "a credit to a merged name lands on the account, and the name reads the account's balance and receipts")
-- merge=true is server code only: the integration API rebuilds the tx and cannot carry it
local src = V.registerSource({ modId = "MaMod", currencies = { "survivor" }, reasonCodes = { "ma" } })
md.config.currencies.survivor = md.config.currencies.survivor or {}
md.config.currencies.survivor.enabled = false
local legs = function() return { { account = "ma-main", currency = "survivor", amount = -5 },
    { account = "ma-other", currency = "survivor", amount = 5 } } end
local viaApi = src.post({ requestId = "ma-m1", reasonCode = "ma", merge = true, postings = legs() })
local direct = L.post({ kind = "account_merge", requestId = "ma-m2", reasonCode = "account_merge", merge = true, postings = legs() })
md.config.currencies.survivor.enabled = nil
check(viaApi.ok == false and viaApi.error == "currency_disabled" and direct.ok == true
    and L.getBalance("ma-other", "survivor").available == 5,
    "merge=true exempts a server posting from a disabled currency, and an integration post cannot smuggle it in")
-- transfers and admin pages compare accounts
SV.TransferEnabled = true
md.config.currencies.survivor.directTransfer = true
local self = cmd(main, "wallet.transfer", { to = "ma-alt", currency = "survivor", amount = 10, fee = 1, requestId = "ma-t1" })
SV.TransferEnabled = nil
md.config.currencies.survivor.directTransfer = nil
check(self.ok == false and self.error == "self_transfer" and L.getBalance("ma-main", "survivor").available == 95,
    "a transfer to another login name of your own account is a self transfer")
local look = cmd(main, "admin.lookup", { username = "ma-alt" })
local members = {}
for _, name in ipairs(look.members or {}) do members[name] = true end
local frozen = cmd(main, "admin.freeze", { username = "ma-alt", frozen = true, reason = "self" })
check(look.username == "ma-alt" and look.account == "ma-main" and members["ma-main"] and members["ma-alt"]
    and look.balances and frozen.error == "self_target" and md.frozen["ma-main"] == nil and md.frozen["ma-alt"] == nil,
    "the admin lookup of a merged name answers for its account and lists its logins; freezing it is freezing yourself")
-- the survival base belongs to each login's save, the claim to the account
Se.observe(main, nowMs); Se.observe(alt, nowMs)
local bases = md.claims["ma-main"] and md.claims["ma-main"].survivalBase or {}
check(bases["ma-main"] == 100 and bases["ma-alt"] == 5 and md.claims["ma-alt"] == nil,
    "two logins of one account keep their own survival base inside the account's claim")
-- recovery looks at this login's save only
alt.modData[KEY].pendingOuts = { ["ma-op"] = { kind = "listing", epoch = md.meta.epoch, seq = 1 } }
local rec = cmd(main, "admin.recovery", { action = "list", username = "ma-alt", requestId = "ma-r1" })
check(M.recoveryStatus("ma-main").open == 0 and M.recoveryStatus("ma-alt").open == 1 and rec.online == true,
    "a recovery status and the admin recovery page read the save of that very login, never another login of its account")
-- mail: the account's box, claimed by one save
local letter = M.add("ma-alt", { kind = "shop", item = "Base.Bandage", qty = 1, txId = "ma-tx" })
local claimed = M.claim(alt, letter.id)
check(letter.owner == "ma-main" and md.mailbox.byOwner["ma-alt"] == nil and claimed.ok == true
    and letter.claimLogin == "ma-alt" and alt.inventory.count("Base.Bandage") == 1,
    "a letter to a merged name is the account's, and the claim remembers which login took it")
cmd(main, "hello")
check(main.inventory.count("Base.Bandage") == 0 and letter.state == "claimed",
    "another login's reconcile, with neither witness nor item, never redelivers what the first login claimed")
fire("OnCharacterDeath", main)
check(letter.state == "claimed", "the death of another login of the account does not settle that letter")
fire("OnCharacterDeath", alt)
local newMain, newAlt = fakePlayer("ma-main"), fakePlayer("ma-alt")
fire("OnNewGame", newMain, nil)
fire("OnNewGame", newAlt, nil)
local carriedMain = newMain.modData[KEY] and newMain.modData[KEY].pendingOuts or {}
local carriedAlt = newAlt.modData[KEY] and newAlt.modData[KEY].pendingOuts or {}
check(letter.state == "settled" and carriedMain["ma-op"] == nil and carriedAlt["ma-op"] ~= nil,
    "the claiming login's own death settles it, and its pending records go to that login's next character only")
-- a stamp names the owner it was written with: the letter is found in any box of the group, once
md.identity.merged["ma-third"] = { into = "ma-main" }
local stray = { id = "ma-x", owner = "ma-alt", state = "claimed" }
md.mailbox.byOwner["ma-alt"] = { entries = { ["ma-x"] = stray }, unclaimed = 0 }
local found = M.entryOf("ma-main", "ma-x") == stray and M.entryOf("ma-alt", "ma-x") == stray
md.mailbox.byOwner["ma-third"] = { entries = { ["ma-x"] = { id = "ma-x", owner = "ma-third", state = "claimed" } }, unclaimed = 0 }
check(found and M.entryOf("ma-main", "ma-x") == nil,
    "a letter left under a merged name is found through the group, and two names holding the id answer nothing")
md.mailbox.byOwner["ma-alt"], md.mailbox.byOwner["ma-third"], md.identity.merged["ma-third"] = nil, nil, nil
-- restore rebuilds for the account, whichever login's save held the record
local R = S.Recovery
local function proven(kind)
    local pend = { kind = kind, qty = 1, lotQty = 1, snapshot = { type = "Base.Bandage" }, price = 10, hours = 24,
        currency = "survivor", tradeSchema = L.TRADE_SCHEMA, at = nowMs }
    R.markProven(pend)
    return pend
end
local relisted = Mk.restoreFromPending("ma-alt", "ma-l1", proven("listing"))
local reopened = Mk.restoreFromPending("ma-alt", "ma-a1", proven("auction"))
check(relisted and reopened and md.market.listings["ma-l1"].seller == "ma-main"
    and md.auctions.items["ma-a1"].seller == "ma-main" and Mk.ownerCount("ma-alt") == 0,
    "a listing or auction restored from a merged login's save is the account's")
-- the survival base keyed by seat "0" becomes its owner's login, keeping the running life
local c = md.claims["ma-main"]
c.survivalBase = { ["0"] = 10 }
nowMs = nowMs + 1000
fire("OnServerStarted")
local veteran = fakePlayer("ma-main"); veteran.hours = 20
onlinePlayers = { veteran }
local life = Se.observe(veteran, nowMs)
check(life == 10 and c.survivalBase["ma-main"] == 10 and c.survivalBase["0"] == nil,
    "the legacy seat key moves to the owner's login once, without restarting the life it measured")
onlinePlayers = {}
end)()

-- ===== 情境 MG：companion 白名單匯出、SteamID 群組與帳號合併（身分 v2 第 2b／2c 步）=====
-- 匯出檔每一種拒收都「完全沒套用」；精確升級、EXACT_MISMATCH、保留門檻；群組只收精確綁定、
-- 碰撞不成群、canon 只決定一次；合併在一次呼叫內搬錢（逐幣守恆）、簽到、上限計數與乾淨信件，
-- 每一種擋點各一例並自然解除；回滾後別名先恢復獨立、再自動合併一次，仍守恆。
io.write("scenario MG: companion export, SteamID groups and the account merge\n")
-- exact multiples of 16 in the SteamID64 range: every one is its own double
function mgT(k) return string.format("7656119820%07d", k * 16) end
-- the same double written as another exact text (last digit + 1 rounds back down)
function mgTwin(text) return string.sub(text, 1, 16) .. tostring(tonumber(string.sub(text, 17)) + 1) end
function mgSid(text) return tonumber(text) + 0.0 end
function mgPlayer(name, text)
    local p = fakePlayer(name)
    p.steamId = text and mgSid(text) or nil
    return p
end
mgGen = 1790000000000
-- rows = { { id, u, s }, ... }; opts: gen, serverName, count, trailerCount, noTrailer, extra (lines)
function mgExport(rows, opts)
    opts = opts or {}
    if not opts.gen then mgGen = mgGen + 1 end
    local lines = { EC.jsonEncode({ type = "whitelist", v = 1, serverName = opts.serverName or "servertest",
        generatedAt = opts.gen or mgGen, count = opts.count or #rows, invalidSteamIds = 0 }) }
    for _, r in ipairs(rows) do lines[#lines + 1] = EC.jsonEncode({ id = r[1], u = r[2], s = r[3] }) end
    if not opts.noTrailer then lines[#lines + 1] = EC.jsonEncode({ type = "end", count = opts.trailerCount or opts.count or #rows }) end
    for _, l in ipairs(opts.extra or {}) do lines[#lines + 1] = l end
    files[EC.Identity.EXPORT_FILE] = { lines = lines }
end
-- one header poll, then the streamed read
function mgPoll()
    nowMs = nowMs + EC.Identity.EXPORT_POLL_MS + 1
    fire("OnTickEvenPaused")
    fire("OnTickEvenPaused")
end
function mgRecs(kind)
    local out = {}
    for _, line in ipairs(files[EC.Identity.FILE] and files[EC.Identity.FILE].lines or {}) do
        local rec = EC.jsonDecode(line)
        if kind == nil or (type(rec) == "table" and rec.k == kind) then out[#out + 1] = rec end
    end
    return out
end
function mgAudits(action, field)
    local n = 0
    for _, e in ipairs(X.auditEntries()) do
        if e.action == action and (field == nil or e.field == field) then n = n + 1 end
    end
    return n
end
function mgMember(name)
    for _, g in ipairs(S.Merge.planGroups()) do
        for _, m in ipairs(g.members) do if m.name == name then return m, g end end
    end
    return nil
end
function mgWorld()
    modDataStore[EC.MODDATA_KEY] = nil
    files, sentCommands, onlinePlayers = {}, {}, {}
    nowMs = nowMs + 61000
    steamModeActive = true
    SandboxVars.MinidoracatEconomy.IdentityAutoMerge = nil
    -- the merge scenarios let aliases use the economy as their own accounts before they merge:
    -- with the one-account policy on (the default) an unmerged alias is refused at login instead
    -- (scenario FS covers that side)
    SandboxVars.MinidoracatEconomy.IdentityMultiAccount = true
    SandboxVars.MinidoracatEconomy.AdminRoles = "admin"
    fire("OnServerStarted")
    return S.modData()
end
function mgEvents(kind)
    proofSettle()
    local out = {}
    for path, f in pairs(files) do
        if string.find(path, "/events-", 1, true) then
            for _, line in ipairs(f.lines or {}) do
                local rec = EC.jsonDecode(line)
                if type(rec) == "table" and rec.type == kind then out[#out + 1] = rec end
            end
        end
    end
    return out
end

-- ----- MG-1: the export is read, refused whole, or applied once -----
;(function()
local Id = EC.Identity
local md = mgWorld()
fire("OnNewGame", mgPlayer("mg-ann", mgT(1)), nil)         -- a rounded NEWGAME binding the export upgrades
fire("OnNewGame", mgPlayer("mg-fay", mgT(3)), nil)         -- the whitelist says another Steam account
fire("OnNewGame", mgPlayer("mg-man", mgT(6)), nil)         -- upgraded later by an administrator's import
L.credit("mg-gone", "survivor", 5, "SYSTEM_MINT", { requestId = "mg-gone", reasonCode = "t" })
L.credit("mg-cat", "survivor", 5, "SYSTEM_MINT", { requestId = "mg-cat", reasonCode = "t" })
local ROWS = { { 1, "mg-boss", mgT(9) }, { 2, "mg-ann", mgT(1) }, { 3, "mg-alt", mgT(1) }, { 4, "mg-fay", mgT(4) },
    { 5, "mg-exa", mgT(5) }, { 6, "mg-cat", "" }, { 7, "mg-p1", mgT(7) }, { 8, "mg-p2", mgT(8) } }
local base = #mgRecs()
local function untouched() return #mgRecs() == base and Id.status().bound == 3 and Id.status().imported == false end
local function rejected(variant, opts, rows)
    mgExport(rows or ROWS, opts)
    mgPoll()
    return Id.exportStatus().status == variant and untouched()
end
files[Id.EXPORT_FILE] = nil
mgPoll()
check(Id.exportStatus().status == "none" and untouched(),
    "with no export file and nothing accepted yet the status stays none: the page never says earlier data stays in effect")
check(rejected("server_mismatch", { serverName = "another-server" }), "an export for another server name is refused and nothing of it is applied")
local whyServer = Id.exportStatus().reason
check(rejected("truncated", { noTrailer = true }), "an export without its trailer line is refused whole: truncated")
local whyTrailer = Id.exportStatus().reason
check(rejected("truncated", { count = 9, trailerCount = 9 }), "an export with fewer rows than its count is refused whole: truncated")
local whyRows = Id.exportStatus().reason
local dupName = { { 1, "mg-boss", mgT(9) }, { 2, "mg-boss", mgT(1) } }
check(rejected("malformed", nil, dupName), "a name listed twice refuses the whole export")
local whyRow = Id.exportStatus().reason
local rowAudit = nil
for _, e in ipairs(X.auditEntries()) do
    if rowAudit == nil and e.action == "IDENTITY_EXPORT_REJECTED" then rowAudit = e end
end
check(rowAudit ~= nil and rowAudit.field == "malformed" and type(rowAudit.detail) == "table"
    and rowAudit.detail.code == "bad_row" and rowAudit.detail.line == 3 and rowAudit.detail.field == "u"
    and rowAudit.reason == nil,
    "the audit line of a refused export keeps the code with its line and field, so why it failed survives a later accepted export")
check(rejected("malformed", nil, { { 1, "mg-boss", "7.6561198E16" }, { 2, "mg-ann", mgT(1) } }),
    "a SteamID text that is not seventeen digits refuses the whole export")
check(rejected("malformed", nil, { { 1, "mg-boss", mgT(9) }, { 1, "mg-ann", mgT(1) } }), "a repeated whitelist id refuses the whole export")
check(rejected("malformed", { extra = { "{\"id\":9,\"u\":\"mg-late\",\"s\":\"\"}" } }), "a line after the trailer refuses the whole export")
local whyAfter = Id.exportStatus().reason
local rejectedGen = mgGen
mgPoll(); mgPoll()
check(mgAudits("IDENTITY_EXPORT_REJECTED") == 7 and mgAudits("IDENTITY_EXPORT_REJECTED", "malformed") == 4
    and Id.exportStatus().generatedAt == rejectedGen and untouched(),
    "every refused export is audited once per generatedAt, however often the same file is polled again")
check(rejected("malformed", { count = 0, trailerCount = 0 }, {}), "a count outside 1..50000 refuses the export")
local realReader = getFileReader
getFileReader = function(path, create) if path == Id.EXPORT_FILE then return nil end return realReader(path, create) end
mgExport(ROWS)
mgPoll()
getFileReader = realReader
check(Id.exportStatus().status == "unreadable" and untouched(),
    "an export that exists but cannot be opened is unreadable, never taken for a missing one, and nothing is applied")
local whyOpen = Id.exportStatus().reason
check(type(whyServer) == "table" and whyServer.code == "header_field" and whyServer.field == "serverName"
    and whyTrailer.code == "no_trailer" and whyTrailer.rows == 8
    and whyRows.code == "rows" and whyRows.rows == 8 and whyRows.count == 9
    and whyRow.code == "bad_row" and whyRow.line == 3 and whyRow.field == "u"
    and whyAfter.code == "after_trailer" and type(whyOpen) == "table" and whyOpen.code == "open",
    "a refused export says why as a code with its facts (field, line, row counts), never as an English sentence")
-- accepted
mgExport(ROWS)
local acceptedGen = mgGen
mgPoll()
local recs = mgRecs()
local marker = recs[base + 1] or {}
local ann = Id.view().bindings["mg-ann"]
check(Id.exportStatus().status == "accepted" and Id.exportStatus().generatedAt == acceptedGen and Id.exportStatus().count == 8
    and marker.k == "import" and marker.src == "COMPANION" and marker.gen == acceptedGen,
    "a whole export is accepted and applied in one write, its import marker (with generatedAt) first")
check(ann and ann.exact == true and ann.text == mgT(1) and Id.view().bindings["mg-alt"].src == "COMPANION"
    and mgAudits("IDENTITY_IMPORT", "COMPANION") == 1,
    "a rounded NEWGAME binding is upgraded to the exact text it rounds from, a new name is bound exactly, and the import is audited as COMPANION")
local upgrade = nil
for _, rec in ipairs(mgRecs("bind")) do if rec.name == "mg-ann" and rec.exact == true then upgrade = rec end end
check(upgrade and upgrade.from == "NEWGAME" and upgrade.src == "COMPANION" and upgrade.sid == mgT(1),
    "the upgrade is a bind record of its own, naming the rounded binding it replaces")
local fay = Id.view().bindings["mg-fay"]
check(fay.text == Id.sidText(mgSid(mgT(3))) and fay.exact == nil and Id.unresolved("mg-fay") == "SID_MISMATCH"
    and S.login(mgPlayer("mg-fay", mgT(3))) == "mg-fay" and S.login(mgPlayer("mg-fay", mgT(4))) == nil,
    "a whitelist SteamID that differs is recorded as a conflict and never moves the binding")
check(Id.view().bindings["mg-gone"].reserved == true and Id.view().bindings["mg-cat"] == nil
    and S.login(mgPlayer("mg-zed", mgT(10))) == nil,
    "the first accepted export reserves the economy's unlisted names and starts the strict mode")
-- the accepted file disappears: what it brought stays in effect, and that is what missing says
local acceptedFile = files[Id.EXPORT_FILE]
files[Id.EXPORT_FILE] = nil
mgPoll()
local gone = Id.exportStatus()
files[Id.EXPORT_FILE] = acceptedFile
check(gone.status == "missing" and gone.acceptedAt ~= nil and Id.view().bindings["mg-alt"] ~= nil,
    "an accepted export that disappears is missing, and the bindings it brought stay in effect")
-- the same file again, an older one, a restart
local lines = #mgRecs()
mgPoll()
mgExport(ROWS, { gen = acceptedGen - 5 })
mgPoll()
check(#mgRecs() == lines and Id.exportStatus().status == "stale", "an unchanged export writes nothing, and an older generatedAt is refused as stale")
check(mgAudits("IDENTITY_IMPORT", "COMPANION") == 1, "an export that changes nothing is not audited again")
mgExport(ROWS, { gen = acceptedGen })
nowMs = nowMs + 1000
fire("OnServerStarted")
check(#mgRecs() == lines and Id.exportStatus().status == "accepted" and Id.view().bindings["mg-ann"].exact == true,
    "after a restart the same export is read again at start and changes nothing")
-- a new generation with the same rows changes no binding but still leaves its generation and
-- digest, so after a restart an older export is stale and the same generation with other rows is refused
mgExport(ROWS)
mgPoll()
local newest = mgGen
check(Id.exportStatus().status == "accepted" and Id.exportStatus().generatedAt == newest and #mgRecs() == lines + 1
    and mgAudits("IDENTITY_IMPORT", "COMPANION") == 1,
    "a new generation that changes nothing writes only its marker (generation and row digest) and is not audited")
mgExport(ROWS, { gen = newest - 1 })
nowMs = nowMs + 1000
fire("OnServerStarted")
local staleAfterRestart = Id.exportStatus().status
local fewer = {}
for i = 1, #ROWS - 1 do fewer[i] = ROWS[i] end
mgExport(fewer, { gen = newest })
nowMs = nowMs + 1000
fire("OnServerStarted")
check(staleAfterRestart == "stale" and Id.exportStatus().status == "replaced" and #mgRecs() == lines + 1
    and Id.view().bindings["mg-p2"] ~= nil and Id.view().bindings["mg-p2"].reserved == nil,
    "after a restart an older export is stale, and the last accepted generation with other rows is refused whole")
local whyReplaced = Id.exportStatus().reason
-- exact mismatch, recorded once
local rows2 = {}
for i, r in ipairs(ROWS) do rows2[i] = r end
rows2[5] = { 5, "mg-exa", mgTwin(mgT(5)) }
mgExport(rows2)
mgPoll()
local conflictsFay, conflictsExa = 0, 0
for _, rec in ipairs(mgRecs("conflict")) do
    if rec.name == "mg-fay" then conflictsFay = conflictsFay + 1 end
    if rec.name == "mg-exa" then conflictsExa = conflictsExa + 1 end
end
check(mgSid(mgTwin(mgT(5))) == mgSid(mgT(5)) and Id.unresolved("mg-exa") == "EXACT_MISMATCH"
    and Id.view().bindings["mg-exa"].text == mgT(5) and mgAudits("BIND_CONFLICT", "EXACT_MISMATCH") == 1,
    "two exact texts of one double are two Steam accounts: EXACT_MISMATCH, and the binding stays")
check(S.login(mgPlayer("mg-exa", mgT(5))) == nil and S.login(mgPlayer("mg-exa", mgTwin(mgT(5)))) == nil
    and S.login(mgPlayer("mg-ann", mgT(1))) == "mg-ann",
    "a name under EXACT_MISMATCH verifies nobody (both Steam accounts pass the double); other names are unaffected")
check(conflictsFay == 1 and conflictsExa == 1 and mgAudits("BIND_CONFLICT", "SID_MISMATCH") == 1,
    "a conflict is recorded and audited once per name and SteamID, not once per export")
-- reservation thresholds of an automatic import
local short = { ROWS[1], ROWS[2] }
mgExport(short)
mgPoll()
check(Id.exportStatus().status == "reserve_suspect" and Id.view().bindings["mg-cat"] == nil,
    "an export that suddenly lacks more than max(5, 0.5%) of the last one's rows reserves nobody (reserve_suspect)")
local whyReserved = Id.exportStatus().reason
check(type(whyReplaced) == "table" and whyReplaced.code == "replaced" and type(whyReserved) == "table"
    and whyReserved.code == "reserved" and type(whyReserved.skipped) == "number" and type(whyReserved.dropped) == "number",
    "a replaced export and an import that reserved nobody report a code with their counts, not a sentence")
for i = 1, 51 do md.firstSeen["mg-k" .. i] = 1 end
mgExport(ROWS)
mgPoll()
local fiftyOne = Id.exportStatus().status
md.firstSeen["mg-k51"] = nil
mgExport(ROWS)
mgPoll()
check(fiftyOne == "reserve_suspect" and Id.exportStatus().status == "accepted" and Id.view().bindings["mg-k50"].reserved == true
    and Id.view().bindings["mg-k51"] == nil and #mgRecs("reserve") == 51,
    "an automatic import reserves at most 50 new names at once; within the thresholds it reserves them all")
-- the administrator's import shares the pipeline
local boss = mgPlayer("mg-boss", mgT(9)); boss.role = "admin"
onlinePlayers = { boss }
nowMs = nowMs + 700
sentCommands = {}
fire("OnClientCommand", EC.COMMAND_MODULE, "admin.identity", boss, { action = "import", requestId = "mg-i1",
    rows = { { u = "mg-boss", s = mgT(9) }, { u = "mg-man", s = mgT(6) }, { u = "mg-exa", s = mgTwin(mgT(5)) } } })
local reply = lastSent("admin.identity").args
local exaListed = false
for _, c in ipairs(reply.status.conflicts or {}) do
    if c.name == "mg-exa" and c.reason == "EXACT_MISMATCH" then exaListed = true end
end
check(reply.ok == true and reply.last.upgraded == 1 and Id.view().bindings["mg-man"].exact == true and exaListed
    and mgAudits("IDENTITY_IMPORT", "MANUAL") == 1,
    "an administrator's import upgrades exactly and reports EXACT_MISMATCH through the same pipeline")
check(reply.status.export.status == "accepted" and reply.status.merge ~= nil and reply.status.merge.enabled == false,
    "every admin.identity reply carries the export status and the merge summary")
onlinePlayers = {}
steamModeActive = false
end)()

-- ----- MG-2: groups, the canonical, the preview and the pass -----
;(function()
local Id, Mg = EC.Identity, S.Merge
local SV = SandboxVars.MinidoracatEconomy
local md = mgWorld()
local G, C1, H = mgT(20), mgT(21), mgT(22)
md.firstSeen["mg-g1"], md.firstSeen["mg-g3"] = 200, 100
fire("OnNewGame", mgPlayer("mg-grnd", G), nil)             -- a rounded double equal to G, never whitelisted
local ROWS = { { 1, "mg-boss", mgT(9) }, { 10, "mg-g1", G }, { 5, "mg-g2", G }, { 7, "mg-g3", G },
    { 11, "mg-c1", C1 }, { 12, "mg-c2", C1 }, { 13, "mg-c3", mgTwin(C1) } }
mgExport(ROWS)
mgPoll()
local g3, gGroup = mgMember("mg-g3")
local canon = mgRecs("canon")
check(g3 and g3.state == "canonical" and gGroup.account == "mg-g3" and #canon == 1 and canon[1].sid == G
    and canon[1].name == "mg-g3" and canon[1].rule == "firstSeen",
    "the group's account is the oldest economy name, decided once and written to the identity file")
local grnd = mgMember("mg-grnd")
check(grnd and grnd.state == "ineligible" and grnd.reason == "not_exact" and mgMember("mg-g2").state == "ready",
    "a name bound only by a rounded double is listed but never joins; the exact members are ready")
local c1 = mgMember("mg-c1")
check(mgSid(mgTwin(C1)) == mgSid(C1) and c1 and c1.state == "ineligible" and c1.reason == "collision"
    and mgMember("mg-c2").reason == "collision" and #mgRecs("canon") == 1,
    "two exact texts of one double never form a group: its members are ineligible (collision) and no account is chosen")
-- a later member with an older firstSeen is an alias of the recorded account
md.firstSeen["mg-g0"] = 1
local rows2 = { ROWS[1], ROWS[2], ROWS[3], ROWS[4], ROWS[5], ROWS[6], ROWS[7], { 14, "mg-g0", G } }
mgExport(rows2)
mgPoll()
check(mgMember("mg-g0").state == "ready" and mgMember("mg-g3").state == "canonical" and #mgRecs("canon") == 1,
    "a member joining later is an alias even with an older firstSeen: the decision is never recomputed")
-- a manual import (no whitelist ids) decides by name
local boss = mgPlayer("mg-boss", mgT(9)); boss.role = "admin"
onlinePlayers = { boss }
nowMs = nowMs + 700
fire("OnClientCommand", EC.COMMAND_MODULE, "admin.identity", boss, { action = "import", requestId = "mg-i2",
    rows = { { u = "mg-boss", s = mgT(9) }, { u = "mg-h2", s = H }, { u = "mg-h1", s = H } } })
local _, hGroup = mgMember("mg-h2")
check(hGroup and hGroup.account == "mg-h1" and mgMember("mg-h2").state == "ready" and #mgRecs("canon") == 2,
    "without firstSeen or whitelist ids the name decides, and an administrator's import updates the plan too")
onlinePlayers = {}
L.credit("mg-g1", "survivor", 50, "SYSTEM_MINT", { requestId = "mg-g1f", reasonCode = "t" })
nowMs = nowMs + 1000
fire("OnServerStarted")
local _, gAfter = mgMember("mg-g1")
local _, hAfter = mgMember("mg-h2")
check(gAfter and gAfter.account == "mg-g3" and hAfter and hAfter.account == "mg-h1" and #mgRecs("canon") == 2,
    "after a restart every group keeps its recorded account and nothing is decided again")
-- the preview, then the pass
local ready = {}
for _, g in ipairs(Mg.planGroups()) do
    for _, m in ipairs(g.members) do if m.state == "ready" then ready[#ready + 1] = m.name end end
end
EC.sortSafe(ready, function(a, b) return a < b end)
local planFile = files[Mg.PLAN_FILE] and files[Mg.PLAN_FILE].lines or {}
local summary = EC.jsonDecode(planFile[1] or "") or {}
check(table.concat(ready, ",") == "mg-g0,mg-g1,mg-g2,mg-h2" and EC.countKeys(md.identity.merged) == 0
    and summary.type == "merge-plan" and summary.enabled == false and summary.ready == 4 and #planFile == 1 + summary.groups,
    "with IdentityAutoMerge off the plan is published (a summary line, then one line per group) and nothing merges")
local gLine, g1Row = nil, nil
for i = 2, #planFile do
    local rec = EC.jsonDecode(planFile[i])
    if type(rec) == "table" and rec.sid == G then gLine = rec end
end
for _, m in ipairs(gLine and gLine.members or {}) do if m.name == "mg-g1" then g1Row = m end end
check(gLine and gLine.account == "mg-g3" and gLine.rule == "firstSeen" and g1Row and g1Row.state == "ready"
    and g1Row.balances.survivor.available == 50 and g1Row.whitelistId == 10,
    "each group line names its SteamID, account and rule, and every member's state, balances and whitelist id")
local consG = L.conservation("survivor")
SV.IdentityAutoMerge = true
nowMs = nowMs + Mg.TICK_MS + 1
fire("OnTickEvenPaused")
local done = {}
for name in pairs(md.identity.merged) do done[#done + 1] = name end
EC.sortSafe(done, function(a, b) return a < b end)
check(table.concat(done, ",") == table.concat(ready, ",") and md.identity.merged["mg-g0"].into == "mg-g3"
    and md.identity.merged["mg-h2"].into == "mg-h1" and mgAudits("ACCOUNT_MERGE_PASS") == 1,
    "the pass merges exactly the aliases the preview called ready, audited once for the pass")
check(md.firstSeen["mg-g3"] == 1 and md.firstSeen["mg-g0"] == nil,
    "the account is as old as its oldest login")
check(L.conservation("survivor") == consG and L.getBalance("mg-g3", "survivor").available == 50 and md.wallets["mg-g1"] == nil,
    "the pass moves the aliases' money to the account, conserved")
local events = mgEvents("identity.merged")
local private = events[1] and events[1].private or {}
local leaked = false
for _, e in ipairs(X.auditEntries()) do if e.steamId ~= nil then leaked = true end end
check(#events == 4 and (private.steamId == G or private.steamId == H) and events[1].steamId == nil and not leaked,
    "each merge emits identity.merged with the SteamID only in its private block, never in the audit ring")
-- a running pass merges at most TICK_MAX aliases
local many = { { 1, "mg-boss", mgT(9) } }
for i = 1, 13 do many[#many + 1] = { 100 + i, "mg-m" .. string.format("%02d", i), mgT(30) } end
mgExport(many)
mgPoll()
nowMs = nowMs + Mg.TICK_MS + 1
fire("OnTickEvenPaused")
local first = EC.countKeys(md.identity.merged) - 4
nowMs = nowMs + Mg.TICK_MS + 1
fire("OnTickEvenPaused")
check(first == Mg.TICK_MAX and EC.countKeys(md.identity.merged) - 4 == 12 and md.identity.merged["mg-m13"].into == "mg-m01",
    "a running pass merges at most ten aliases; the next pass takes the rest")
local more = { { 1, "mg-boss", mgT(9) } }
for i = 1, 12 do more[#more + 1] = { 200 + i, "mg-s" .. string.format("%02d", i), mgT(31) } end
mgExport(more)
nowMs = nowMs + 1000
fire("OnServerStarted")
md = S.modData()
local startMerged = 0
for i = 2, 12 do
    local rec = md.identity.merged["mg-s" .. string.format("%02d", i)]
    if rec and rec.into == "mg-s01" then startMerged = startMerged + 1 end
end
check(startMerged == 11 and mgAudits("ACCOUNT_MERGE_PASS", "start") == 1,
    "the start-up pass merges every ready alias at once, before any player can connect")
SV.IdentityAutoMerge = nil
steamModeActive = false
end)()

-- ----- MG-3: one merge moves everything, and a rollback merges it again -----
;(function()
local Id, Mg, M, Mk, Se = EC.Identity, S.Merge, S.Mailbox, S.Market, S.Seasons
local Rw, Rc = EC.Rewards, S.Recovery
local SV = SandboxVars.MinidoracatEconomy
local md = mgWorld()
local P = mgT(40)
local ROWS = { { 1, "mg-boss", mgT(9) }, { 2, "mg-main", P }, { 3, "mg-side", P }, { 4, "mg-oth", mgT(41) } }
mgExport(ROWS)
mgPoll()
local main, side, boss = mgPlayer("mg-main", P), mgPlayer("mg-side", P), mgPlayer("mg-boss", mgT(9))
boss.role, main.hours, side.hours = "admin", 50, 30
-- money, above the cap and in a paused currency
L.credit("mg-main", "survivor", 100, "SYSTEM_MINT", { requestId = "mg-f1", reasonCode = "t" })
L.credit("mg-side", "survivor", 300, "SYSTEM_MINT", { requestId = "mg-f2", reasonCode = "t" })
L.credit("mg-side", "cat", 20, "SYSTEM_MINT", { requestId = "mg-f3", reasonCode = "t" })
md.config.currencies.survivor = md.config.currencies.survivor or {}
md.config.currencies.cat = md.config.currencies.cat or {}
md.config.currencies.survivor.balanceMax = 250
md.config.currencies.cat.enabled = false
-- today's claims, milestones, lives
SV.CheckinDailyLimit = 2
onlinePlayers = { main, side }
Se.observe(main, nowMs); Se.observe(side, nowMs)
onlinePlayers = {}
local day = Rw.dayKey(nowMs)
for name, bit in pairs({ ["mg-main"] = 1, ["mg-side"] = 2 }) do
    local c = md.claims[name]
    c.day, c.paid, c.paidDay, c.claimedCount, c.playedMs, c.milestones = day, { [day] = 1 }, day, 1, 1000 * bit, bit
end
local _, metaBefore = Se.records("current")
-- counters
md.transferDaily[day] = { ["mg-main"] = 10, ["mg-side"] = 40 }
md.transferRecent["mg-main"] = { "mg-x", "mg-side" }
md.transferRecent["mg-side"] = { "mg-main", "mg-y", "mg-x" }
md.shopDaily[day] = { ["mg-main"] = { skuA = 2 }, ["mg-side"] = { skuA = 1 } }
md.shopLifetime["mg-side"] = { skuA = 5 }
md.shopBuyback[day] = { v = 2, byCurrency = { survivor = 5 }, accounts = { ["mg-side\1survivor"] = 5 }, skus = {} }
md.exchange.daily[day] = { total = { cat = 7 }, accounts = { ["mg-side\1cat"] = 7 } }
md.adminDaily[day] = { v = A.DAILY_VERSION, server = {}, admins = { ["mg-side"] = { survivor = { add = 3, sub = 1 } },
    ["mg-main"] = { survivor = { add = 2, sub = 0 } } } }
local letter = M.add("mg-side", { kind = "shop", item = "Base.Bandage", qty = 1, txId = "mg-tx" })
local unclaimedAll = md.mailbox.unclaimed
local consSurvivor, consCat = L.conservation("survivor"), L.conservation("cat")
local snap = proofSnapshot()
-- the merge
SV.IdentityAutoMerge = true
nowMs = nowMs + Mg.TICK_MS + 1
fire("OnTickEvenPaused")
local mark = md.identity.merged["mg-side"]
check(mark and mark.into == "mg-main" and type(mark.mergeId) == "string" and mark.epoch == md.meta.epoch
    and type(mark.seq) == "number" and type(mark.at) == "number",
    "the merge writes md.identity.merged[alias] = { into, mergeId, epoch, seq, at }")
check(mgMember("mg-side").state == "merged" and mgMember("mg-main").state == "canonical" and Mg.status().merged == 1,
    "the plan shows the alias as merged into its account")
check(L.getBalance("mg-main", "survivor").available == 400 and L.getBalance("mg-main", "cat").available == 20
    and md.wallets["mg-side"] == nil,
    "every currency's balance moves, above the balance cap and in a paused currency: merge money already exists")
check(L.conservation("survivor") == consSurvivor and L.conservation("cat") == consCat,
    "each currency is conserved across the account_merge transaction")
local receipts = L.receipts("mg-main")
local last = receipts[#receipts] or {}
check(last.kind == "account_merge" and last.counterparty == "mg-side" and md.receipts["mg-side"] == nil,
    "the account's statement shows the merge-in and the alias's receipt ring is gone")
md.config.currencies.survivor.balanceMax = nil          -- the cap gates new money again
L.credit("mg-side", "survivor", 1, "SYSTEM_MINT", { requestId = "mg-f4", reasonCode = "t" })
check(md.wallets["mg-side"] == nil and L.getBalance("mg-main", "survivor").available == 401,
    "after the merge a credit to the alias lands on the account")
local state = Rw.state("mg-main", nowMs)
check(state.claimedCount == 2 and state.remainingClaims == 0 and md.claims["mg-side"] == nil,
    "two logins that each claimed today have used two of the account's claims")
local records, metaAfter = Se.records("current")
local cm = md.claims["mg-main"]
check(cm.milestones == 3 and records ~= nil and metaAfter.participants == metaBefore.participants - 1
    and records["mg-side"] == nil and records["mg-main"] ~= nil,
    "milestones combine (never paid twice) and the season still reads, one participant fewer")
check(cm.survivalBase["mg-main"] == 50 and cm.survivalBase["mg-side"] == 30 and cm.playedMs == 2000,
    "each login keeps its own survival base inside the account's claim, and the connected time is the larger")
local recent = table.concat(md.transferRecent["mg-main"] or {}, ",")
check(md.transferDaily[day]["mg-main"] == 50 and md.transferDaily[day]["mg-side"] == nil and recent == "mg-x,mg-y"
    and md.transferRecent["mg-side"] == nil,
    "the daily transfer totals add up and the recent list keeps neither login of the account")
check(md.shopDaily[day]["mg-main"].skuA == 3 and md.shopLifetime["mg-main"].skuA == 5
    and md.shopBuyback[day].accounts["mg-main\1survivor"] == 5 and md.shopBuyback[day].accounts["mg-side\1survivor"] == nil
    and md.exchange.daily[day].accounts["mg-main\1cat"] == 7 and md.adminDaily[day].admins["mg-main"].survivor.add == 5
    and md.adminDaily[day].admins["mg-main"].survivor.sub == 1 and md.adminDaily[day].admins["mg-side"] == nil,
    "every per-person cap counter adds up: shop daily/lifetime/buyback, Discord deposits, admin adjustments")
check(md.mailbox.byOwner["mg-main"].entries[letter.id] == letter and letter.owner == "mg-main"
    and md.mailbox.byOwner["mg-side"] == nil and md.mailbox.unclaimed == unclaimedAll,
    "a clean ready letter moves to the account's box and the server-wide count stays")
local ev = mgEvents("identity.merged")[1] or {}
check(ev.alias == "mg-side" and ev.into == "mg-main" and ev.moved and ev.moved.survivor == 300 and ev.moved.cat == 20
    and ev.participantsDelta == -1 and ev.letters and ev.letters[1] == letter.id and type(ev.txId) == "string",
    "the merge event names the transaction, the amounts, the letters and the participant change")
-- the alias logs in: the account's
onlinePlayers = { side, boss }
local visits = {}
S.forEachOnline(function(p, account) visits[#visits + 1] = account end)
check(S.login(side) == "mg-side" and S.principal(side) == "mg-main" and S.onlinePlayer("mg-main") == side
    and S.onlineLogin("mg-side") == side and visits[1] == "mg-main",
    "a merged login is its own login and its account's principal everywhere")
local claimed = M.claim(side, letter.id)
check(claimed.ok == true and letter.claimLogin == "mg-side" and side.inventory.count("Base.Bandage") == 1,
    "the moved letter is claimed by the alias's login")
local _, scanned, scanTarget = A.recoveryRows("mg-side")
check(scanTarget == side and scanned ~= nil,
    "the administrator's recovery page walks the backpack of that very login, never another login of its account")
worldSprites = { ["100,200,0"] = "MinidoracatEconomy_terminal_0" }
nowMs = nowMs + 700
fire("OnClientCommand", EC.COMMAND_MODULE, "terminal.register", boss, { x = 100, y = 200, z = 0, kind = "atm", requestId = "mg-term" })
local axe = instanceItem("Base.Axe")
side.inventory:AddItem(axe)
nowMs = nowMs + 700
fire("OnClientCommand", EC.COMMAND_MODULE, "market.list", side, { itemId = axe.id, price = 200, currency = "survivor", requestId = "mg-list" })
local listed = lastSent("market.list") and lastSent("market.list").args or {}
proofSettle()
check(listed.ok == true and md.market.listings[listed.listingId].seller == "mg-main"
    and proofJournalRowOf("mg-side", listed.listingId) ~= nil and proofJournalRowOf("mg-main", listed.listingId) == nil,
    "a listing by the alias belongs to the account, while its recovery receipt stays with the login whose save it left")
onlinePlayers = { main, boss }
nowMs = nowMs + 700
fire("OnClientCommand", EC.COMMAND_MODULE, "hello", main, {})
fire("OnCharacterDeath", main)
