-- ===== 情境 MD：玩家 modData 是客戶端的（P0，.omc/tmp/moddata-fix/design.md §8.1）=====
-- ObjectModDataPacket 讓客戶端整份取代自己（與任何在線玩家）的 modData；這裡逐條證明：那張表
-- 的內容（見證、pendingOuts）不能打斷交付、不能讓信件重送、不能替別人結案、不能灌爆伺服器。
io.write("scenario MD: the player's own modData decides nothing\n")
;(function()
local M, Rc = S.Mailbox, S.Recovery
local KEY = EC.PLAYER_MODDATA_KEY
modDataStore[EC.MODDATA_KEY] = nil
files, sentCommands, sentItemPackets = {}, {}, {}
worldSprites = { ["100,200,0"] = "MinidoracatEconomy_terminal_0" }
onlinePlayers = {}
nowMs = nowMs + 61000
fire("OnServerStarted")
nowMs = nowMs + 1000
fire("OnServerStarted")                 -- a previous epoch in the history (MD-15/16)
local prev = S.modData().meta.history[#S.modData().meta.history]
local boss = fakePlayer("md-boss"); boss.role = "admin"
local function player(name, hours, capacity)
    local p = fakePlayer(name); p.x, p.y, p.hours = 101, 200, hours or 0
    p.inventory = fakeInventory(capacity or 1000)
    onlinePlayers[#onlinePlayers + 1] = p
    return p
end
onlinePlayers = { boss }
local serial = 0
local function cmd(who, name, args)
    serial, nowMs = serial + 1, nowMs + 600
    args = args or {}
    args.requestId = "md-" .. serial
    withCurrency(name, args)
    fire("OnClientCommand", EC.COMMAND_MODULE, name, who, args)
    for i = #sentCommands, 1, -1 do
        local s = sentCommands[i]
        if s.player == who and s.command == name and s.args.requestId == args.requestId then return s.args end
    end
    return nil
end
local function hello(who) nowMs = nowMs + 600; fire("OnClientCommand", EC.COMMAND_MODULE, "hello", who, {}) end
local function drop(who, t)
    for i = #who.inventory.items, 1, -1 do
        if who.inventory.items[i].fullType == t then table.remove(who.inventory.items, i) end
    end
end
local events = {}
local realEmit = X.emit
X.emit = function(kind, fields)
    if kind == "ledger.anomaly" then events[#events + 1] = fields end
    return realEmit(kind, fields)
end
local function count(resolution, mailId, reason)
    local n = 0
    for _, e in ipairs(events) do
        if e.resolution == resolution and (mailId == nil or e.mailId == mailId) and (reason == nil or e.reason == reason) then n = n + 1 end
    end
    return n
end
local function letter(owner, qty, item) return M.add(owner, { item = item or "Base.Bandage", qty = qty or 1, kind = "shop" }) end
assert(cmd(boss, "terminal.register", { x = 100, y = 200, z = 0, kind = "atm" }).ok)

-- MD-1/2: a claims value that is not a table cannot stop a delivered claim halfway
local a = player("md-a")
local other = letter("md-a")
a.modData[KEY] = { claims = { [other.id] = true }, pendingOuts = {} }
local L1 = letter("md-a")
local ok1, r1 = pcall(M.claim, a, L1.id)
check(ok1 and r1.ok == true and L1.state == "claimed" and a.inventory.count("Base.Bandage") == 1,
    "MD-1: a poisoned claims table cannot interrupt a claim: it is delivered and settled")
local ok2, r2 = pcall(M.claim, a, L1.id)
check(ok2 and r2.error == "already_claimed" and a.inventory.count("Base.Bandage") == 1,
    "MD-2: the same letter is never handed over a second time")
-- MD-3: the split path settles the child and the parent before anything a save holds is read
local b = player("md-b", 0, 7)
b.modData[KEY] = { claims = { [other.id] = true }, pendingOuts = {} }
local L3 = letter("md-b", 3, "Base.Plank")
local ok3, r3 = pcall(M.claim, b, L3.id)
local child3 = ok3 and M.entryOf("md-b", r3.childMailId) or nil
local overlap = false
for _, t in ipairs(child3 and child3.units or {}) do
    for _, u in ipairs(L3.units) do if t == u then overlap = true end end
end
check(child3 ~= nil and child3.state == "claimed" and L3.state == "ready" and #L3.units == 1 and not overlap
    and b.inventory.count("Base.Plank") == 2,
    "MD-3: a split claim settles its child and cuts the parent down to the rest, with no token in both")
-- MD-4: a pendingOuts value that is not a table cannot break a list-out
L.credit("md-a", "survivor", 1000, "SYSTEM_MINT", { requestId = "md-seed-a", reasonCode = "t" })
local axe = instanceItem("Base.Axe"); a.inventory:AddItem(axe)
a.modData[KEY].pendingOuts = { junk = 5 }
local listed = cmd(a, "market.list", { itemId = axe.id, price = 10 })
check(listed ~= nil and (listed.ok == true or type(listed.error) == "string"),
    "MD-4: a junk pendingOuts value gets an ordinary answer to a list-out, not a crash")
-- MD-5: a key this server never writes cannot stop the reconcile
a.modData[KEY].pendingOuts = { [{}] = {} }
local okR, done = pcall(M.reconcile, a)
local tableKey = false
for key in pairs(a.modData[KEY].pendingOuts) do if type(key) ~= "string" then tableKey = true end end
check(okR and done == true and not tableKey and count("pending-key-dropped") == 1,
    "MD-5: a table-keyed pending is dropped and the reconcile completes")

-- MD-6: wiping the claims table and saying hello in the same session redelivers nothing
local c = player("md-c", 5)
fire("OnTickEvenPaused")                -- first sighting: this session's save loaded at 5 h
c.hours = 6
local L6 = letter("md-c", 2)
assert(M.claim(c, L6.id).ok)
local again6 = 0
for _ = 1, 3 do
    drop(c, "Base.Bandage")
    c.modData[KEY] = { claims = {}, pendingOuts = {} }
    hello(c)
    again6 = again6 + c.inventory.count("Base.Bandage")
end
check(again6 == 0 and L6.state == "claimed", "MD-6: a wiped claims table and hello in the same session redeliver nothing")
-- MD-13/7: a letter claimed before anchors existed is not redelivered, and says so once a session
local d = player("md-d")
local L7 = letter("md-d", 1)
assert(M.claim(d, L7.id).ok)
L7.claimHours, L7.claimSess, L7.claimLife = nil, nil, nil
drop(d, "Base.Bandage")
d = newSave(d, 3)
hello(d)
check(d.inventory.count("Base.Bandage") == 0
    and count("redelivery-refused", L7.id, "unanchored") == 1,
    "MD-13: a claimed letter with no anchor and no stamp is not redelivered, and the refusal names it unanchored")
hello(d); hello(d)
check(count("redelivery-refused", L7.id) == 1 and d.inventory.count("Base.Bandage") == 0,
    "MD-7: one refusal event per letter per session, however often hello comes")
-- MD-14: an unanchored letter whose stamped object is in the backpack is simply fine
local L14 = letter("md-d", 1)
assert(M.claim(d, L14.id).ok)
L14.claimHours, L14.claimSess, L14.claimLife = nil, nil, nil
hello(d)
check(count("redelivery-refused", L14.id) == 0 and d.inventory.count("Base.Bandage") == 1,
    "MD-14: an unanchored letter whose stamp is in the backpack raises nothing")

-- MD-8/9/10: the save's hours against the claim's decide, once per session
local e = player("md-e", 10)
local L8 = letter("md-e", 2)
assert(M.claim(e, L8.id).ok)
drop(e, "Base.Bandage")
e = newSave(e, 12)
hello(e)
check(e.inventory.count("Base.Bandage") == 0 and L8.state == "claimed",
    "MD-8: a save written after the claim (more hours) gets nothing again")
e = newSave(e, 8)
hello(e)
check(e.inventory.count("Base.Bandage") == 2, "MD-9: a save written before the claim (fewer hours) is handed the letter again")
drop(e, "Base.Bandage")
e.modData[KEY] = { claims = {}, pendingOuts = {} }
hello(e)
check(e.inventory.count("Base.Bandage") == 0, "MD-10: that redelivery is anchored to this session: wiping again gets nothing")
-- MD-11: seventy claims used up, five logins: nothing comes back
local f = player("md-f", 10)
for _ = 1, 70 do
    local l = letter("md-f", 1)
    assert(M.claim(f, l.id).ok)
end
drop(f, "Base.Bandage")
local again11 = 0
for i = 1, 5 do
    f = newSave(f, 10 + i)
    hello(f)
    again11 = again11 + f.inventory.count("Base.Bandage")
end
check(again11 == 0, "MD-11: seventy claimed and used letters stay used over five logins")
-- MD-12: equal hours cannot tell which came first: nothing is redelivered, and it says tie
local g = player("md-g", 10)
local L12 = letter("md-g", 1)
assert(M.claim(g, L12.id).ok)
drop(g, "Base.Bandage")
g = newSave(g, 10)
hello(g)
check(g.inventory.count("Base.Bandage") == 0 and count("redelivery-refused", L12.id, "tie") == 1,
    "MD-12: a save at exactly the claim's hours is not handed it again, and the refusal says tie")

-- MD-15: a pending of mine naming another account's letter cannot close it
local v = player("md-v")
local V1 = letter("md-v", 1)
local h = player("md-h")
local forged = tostring(prev.epoch) .. ":" .. tostring(prev.loadedSeq + 1)
h.modData[KEY] = { pendingOuts = { [forged] = { protocol = 2, epoch = prev.epoch, seq = prev.loadedSeq + 1,
    snapshot = { type = "Base.Bandage" }, origins = { { src = "mail", mailId = V1.id, owner = "md-v", unit = V1.units[1] } } } } }
hello(h)
check(V1.state == "ready" and M.claim(v, V1.id).ok == true and v.inventory.count("Base.Bandage") == 1,
    "MD-15: another account's ready letter stays ready and its owner claims it")
-- MD-16/17: a witness written into a save - rolled-back epoch or this one - closes nothing
local V2 = letter("md-v", 1)
v.modData[KEY] = { claims = { [V2.id] = { epoch = prev.epoch, seq = prev.loadedSeq + 1 } }, pendingOuts = {} }
hello(v)
check(V2.state == "ready" and M.claim(v, V2.id).ok == true and v.inventory.count("Base.Bandage") == 2,
    "MD-16: a forged witness with a rolled-back epoch in a victim's save does not close the victim's letter")
local V3 = letter("md-v", 1)
v.modData[KEY] = { claims = { [V3.id] = { epoch = S.modData().meta.epoch, seq = 1 } }, pendingOuts = {} }
hello(v)
check(V3.state == "ready" and (v.modData[KEY].claims == nil), "MD-17: a current-epoch witness closes nothing and the table is dropped")

-- MD-18/19: a new character without a death. OnNewGame fires on a temporary object while the old
-- main-seat object is still online (CreatePlayerPacket.java:288-303); the new object comes after.
-- CreatePlayer writes the new row at once (:302-303) whether or not the old one died, so the mark
-- is set beside a living seat too.
local i1 = player("md-i", 10)
local L18 = letter("md-i", 1)
assert(M.claim(i1, L18.id).ok)
fire("OnNewGame", fakePlayer("md-i"), nil)
local i2 = fakePlayer("md-i"); i2.x, i2.y = 101, 200
for n, p in ipairs(onlinePlayers) do if p == i1 then onlinePlayers[n] = i2 end end
hello(i2)
-- A lifeBreak mark alone never starts a life (only a death the server saw does): the letter stays
-- claimed, nothing is handed over, and no record waits on an administrator
check(L18.state == "claimed" and i2.inventory.count("Base.Bandage") == 0 and Rc.life("md-i") == 0
    and #Rc.heldRecords("md-i") == 0,
    "MD-18: a new character made without a death leaves the old letter claimed, handed over to nobody")
local j = player("md-j", 10)
local L19 = letter("md-j", 1)
assert(M.claim(j, L19.id).ok)
drop(j, "Base.Bandage")
local seat = fakePlayer("md-j")
fire("OnNewGame", seat, nil)            -- a split-screen seat's character fires it under the main login
hello(j)
check(L19.state == "claimed" and L19.lifeBreak ~= nil and j.inventory.count("Base.Bandage") == 0,
    "MD-19: the same character going on keeps its letter claimed; the mark waits for another object")
-- the cost of marking beside a living seat: an older save of that main character (V3) is refused
-- its redelivery - one event naming the item, for an administrator to make good by hand
local j2 = newSave(j, 5)
hello(j2)
check(L19.state == "claimed" and j2.inventory.count("Base.Bandage") == 0
    and count("redelivery-refused", L19.id, "lifebreak_unproven") == 1,
    "MD-19b: the cost of that mark: an older save of the main seat is refused its redelivery, with one event")

-- MD-20: a pending table no server path could fill is one record, not a flood
local k = player("md-k")
local big = {}
for n = 1, Rc.PENDING_MAX + 1 do big["1600000000000:" .. n] = { protocol = 2, epoch = "1600000000000", seq = n } end
k.modData[KEY] = { pendingOuts = big }
hello(k)
local pendHolds = 0
for _, rec in ipairs(Rc.heldRecords("md-k")) do
    if string.sub(rec.key, 1, 5) == "pend:" then pendHolds = pendHolds + 1 end
end
check(pendHolds == 1 and Rc.heldRecord("md-k", "pend:oversized") ~= nil,
    "MD-20: an oversized pending table is one pend:oversized record and nothing in it is judged")
-- MD-21/22: receipt-less pendings are held at a bounded rate, close when withdrawn, and block nothing
local m = player("md-m")
L.credit("md-m", "survivor", 1000, "SYSTEM_MINT", { requestId = "md-seed-m", reasonCode = "t" })
local function pendHeldEvents()
    local n = 0
    for _, ev in ipairs(events) do
        if ev.resolution == "held" and ev.username == "md-m" and string.sub(tostring(ev.key), 1, 5) == "pend:" then n = n + 1 end
    end
    return n
end
local out22 = nil
for round = 1, 3 do
    local batch = {}
    for n = 1, Rc.PENDING_MAX do batch["md-junk:" .. round .. ":" .. n] = 5 end
    m.modData[KEY] = { pendingOuts = batch }
    hello(m)
    if round == 1 then                  -- a full working set of the player's own claims is open now
        local saw = instanceItem("Base.Saw"); m.inventory:AddItem(saw)
        out22 = cmd(m, "market.list", { itemId = saw.id, price = 10 })
    end
end
local open = 0
for _, rec in ipairs(Rc.heldRecords("md-m")) do
    if string.sub(rec.key, 1, 5) == "pend:" then open = open + 1 end
end
check(open <= Rc.PENDING_MAX and Rc.heldRecord("md-m", "pend:md-junk:1:1") == nil
    and pendHeldEvents() <= Rc.CLAIMED_HOLDS_PER_HOUR + 1,
    "MD-21: three batches of claimed pendings stay bounded, the withdrawn batch is closed, and the hold events are rate-limited")
check(out22 ~= nil and out22.ok == true, "MD-22: the player's own claims never lock them out with held_limit_reached")

-- MD-23/24: a world save older than the player save; the client claims before it says hello
local function v2(name)
    local p = player(name, 10)
    local l = letter(name, 2)
    local saved = {}
    for key, val in pairs(l) do saved[key] = val end
    saved.units = { l.units[1], l.units[2] }
    assert(M.claim(p, l.id).ok)
    local box = S.modData().mailbox.byOwner[name]
    box.entries[l.id] = saved
    box.unclaimed = box.unclaimed + 1
    S.modData().mailbox.unclaimed = S.modData().mailbox.unclaimed + 1
    return newSave(p, 12), l.id
end
local n2, id23 = v2("md-n")
fire("OnTickEvenPaused")                -- first sighting, before any command
check(M.entryOf("md-n", id23).state == "claimed" and cmd(n2, "mail.claim", { mailId = id23 }).error == "already_claimed"
    and n2.inventory.count("Base.Bandage") == 2,
    "MD-23: the first tick marks the letter claimed from the stamps the save loaded with")
local o2, id24 = v2("md-o")
local claimed24 = cmd(o2, "mail.claim", { mailId = id24 })
check(claimed24 ~= nil and claimed24.error == "already_claimed" and o2.inventory.count("Base.Bandage") == 2,
    "MD-24: a claim sent before hello is answered after a full reconcile: no second copy")
X.emit = realEmit
onlinePlayers = {}
end)()

-- ===== 情境 LG：回滾帳本（P1，design.md §5 P1-1..P1-4）=====
-- 世界回滾會忘掉的事（領取、session 開始、生命）寫在不回滾的帳本檔；啟動時收割。每一段都是
-- 「真的操作 → 帳本落盤 → 世界回到快照（崩潰）→ 某一份玩家存檔上線」。
io.write("scenario LG: what a world rollback forgot is judged from the ledger\n")
;(function()
local M, Mk, Rc = S.Mailbox, S.Market, S.Recovery
local function deep(v)
    if type(v) ~= "table" then return v end
    local out = {}
    for k, x in pairs(v) do out[k] = deep(x) end
    return out
end
local serial = 0
local function cmd(who, name, args)
    serial, nowMs = serial + 1, nowMs + 600
    args = args or {}
    args.requestId = "rl-" .. serial
    withCurrency(name, args)
    fire("OnClientCommand", EC.COMMAND_MODULE, name, who, args)
    for i = #sentCommands, 1, -1 do
        local s = sentCommands[i]
        if s.player == who and s.command == name and s.args.requestId == args.requestId then return s.args end
    end
    return {}
end
local function hello(who) nowMs = nowMs + 600; fire("OnClientCommand", EC.COMMAND_MODULE, "hello", who, {}) end
local events = {}
local realEmit = X.emit
X.emit = function(kind, fields)
    if kind == "ledger.anomaly" then events[#events + 1] = fields end
    return realEmit(kind, fields)
end
local function count(resolution)
    local n = 0
    for _, e in ipairs(events) do if e.resolution == resolution then n = n + 1 end end
    return n
end
local function world()
    modDataStore[EC.MODDATA_KEY] = nil
    files, sentCommands, sentItemPackets = {}, {}, {}
    worldSprites = { ["100,200,0"] = "MinidoracatEconomy_terminal_0" }
    onlinePlayers = {}
    nowMs = nowMs + 61000
    fire("OnServerStarted")
    local boss = fakePlayer("rl-boss"); boss.role = "admin"
    onlinePlayers = { boss }
    assert(cmd(boss, "terminal.register", { x = 100, y = 200, z = 0, kind = "atm" }).ok)
    onlinePlayers = {}
end
-- one save of `name` comes online and is seen by one tick (its first sighting)
local function login(name, hours, inv, data)
    local p = fakePlayer(name); p.x, p.y, p.hours = 101, 200, hours
    p.inventory, p.modData = inv or fakeInventory(1000), data or {}
    for i = #onlinePlayers, 1, -1 do
        if onlinePlayers[i]:getUsername() == name then table.remove(onlinePlayers, i) end
    end
    onlinePlayers[#onlinePlayers + 1] = p
    fire("OnTickEvenPaused")
    return p
end
-- a crash: what was flushed stays on disk, the world goes back to `snap`, nobody is online
local function crash(snap)
    proofSettle()
    onlinePlayers = {}
    modDataStore[EC.MODDATA_KEY] = deep(snap)
    nowMs = nowMs + 1000
    fire("OnServerStarted")
end
local function claimed(name, hours, qty, item)
    world()
    local p = login(name, hours)
    local l = M.add(name, { item = item or "Base.Bandage", qty = qty or 2, kind = "shop" })
    local snap = proofSnapshot()
    return p, l, snap
end

-- LG-1: the world forgot a claim the loaded save has: marked claimed at the first tick
local p, l, snap = claimed("rl-a", 10)
assert(M.claim(p, l.id).ok)
p.inventory.items = {}                  -- used up
crash(snap)
local p2 = login("rl-a", 12)
check(M.entryOf("rl-a", l.id).state == "claimed" and cmd(p2, "mail.claim", { mailId = l.id }).error == "already_claimed"
    and p2.inventory.count("Base.Bandage") == 0 and count("mark-claimed-ledger") == 1,
    "LG-1: a claim the world lost but the save holds is closed from the ledger, and cannot be claimed again")
-- LG-3: the save predates that claim: the letter is still owed, once
p, l, snap = claimed("rl-b", 10)
assert(M.claim(p, l.id).ok)
crash(snap)
p2 = login("rl-b", 5)
check(M.entryOf("rl-b", l.id).state == "ready" and cmd(p2, "mail.claim", { mailId = l.id }).ok == true
    and p2.inventory.count("Base.Bandage") == 2,
    "LG-3: a save older than the lost claim never had the objects: the letter stays claimable")
-- LG-4: that older save played on past the claim's hours - and the world lost the record of it
p, l, snap = claimed("rl-c", 10)
assert(M.claim(p, l.id).ok)
crash(snap)
login("rl-c", 5)                        -- the fork: a save below the claim was loaded
crash(snap)
p2 = login("rl-c", 20)
check(M.entryOf("rl-c", l.id).state == "ready" and cmd(p2, "mail.claim", { mailId = l.id }).ok == true,
    "LG-4: a save forked below the claim stays excluded however far it played, from the ledger's own start line")
-- LG-child: a split child the world lost is carved out of its parent again
world()
p = login("rl-d", 10, fakeInventory(7))
l = M.add("rl-d", { item = "Base.Plank", qty = 5, kind = "shop" })
snap = proofSnapshot()
local partial = M.claim(p, l.id)
assert(partial.error == "delivery_partial" and partial.deliveredQty == 2)
crash(snap)
p2 = login("rl-d", 12)
local child = M.entryOf("rl-d", partial.childMailId)
local rest = cmd(p2, "mail.claim", { mailId = l.id })
check(child ~= nil and child.state == "claimed" and #child.units == 2 and rest.ok == true
    and p2.inventory.count("Base.Plank") == 3,
    "LG-child: the lost child comes back claimed under its own id and the parent hands over only its three")
-- LG-old-life: a claim and the death after it, both forgotten: the claim went with that character
p, l, snap = claimed("rl-e", 10)
assert(M.claim(p, l.id).ok)
fire("OnCharacterDeath", p)
crash(snap)
p2 = login("rl-e", 1)
check(M.entryOf("rl-e", l.id).state == "settled" and cmd(p2, "mail.claim", { mailId = l.id }).error == "already_claimed"
    and p2.inventory.count("Base.Bandage") == 0,
    "LG-old-life: a lost claim of a character that died since is settled, not handed to the next one")
-- LG-11: the world went back to before a death only: that character's claim is settled too
p, l, snap = claimed("rl-f", 10)
assert(M.claim(p, l.id).ok)
snap = proofSnapshot()
fire("OnCharacterDeath", p)
crash(snap)
p2 = login("rl-f", 1)
hello(p2)
check(M.entryOf("rl-f", l.id).state == "settled" and p2.inventory.count("Base.Bandage") == 0,
    "LG-11: a rollback to before the death settles the dead character's claim instead of redelivering it")

-- list-outs: the save that comes back must really have had the objects taken out
local function listed(name, hours)
    world()
    local seller = login(name, hours)
    L.credit(name, "survivor", 1000, "SYSTEM_MINT", { requestId = name .. "-seed", reasonCode = "t" })
    local axe = instanceItem("Base.Axe"); seller.inventory:AddItem(axe)
    local before = proofSnapshot()
    local out = cmd(seller, "market.list", { itemId = axe.id, price = 10 })
    assert(out.ok, tostring(out.error))
    return out.listingId, before, deep(seller.modData)
end
local function reason(name, id)
    local rec = Rc.heldRecord(name, "pend:" .. id)
    return rec and not rec.resolvedAt and rec.reason or nil
end
-- A pending the save provably never had is discarded by the server itself, exactly as the
-- administrator's discard did (a void receipt, nothing refunded), with one event naming how it was
-- proven and a SYSTEM audit line; no record is opened, so nothing counts against the held limit
local function autoDiscarded(name, id, who, proof)
    local ev, audited = nil, false
    for _, e in ipairs(events) do
        if e.resolution == "pending-auto-discarded" and e.opId == id then ev = e end
    end
    for _, a in ipairs(X.auditEntries()) do
        if a.action == "recovery" and a.admin == "SYSTEM" and a.field == id and a.after == "discard" then audited = true end
    end
    local receipt = Rc.receipt(id)
    local data = who.modData[EC.PLAYER_MODDATA_KEY]
    local pend = type(data) == "table" and type(data.pendingOuts) == "table" and data.pendingOuts[id] or nil
    return not Mk.listingExists(id) and reason(name, id) == nil and Rc.heldCount(name, true) == 0
        and receipt ~= nil and receipt.kind == "discard" and pend == nil
        and ev ~= nil and ev.item == "Base.Axe" and ev.qty == 1 and ev.proof == proof and audited
end
-- LG-6: both went back below the listing; the client replays the pending and drops the axe
local id, before, replay = listed("rl-g", 10)
crash(before)
local g = login("rl-g", 5, fakeInventory(1000), deep(replay))
hello(g); proofPump("rl-g")
check(autoDiscarded("rl-g", id, g, "hours"),
    "LG-6: a replayed pending on a save from before the listing is discarded by the server, never rebuilt")
local admin = fakePlayer("rl-boss"); admin.role = "admin"
onlinePlayers[#onlinePlayers + 1] = admin
local row = nil
for _, r in ipairs(cmd(admin, "admin.recovery", { action = "list", username = "rl-g" }).records or {}) do
    if r.key == "pend:" .. id then row = r end
end
hello(g); proofPump("rl-g")
check(row == nil and autoDiscarded("rl-g", id, g, "hours") and g.inventory.count("Base.Axe") == 0,
    "LG-admin: nothing is left for the administrator, and a later login stays closed")
-- LG-7: the older save played on first, then replayed
id, before, replay = listed("rl-h", 10)
crash(before)
local h1 = login("rl-h", 5)
h1.inventory:AddItem(instanceItem("Base.Axe"))
hello(h1)
local h2 = login("rl-h", 20, fakeInventory(1000), deep(replay))
hello(h2); proofPump("rl-h")
check(autoDiscarded("rl-h", id, h2, "fork"),
    "LG-7: a save that loaded below the listing stays excluded after playing past it")
-- LG-tie: a save within one tick of the commit may be the one written right after it: nothing
-- proves it lacks the transfer, so the server does not void it - it stays a hold the
-- administrator can close (and cannot rebuild)
do
    local idT, beforeT, replayT = listed("rl-t", 10)
    crash(beforeT)
    local gt = login("rl-t", 10 + Rc.TICK_EPS_MIN / 2, fakeInventory(1000), deep(replayT))
    hello(gt); proofPump("rl-t")
    onlinePlayers[#onlinePlayers + 1] = admin
    local rowT = nil
    for _, r in ipairs(cmd(admin, "admin.recovery", { action = "list", username = "rl-t" }).records or {}) do
        if r.key == "pend:" .. idT then rowT = r end
    end
    check(reason("rl-t", idT) == "pending_not_in_save" and Rc.receipt(idT) == nil and not Mk.listingExists(idT)
        and rowT ~= nil
        and rowT.actions.discard == true and rowT.actions.restore == false,
        "LG-tie: a save within a tick of the commit is held for the administrator, never voided by the server")
    -- the same character plays on and comes back well past the commit: the tie start of its first
    -- login lies within the tick band, which may refuse the rebuild but proves nothing
    local gt2 = login("rl-t", 20, fakeInventory(1000), gt.modData)
    hello(gt2); proofPump("rl-t")
    check(reason("rl-t", idT) == "pending_not_in_save" and Rc.receipt(idT) == nil and not Mk.listingExists(idT),
        "LG-tie2: a later login past the commit does not turn the earlier tie start into proof: still held, not voided")
end
-- LG-8: the ordinary crash - the player save is newer than the world save - still rebuilds
id, before, replay = listed("rl-i", 10)
crash(before)
local i2 = login("rl-i", 12, fakeInventory(1000), deep(replay))
hello(i2); proofPump("rl-i")
check(Mk.listingExists(id) and i2.inventory.count("Base.Axe") == 0,
    "LG-8: a save written after the listing gets its lost listing rebuilt")
-- LG-9: within a tick of the commit the order cannot be told. A save is judged by its own hours
-- even before its start line exists (an administrator acting on a player seen this very tick)
local fresh = fakePlayer("rl-j"); fresh.hours = 10 + Rc.TICK_EPS_MIN / 2
local first = { h = 10, life = 0, epoch = S.modData().meta.epoch, seq = S.modData().meta.seq }
check(Rc.outOrder("rl-j", first, fresh) == "tie" and Rc.outOrder("rl-j", first, newSave(fresh, 5)) == "excluded",
    "LG-9: a save within one tick of the commit is a tie, one below it is excluded, whether or not its start is on record")
-- LG-10: listed, died, the pending rode to the new character, then the world lost all of it. Only
-- the ledger says the old life ended, so the save that loads may be either character: held, and
-- the administrator may rebuild it from the journal record
id, before = listed("rl-k", 10)
local k1 = onlinePlayers[#onlinePlayers]
fire("OnCharacterDeath", k1)
local k2 = fakePlayer("rl-k"); k2.x, k2.y = 101, 200
onlinePlayers[#onlinePlayers] = k2
fire("OnNewGame", k2, nil)
local carried = deep(k2.modData)
crash(before)
local k3 = login("rl-k", 1, fakeInventory(1000), carried)
hello(k3); proofPump("rl-k")
onlinePlayers[#onlinePlayers + 1] = admin
local row10 = nil
for _, r in ipairs(cmd(admin, "admin.recovery", { action = "list", username = "rl-k" }).records or {}) do
    if r.key == "pend:" .. id then row10 = r end
end
check(not Mk.listingExists(id) and reason("rl-k", id) == "pending_life_unproven"
    and row10 ~= nil and row10.actions.restore == true and row10.actions.discard == true,
    "LG-10: a listing carried over a death the world lost is held, and the administrator may rebuild or close it")
-- LG-legacy: a journal line from before the anchors keeps the old judgement and says so
id, before, replay = listed("rl-l", 10)
proofSettle()
local jf = files[proofJournalPathForOp("rl-l", id)]
for n, line in ipairs(jf.lines) do
    jf.lines[n] = string.gsub(string.gsub(string.gsub(line, ',"h":[^,}]*', ""), ',"life":[^,}]*', ""), ',"sess":"[^"]*"', "")
end
crash(before)
local l2 = login("rl-l", 5, fakeInventory(1000), deep(replay))
hello(l2); proofPump("rl-l")
check(Mk.listingExists(id) and count("journal-unanchored") == 1,
    "LG-legacy: an unanchored journal line is judged as before and reported once")

-- LG-12/13: the session's hours come from its first tick; the tie band from the tick step
world()
local q = login("rl-m", 3)
q.hours = 4
hello(q)
check(Rc.session(q).h0 == 3, "LG-12: a session's save hours are taken at its first tick, not at its first command")
fire("OnTickEvenPaused")               -- one step of 1 h (3 -> 4) seen by the probe
q.hours = 4.5
fire("OnTickEvenPaused")               -- then a smaller one
check(Rc.tickEps() == 1, "LG-13: the tie band follows the largest per-tick hours step seen")

-- ===== RV: the review of the moddata fix (five findings, two residuals) =====
local J = S.RecoveryJournal
-- RV-1: a claim the first crash excluded, a legitimate re-claim, a second crash: the save holds
-- the re-claim, so the letter is not handed over a third time
do
    local pa, la, snapA = claimed("rv-a", 10)
    assert(M.claim(pa, la.id).ok)
    crash(snapA)
    local pa2 = login("rv-a", 5)
    assert(M.entryOf("rv-a", la.id).state == "ready")
    pa2.hours = 6
    assert(M.claim(pa2, la.id).ok)
    pa2.inventory.items = {}
    crash(snapA)
    local pa3 = login("rv-a", 7)
    check(M.entryOf("rv-a", la.id).state == "claimed" and cmd(pa3, "mail.claim", { mailId = la.id }).error == "already_claimed"
        and pa3.inventory.count("Base.Bandage") == 0,
        "RV-1: every lost claim of a letter is kept: the re-claim after a first crash still closes it after a second")
end
-- RV-2: listed, died, both saves back below the listing: the harvested life is no proof the old
-- character is gone, so a replayed pending on it is not rebuilt
do
    local idB, beforeB, replayB = listed("rv-b", 10)
    fire("OnCharacterDeath", onlinePlayers[#onlinePlayers])
    crash(beforeB)
    local gb = login("rv-b", 5, fakeInventory(1000), deep(replayB))
    hello(gb); proofPump("rv-b")
    check(not Mk.listingExists(idB) and reason("rv-b", idB) == "pending_life_unproven",
        "RV-2: a life only the ledger raised does not skip the save's hours: the old character's replay is held")
    -- the old character plays past the listing and loads again: its earlier start was one of
    -- either life, so it is still a fork of the old one
    local gb2 = login("rv-b", 20, fakeInventory(1000), deep(replayB))
    hello(gb2); proofPump("rv-b")
    check(not Mk.listingExists(idB) and reason("rv-b", idB) == "pending_life_unproven",
        "RV-2c: a start whose character was not proven counts as a fork of the old life too")
    local meta = S.modData().meta
    S.modData().recovery.lives["rv-x"] = { life = 1, seen = 0, starts = {} }
    local px = fakePlayer("rv-x"); px.hours = 5
    check(Rc.outOrder("rv-x", { h = 10, life = 0, epoch = meta.epoch, seq = meta.seq }, px) == "life_unproven",
        "RV-2b: with no start on record the save's own hours still decide across a life only the ledger raised")
end
-- RV-9: a letter with more lost claims than kept is judged claimed outright
do
    world()
    local lo = M.add("rv-o", { item = "Base.Bandage", qty = 1, kind = "shop" })
    S.modData().recovery.lost["rv-o"] = { [lo.id] = { l = "rv-o", claims = {}, n = M.LOST_PER_LETTER, over = true } }
    login("rv-o", 10)
    check(M.entryOf("rv-o", lo.id).state == "claimed", "RV-9: past the per-letter bound the letter is claimed, never left ready")
end
-- RV-3: the fork start is pushed out by more sessions than a login keeps: its trace stays
do
    local idC, beforeC, replayC = listed("rv-c", 10)
    crash(beforeC)
    login("rv-c", 5)                     -- the fork: a save below the listing, still holding the axe
    for i = 1, Rc.STARTS_MAX + 1 do login("rv-c", 20 + i) end
    local gc = login("rv-c", 200, fakeInventory(1000), deep(replayC))
    hello(gc); proofPump("rv-c")
    -- only the trimmed-start floor says a fork may have happened: no proof either way, so it is
    -- held for the administrator (discard-only), never voided by the server
    check(not Mk.listingExists(idC) and reason("rv-c", idC) == "pending_not_in_save" and Rc.receipt(idC) == nil,
        "RV-3: trimming the start lines leaves a floor: a transfer before it is held, neither rebuilt nor voided")
end
-- RV-4a: a lost claim far down a long ledger file is still found
do
    local pd, ld, snapD = claimed("rv-d", 10)
    local epochD = S.modData().meta.epoch
    assert(M.claim(pd, ld.id).ok)
    pd.inventory.items = {}
    proofSettle()
    local fd = files[J.ledgerPath(epochD)]
    local real, pad = fd.lines, 200000
    local filler = '{"k":"start","l":"rv-pad","life":0,"s":1,"t":"recovery.ledger","v":1}'
    fd.lines = setmetatable({}, { __index = function(_, i) if i <= pad then return filler end return real[i - pad] end })
    crash(snapD)
    local pd2 = login("rv-d", 12)
    check(M.entryOf("rv-d", ld.id).state == "claimed" and cmd(pd2, "mail.claim", { mailId = ld.id }).error == "already_claimed",
        "RV-4a: the ledger is read to its end: a claim after two hundred thousand rows still closes its letter")
end
-- RV-4b: a ledger file that exists and cannot be opened: old letters and old transfers wait
do
    world()
    local pe = login("rv-e", 10)
    L.credit("rv-e", "survivor", 1000, "SYSTEM_MINT", { requestId = "rv-e-seed", reasonCode = "t" })
    local axe = instanceItem("Base.Axe"); pe.inventory:AddItem(axe)
    local le = M.add("rv-e", { item = "Base.Bandage", qty = 1, kind = "shop" })
    local beforeE, epochE = proofSnapshot(), S.modData().meta.epoch
    assert(M.claim(pe, le.id).ok)
    local outE = cmd(pe, "market.list", { itemId = axe.id, price = 10 })
    assert(outE.ok, tostring(outE.error))
    local replayE = deep(pe.modData)
    local pathE, realReader = J.ledgerPath(epochE), getFileReader
    getFileReader = function(fp, create) if fp == pathE then return nil end return realReader(fp, create) end
    crash(beforeE)
    getFileReader = realReader
    local pe2 = login("rv-e", 12, fakeInventory(1000), replayE)
    hello(pe2); proofPump("rv-e")
    local refusedE = cmd(pe2, "mail.claim", { mailId = le.id })
    check(refusedE.error == "ledger_unreadable" and pe2.inventory.count("Base.Bandage") == 0,
        "RV-4b: a letter up to an unreadable ledger is not handed over, and the reply says why")
    check(not Mk.listingExists(outE.listingId) and reason("rv-e", outE.listingId) == "ledger_incomplete",
        "RV-4b: a transfer up to an unreadable ledger is held, not rebuilt")
    local freshE = M.add("rv-e", { item = "Base.Bandage", qty = 1, kind = "shop" })
    check(M.claim(pe2, freshE.id).ok == true, "RV-4b: a letter minted after the unreadable ledger is claimed as usual")
    -- the administrator's System page is told which ledger could not be read and when
    onlinePlayers[#onlinePlayers + 1] = admin
    cmd(admin, "admin.system", {})
    local sysE = {}
    for _, s in ipairs(sentCommands) do
        if s.player == admin and s.command == "admin.system" then sysE = s.args end
    end
    local gapE = type(sysE.ledgerGaps) == "table" and sysE.ledgerGaps[1] or nil
    check(gapE ~= nil and #sysE.ledgerGaps == 1 and tostring(gapE.epoch) == tostring(epochE)
        and type(gapE.at) == "number" and type(gapE.reason) == "string",
        "RV-4e: admin.system names the unreadable ledger's epoch and when this start found it")
end
-- RV-4c/d: a broken row inside the file is an incomplete read; a torn last row is the known tail
do
    for _, where in ipairs({ "middle", "end" }) do
        local name = "rv-t" .. where
        local pt, lt, snapT = claimed(name, 10)
        local epochT = S.modData().meta.epoch
        assert(M.claim(pt, lt.id).ok)
        pt.inventory.items = {}
        proofSettle()
        local lines = files[J.ledgerPath(epochT)].lines
        if where == "middle" then table.insert(lines, 1, '{"k":"cla') else lines[#lines + 1] = '{"k":"cla' end
        crash(snapT)
        local pt2 = login(name, 12)
        local rt = M.claim(pt2, lt.id)
        if where == "middle" then
            check(rt.error == "ledger_unreadable", "RV-4c: a row that cannot be decoded inside the ledger makes it incomplete")
        else
            check(rt.error == "already_claimed" and M.entryOf(name, lt.id).state == "claimed"
                and (Rc.ledgerGap == nil or Rc.ledgerGap(epochT) == nil),
                "RV-4d: a torn last row is the line cut by the crash: the rest is read and judged as usual")
        end
    end
end
-- RV-5: an older save of the main character, and a split-screen character made before any command
do
    world()
    local pf = login("rv-f", 10)
    local lf = M.add("rv-f", { item = "Base.Bandage", qty = 2, kind = "shop" })
    assert(M.claim(pf, lf.id).ok)
    local older = login("rv-f", 5)       -- the world keeps the claim, this save lacks it (V3)
    fire("OnNewGame", fakePlayer("rv-f"), nil)
    hello(older)
    check(older.inventory.count("Base.Bandage") == 0 and M.entryOf("rv-f", lf.id).state == "claimed"
        and #Rc.heldRecords("rv-f") == 0 and Rc.life("rv-f") == 0,
        "RV-5: an older save with a new-character mark is neither a new life nor redelivered")
end
-- RV-6: hours beyond six decimals survive the ledger: a save at exactly the claim's hours holds it
do
    local pg, lg, snapG = claimed("rv-g", 10.1234567)
    assert(M.claim(pg, lg.id).ok)
    pg.inventory.items = {}
    crash(snapG)
    login("rv-g", 10.1234567)
    check(M.entryOf("rv-g", lg.id).state == "claimed",
        "RV-6: the ledger keeps the hours whole: a tie is not read as a fork")
end
-- RV-7/8: an oversized pending table costs a count, nothing more
do
    world()
    local pk = login("rv-k", 10)
    L.credit("rv-k", "survivor", 1000, "SYSTEM_MINT", { requestId = "rv-k-seed", reasonCode = "t" })
    local hits = 0
    local origins = setmetatable({}, { __index = function(_, i)
        hits = hits + 1
        if i <= 3 then return { src = "native", nativeId = -i } end
    end })
    local big = {}
    for n = 1, Rc.PENDING_MAX + 1 do big["rv-big:" .. n] = { protocol = 2, origins = origins } end
    pk.modData[EC.PLAYER_MODDATA_KEY] = { pendingOuts = big }
    local parsed, realParse = 0, EC.parseId
    EC.parseId = function(id)
        if type(id) == "string" and string.sub(id, 1, 7) == "rv-big:" then parsed = parsed + 1 end
        return realParse(id)
    end
    M.reconcile(pk)
    EC.parseId = realParse
    check(parsed == 0 and Rc.heldRecord("rv-k", "pend:oversized") ~= nil,
        "RV-7: the reconcile counts an oversized pending table and stops before parsing a single key")
    local saw = instanceItem("Base.Saw"); pk.inventory:AddItem(saw)
    local outK = cmd(pk, "market.list", { itemId = saw.id, price = 10 })
    check(outK.ok ~= true and hits == 0 and pk.inventory:contains(saw),
        "RV-8: a list-out with an oversized pending table is refused before any of its origins is read")
end
-- RV-10: V3, a split-screen character, a reconnect of the same main character: a different
-- session is not a different character, so no life starts, nothing is settled and nothing is
-- handed over: the refusal is one event per letter, and no record waits on an administrator
local function refusals(id, why)
    local n, last = 0, nil
    for _, e in ipairs(events) do
        if e.resolution == "redelivery-refused" and e.mailId == id and e.reason == why then n, last = n + 1, e end
    end
    return n, last
end
do
    world()
    local ph = login("rv-h", 10)
    local lh = M.add("rv-h", { item = "Base.Bandage", qty = 2, kind = "shop" })
    local lh3 = M.add("rv-h", { item = "Base.Bandage", qty = 1, kind = "shop" })
    local lh4 = M.add("rv-h", { item = "Base.Bandage", qty = 1, kind = "shop" })
    local lh5 = M.add("rv-h", { item = "Base.Bandage", qty = 1, kind = "shop" })
    assert(M.claim(ph, lh.id).ok and M.claim(ph, lh4.id).ok)
    ph.hours = 20
    assert(M.claim(ph, lh5.id).ok)
    ph.hours = 3
    assert(M.claim(ph, lh3.id).ok)          -- claimLife 0, so a raised life would settle it too
    login("rv-h", 5)                          -- the older save (V3), seen by one tick only
    fire("OnNewGame", fakePlayer("rv-h"), nil)
    local again = login("rv-h", 5)            -- reconnect: the same character, a new object
    hello(again)
    check(M.entryOf("rv-h", lh.id).state == "claimed" and again.inventory.count("Base.Bandage") == 0
        and Rc.life("rv-h") == 0 and M.entryOf("rv-h", lh3.id).state == "claimed" and #Rc.heldRecords("rv-h") == 0,
        "RV-10: a reconnect after a split-screen character starts no life, settles nothing and opens no record")
    local third = login("rv-h", 5)            -- and once more: still refused, still one event
    hello(third)
    local n, ev = refusals(lh.id, "lifebreak_unproven")
    check(n == 1 and ev.kind == "mailbox" and ev.item == "Base.Bandage" and ev.qty == 2
        and third.inventory.count("Base.Bandage") == 0,
        "RV-10b: the refused redelivery is one event per letter, naming the item and the quantity")
    local later = login("rv-h", 12)
    hello(later)
    check(M.entryOf("rv-h", lh4.id).lifeBreak == nil and M.entryOf("rv-h", lh5.id).lifeBreak ~= nil
        and M.entryOf("rv-h", lh5.id).state == "claimed" and later.inventory.count("Base.Bandage") == 0,
        "RV-10c: a later save holding the claim spends the mark; a save still before a claim gets nothing")
    fire("OnCharacterDeath", later)
    check(M.entryOf("rv-h", lh5.id).state == "settled" and M.entryOf("rv-h", lh5.id).lifeBreak == nil
        and Rc.life("rv-h") == 1,
        "RV-10d: a death the server saw settles the marked letter and clears its mark")
end
-- RV-11: the world keeps a claim, the ledger that held the death is unreadable, and the save is the
-- next character: the gap stops the automatic redelivery too, not only a claim
do
    world()
    local pi = login("rv-i", 10)
    local li = M.add("rv-i", { item = "Base.Bandage", qty = 1, kind = "shop" })
    assert(M.claim(pi, li.id).ok)
    local snapI, epochI = proofSnapshot(), S.modData().meta.epoch
    fire("OnCharacterDeath", pi)
    local pathI, realReader = J.ledgerPath(epochI), getFileReader
    proofSettle()
    getFileReader = function(fp, create) if fp == pathI then return nil end return realReader(fp, create) end
    crash(snapI)
    getFileReader = realReader
    local ni = login("rv-i", 1)
    hello(ni)
    local n, ev = refusals(li.id, "ledger_unreadable")
    check(ni.inventory.count("Base.Bandage") == 0 and M.entryOf("rv-i", li.id).state == "claimed"
        and n == 1 and ev.item == "Base.Bandage" and ev.qty == 1 and #Rc.heldRecords("rv-i") == 0,
        "RV-11: an unreadable ledger stops the redelivery of a claimed letter: it stays claimed, one event, no record")
    -- nothing waits on anyone: the claimed TTL takes it like any other claimed letter
    nowMs = nowMs + M.CLAIMED_TTL_MS + M.PRUNE_EVERY_MS + 1000
    fire("OnTickEvenPaused")
    hello(ni)
    check(M.entryOf("rv-i", li.id) == nil and ni.inventory.count("Base.Bandage") == 0,
        "RV-11b: the refused letter goes with the claimed TTL and is never handed over")
end
-- RV-12: inside a life only the ledger knows (the transfer's, or the current one), hours prove
-- nothing either way; a life this world save watched begin is still judged by hours
do
    local meta = S.modData().meta
    S.modData().recovery.lives["rv-y"] = { life = 1, seen = 0, starts = {} }
    local py = fakePlayer("rv-y"); py.hours = 50
    local old = Rc.outOrder("rv-y", { h = 10, life = 0, epoch = meta.epoch, seq = meta.seq }, py)
    local cur = Rc.outOrder("rv-y", { h = 10, life = 1, epoch = meta.epoch, seq = meta.seq }, py)
    S.modData().recovery.lives["rv-y"] = { life = 1, seen = 1, starts = {} }
    local watched = Rc.outOrder("rv-y", { h = 10, life = 1, epoch = meta.epoch, seq = meta.seq }, py)
    check(old == "life_unproven" and cur == "life_unproven" and watched == "contained",
        "RV-12: a save's hours past the commit do not prove it holds a transfer of an unproven life")
end
-- RV-13: two logins merged into one account share one mailbox, but a lost claim is judged only by
-- the save of the login that made it. Until that login has been seen, no other login of the group
-- may take the letter (nor the parent of a lost split child): its save may hold the items.
local function mergedPair(tag, capacity, qty, item)
    world()
    S.modData().identity.merged["rv-" .. tag .. "b"] = { into = "rv-" .. tag .. "a" }
    local pb = login("rv-" .. tag .. "b", 10, fakeInventory(capacity or 1000))
    local lm = M.add("rv-" .. tag .. "a", { item = item or "Base.Bandage", qty = qty or 2, kind = "shop" })
    return pb, lm, proofSnapshot()
end
do
    local pb, lm, snapM = mergedPair("m")
    assert(M.claim(pb, lm.id).ok)
    crash(snapM)
    local pa = login("rv-ma", 10)
    local early = cmd(pa, "mail.claim", { mailId = lm.id })
    check(early.error == "lost_claim_pending" and pa.inventory.count("Base.Bandage") == 0
        and M.entryOf("rv-ma", lm.id).state == "ready",
        "RV-13: another login of the account cannot take a letter whose lost claim its maker's save has not judged")
    local pb2 = login("rv-mb", 12)
    local after = cmd(pa, "mail.claim", { mailId = lm.id })
    check(M.entryOf("rv-ma", lm.id).state == "claimed" and after.error == "already_claimed"
        and pa.inventory.count("Base.Bandage") == 0 and pb2.inventory.count("Base.Bandage") == 0,
        "RV-13b: the maker's save holding the claim marks it claimed; the other login still gets nothing")
    -- an older save of the maker, too full to take it back: the letter is back to ready, and the
    -- judgement already made is not asked for again
    local pb3 = login("rv-mb", 5, fakeInventory(0))
    hello(pb3)
    local reopened = M.entryOf("rv-ma", lm.id).state == "ready"
    local again = cmd(pa, "mail.claim", { mailId = lm.id })
    check(reopened and again.ok == true and pa.inventory.count("Base.Bandage") == 2
        and pb3.inventory.count("Base.Bandage") == 0,
        "RV-13e: a letter the maker's save already judged and the server put back is claimable by the other login")
end
do
    local pb, lm, snapN = mergedPair("n")
    assert(M.claim(pb, lm.id).ok)
    crash(snapN)
    local pa = login("rv-na", 10)
    login("rv-nb", 5)                      -- the maker's save predates its claim: excluded
    local out = cmd(pa, "mail.claim", { mailId = lm.id })
    check(out.ok == true and pa.inventory.count("Base.Bandage") == 2,
        "RV-13c: once the maker's save proves it never had the claim, the other login may take the letter")
end
do
    local pb, lm, snapP = mergedPair("p", 7, 5, "Base.Plank")
    local partial = M.claim(pb, lm.id)
    assert(partial.error == "delivery_partial" and partial.deliveredQty == 2)
    crash(snapP)
    local pa = login("rv-pa", 10)
    local out = cmd(pa, "mail.claim", { mailId = lm.id })
    check(out.error == "lost_claim_pending" and pa.inventory.count("Base.Plank") == 0,
        "RV-13d: the parent of a lost split child is not handed over before the child's maker is seen")
end
X.emit = realEmit
onlinePlayers = {}
end)()

-- ===== 情境 FS2：身分審查修正（S.login 與政策分開、動物、匯入後才通知、短缺席、設定豁免、警示隱私）=====
io.write("scenario FS2: identity review fixes\n")
;(function()
local Id, Mg = EC.Identity, S.Merge
local SV = SandboxVars.MinidoracatEconomy
local function fsPlayer(name, text, seat)
    local p = mgPlayer(name, text)
    p.onlineId = seat
    return p
end
local function alertOf(kind, name)
    for _, a in ipairs(Id.status().alerts) do
        if a.kind == kind and a.name == name then return a end
    end
end
local function pushes(p, command)
    local out = {}
    for _, s in ipairs(sentCommands) do
        if s.player == p and s.command == command then out[#out + 1] = s.args end
    end
    return out
end
local function ringAudit(action, target, field)
    local last = nil
    for _, e in ipairs(X.auditEntries()) do
        if e.action == action and e.target == target and (field == nil or e.field == field) then last = e end
    end
    return last
end
local function fileAudit(action, target, field)
    proofSettle()
    local last = nil
    for _, line in ipairs(files[X.auditPath(nowMs)] and files[X.auditPath(nowMs)].lines or {}) do
        local rec = EC.jsonDecode(line)
        if type(rec) == "table" and rec.action == action and rec.target == target and (field == nil or rec.field == field) then last = rec end
    end
    return last
end
local function tick(ms)
    nowMs = nowMs + (ms or Id.SCAN_MS)
    fire("OnTickEvenPaused")
end
local function fresh()
    local md = mgWorld()
    SV.IdentityMultiAccount = nil
    return md
end

-- ----- the one-account policy decides the account, never which save a player is -----
local md = fresh()
local R_ = mgT(200)
local r1 = fsPlayer("fs2-r1", R_, 1)
onlinePlayers = { r1 }
tick()
local r1First = S.login(r1)
md.mailbox.byOwner["fs2-r1"] = { entries = { ["fs2-m1"] = { id = "fs2-m1", owner = "fs2-r1", state = "claimed",
    claimLogin = "fs2-r1", at = nowMs, claimedAt = nowMs } }, unclaimed = 0 }
md.firstSeen["fs2-r0"], md.firstSeen["fs2-r1"] = 0, nowMs
fire("OnNewGame", fsPlayer("fs2-r0", R_, 50), nil)          -- an older login of the Steam account gets bound
check(r1First == "fs2-r1" and S.login(r1) == "fs2-r1" and S.principal(r1) == nil,
    "a login the one-account policy refuses is still that save's login (S.login); only its account (S.principal) is refused")
r1.dead = true
fire("OnCharacterDeath", r1)
local settledAtDeath = md.mailbox.byOwner["fs2-r1"].entries["fs2-m1"].state
fire("OnNewGame", fsPlayer("fs2-r1", R_, 51), nil)
local r1b = fsPlayer("fs2-r1", R_, 1)
onlinePlayers = { r1b }
SV.IdentityMultiAccount = true
tick()
sentCommands = {}
nowMs = nowMs + 700
fire("OnClientCommand", EC.COMMAND_MODULE, "hello", r1b, {})
local ack = lastSent("hello.ack")
check(settledAtDeath == "settled" and md.mailbox.byOwner["fs2-r1"].entries["fs2-m1"].state == "settled"
    and ack ~= nil and ack.args.account == "fs2-r1",
    "the death of a policy-refused login settles the letters its save claimed, so allowing it later redelivers nothing")

-- ----- animals: IsoAnimal extends IsoPlayer (IsoAnimal.java:123) and dies through OnCharacterDeath -----
md = fresh()
SV.IdentityMultiAccount = true
local A_ = mgT(230)
local a1 = fsPlayer("fs2-a1", A_, 20)
onlinePlayers = { a1 }
tick()
local a1ok = S.login(a1) == "fs2-a1"
a1.dead = true
