md.firstSeen["fs2-m0"], md.firstSeen["fs2-m2"] = 0, 0
fire("OnNewGame", fsPlayer("fs2-m0", M_, 70), nil)
fire("OnNewGame", fsPlayer("fs2-m1", M_, 71), nil)
fire("OnNewGame", fsPlayer("fs2-m2", M_, 72), nil)
local m1, m2 = fsPlayer("fs2-m1", M_, 13), fsPlayer("fs2-m2", M_, 14)
local mboss = fsPlayer("fs2-boss", mgT(216), 15); mboss.role = "admin"
onlinePlayers = { mboss, m1, m2 }
tick()
local beforeM = { S.principal(m1), S.principal(m2) }       -- fs2-m0 is recorded (firstSeen, then the name)
sentCommands = {}
nowMs = nowMs + 700
fire("OnClientCommand", EC.COMMAND_MODULE, "admin.identity", mboss, { action = "import", requestId = "fs2-i1",
    rows = { { u = "fs2-boss", s = mgT(216) }, { u = "fs2-m1", s = M_ }, { u = "fs2-m2", s = M_ } } })
check(beforeM[1] == nil and beforeM[2] == nil and lastSent("admin.identity").args.ok == true
    and S.principal(m2) == "fs2-m2" and #pushes(m2, "identity.verified") == 1 and #pushes(m1, "identity.unverified") == 0,
    "an administrator's import tells the players online what the Steam account's primary is after the canonical is recorded")

-- ----- a merge pass that records a canonical tells the players it changed -----
md = fresh()
local T_ = mgT(262)
md.firstSeen["fs2-t0"], md.firstSeen["fs2-t1"], md.firstSeen["fs2-t2"] = 0, 1, 2
fire("OnNewGame", fsPlayer("fs2-t0", T_, 73), nil)          -- rounded, never on the whitelist
fire("OnNewGame", fsPlayer("fs2-t1", mgT(263), 74), nil)    -- the whitelist moves this one to T_ (a conflict)
local tboss = fsPlayer("fs2-tb", mgT(264), 18); tboss.role = "admin"
local t1 = fsPlayer("fs2-t1", T_, 19)
onlinePlayers = { tboss, t1 }
nowMs = nowMs + 700
fire("OnClientCommand", EC.COMMAND_MODULE, "admin.identity", tboss, { action = "import", requestId = "fs2-i2",
    rows = { { u = "fs2-tb", s = mgT(264) }, { u = "fs2-t1", s = T_ }, { u = "fs2-t2", s = T_ } } })
nowMs = nowMs + 700
fire("OnClientCommand", EC.COMMAND_MODULE, "admin.identity", tboss, { action = "rebind", requestId = "fs2-r1",
    names = { "fs2-t1" }, reason = "moved to the whitelisted Steam account" })
local t1AfterRebind = S.principal(t1)                        -- fs2-t0 is the recorded primary
sentCommands = {}
SV.IdentityAutoMerge = true                                  -- the running pass only runs with merging on
tick(Mg.TICK_MS + 1)                                         -- the pass records the exact group's canonical
SV.IdentityAutoMerge = nil
check(t1AfterRebind == nil and S.principal(t1) == "fs2-t1" and #pushes(t1, "identity.verified") == 1,
    "a merge pass whose new canonical lets an online login in tells that player at once")

-- ----- an administrator refused by the policy keeps the settings and is audited as its login -----
md = fresh()
local D_ = mgT(220)
md.firstSeen["fs2-d0"], md.firstSeen["fs2-ad"] = 0, nowMs
fire("OnNewGame", fsPlayer("fs2-d0", D_, 68), nil)
fire("OnNewGame", fsPlayer("fs2-ad", D_, 69), nil)
local ad = fsPlayer("fs2-ad", D_, 12); ad.role = "admin"
onlinePlayers = { ad }
tick()
local adBefore = S.principal(ad)
sentCommands = {}
nowMs = nowMs + 700
fire("OnClientCommand", EC.COMMAND_MODULE, "admin.system", ad, {})
local sys = lastSent("admin.system")
check(adBefore == nil and sys ~= nil and sys.args.ok == true and type(sys.args.sandbox) == "table",
    "admin.system (the settings page's options) is answered for an administrator the policy refuses")
nowMs = nowMs + 700
fire("OnClientCommand", EC.COMMAND_MODULE, "admin.identity", ad, { action = "import", requestId = "fs2-i3",
    rows = { { u = "fs2-ad", s = D_ }, { u = "fs2-d0", s = D_ } } })
local imp = ringAudit("IDENTITY_IMPORT", "whitelist")
nowMs = nowMs + 700
fire("OnClientCommand", EC.COMMAND_MODULE, "admin.option", ad,
    { key = "IdentityMultiAccount", value = true, requestId = "fs2-o1", reason = "several accounts are fine here" })
local opt = lastSent("admin.option")
local cfg = nil
for _, e in ipairs(X.auditEntries()) do if e.action == "config" and e.field == "IdentityMultiAccount" then cfg = e end end
tick()
check(opt ~= nil and opt.args.ok == true and EC.sandbox("IdentityMultiAccount", false) == true
    and #pushes(ad, "identity.verified") == 1,
    "admin.option is answered for an administrator the policy refuses, and the change verifies them")
check(cfg ~= nil and cfg.admin == "fs2-ad" and imp ~= nil and imp.admin == "fs2-ad",
    "a policy-refused administrator is audited as the login it verifiably is, not as a bare claim")

-- ----- a failed identity-file write backs off instead of reopening the file every second -----
md = fresh()
local opens, realWriter = 0, getFileWriter
getFileWriter = function(path, create, append)
    if path == Id.FILE then opens = opens + 1 end
    return realWriter(path, create, append)
end
writerDeny[Id.FILE] = true
local w1, w2 = fsPlayer("fs2-w1", mgT(270), 90), fsPlayer("fs2-w2", mgT(271), 91)
onlinePlayers = { w1, w2 }
local wFirst = { S.login(w1), S.login(w2) }
nowMs = nowMs + 1000
S.login(w1)
local within = opens
nowMs = nowMs + (Id.WRITE_RETRY_MS or 60000)
writerDeny[Id.FILE] = nil
local wAfter = S.login(w2)
getFileWriter = realWriter
check(wFirst[1] == nil and wFirst[2] == nil and within == 1 and opens == 2 and wAfter == "fs2-w2",
    "after a failed write first sight leaves the identity file alone for a minute, then binds again")
SV.IdentityMultiAccount = nil
steamModeActive = false
onlinePlayers = {}
end)()

-- 死亡的簿記不能因身分未確認或死亡事件沒來而漏掉：已領信件照樣結清、開新生命，否則崩潰後會再送一次。
io.write("scenario DU: a death the identity could not verify, or whose event never came\n")
;(function()
local M, Rc = S.Mailbox, S.Recovery
local md = mgWorld()
local settledEvents, diedNames, refused = {}, {}, {}
local realEmit = X.emit
X.emit = function(kind, fields)
    if kind == "mailbox.settled" then settledEvents[#settledEvents + 1] = fields end
    if kind == "player.died" then diedNames[#diedNames + 1] = fields.username end
    if kind == "ledger.anomaly" and fields.resolution == "redelivery-refused" then
        refused[#refused + 1] = { mailId = fields.mailId, reason = fields.reason }
    end
    return realEmit(kind, fields)
end
local function tick(ms)
    nowMs = nowMs + (ms or EC.Identity.SCAN_MS)
    fire("OnTickEvenPaused")
end
local function hello(who) nowMs = nowMs + 600; fire("OnClientCommand", EC.COMMAND_MODULE, "hello", who, {}) end
local function seat(name, text, id, hours)
    local p = mgPlayer(name, text)
    p.onlineId, p.hours, p.x, p.y = id, hours or 0, 101, 200
    p.inventory = fakeInventory(1000)
    return p
end
local function settledFor(name, flag)
    for _, e in ipairs(settledEvents) do
        if e.username == name and (flag == nil or e[flag] == true) then return e end
    end
end
local function refusedCount(id)
    local n = 0
    for _, e in ipairs(refused) do if e.mailId == id and e.reason == "lifebreak_unproven" then n = n + 1 end end
    return n
end

-- DU-1: login du-m (bound to Steam A) claims, stashes the bandages, logs into du-m from Steam B
-- (the password is all the server checks: ServerWorldDatabase.authClient), dies unverified,
-- respawns, and comes back from Steam A on the new character's early row. The unverified death
-- settles nothing (its name is no proof) but marks the claim, so the early row is refused it.
local A_, B_ = mgT(201), mgT(202)
local ma = seat("du-m", A_, 5, 10)
onlinePlayers = { ma }
tick()
assert(S.login(ma) == "du-m")
local lm = M.add("du-m", { item = "Base.Bandage", qty = 2, kind = "shop" })
assert(M.claim(ma, lm.id).ok)
ma.inventory.items = {}                    -- stashed in a container
local mb = seat("du-m", B_, 5, 12)
onlinePlayers = { mb }
tick()
assert(S.login(mb) == nil)
mb.modData[EC.PLAYER_MODDATA_KEY] = { pendingOuts = { ["1600000000000:1"] = { protocol = 2, epoch = "1600000000000", seq = 1 } } }
mb.dead = true
fire("OnCharacterDeath", mb)
fire("OnNewGame", seat("du-m", B_, nil, 0), nil)
local mb2 = seat("du-m", B_, 5, 0)
onlinePlayers = { mb2 }
tick()
local ma2 = seat("du-m", A_, 5, 0.5)
onlinePlayers = { ma2 }
tick()
hello(ma2)
local entryM = M.entryOf("du-m", lm.id)
check(entryM.state == "claimed" and entryM.lifeBreak ~= nil and ma2.inventory.count("Base.Bandage") == 0
    and Rc.life("du-m") == 0 and settledFor("du-m") == nil and refusedCount(lm.id) == 1 and #diedNames == 0,
    "DU-1: a death while the seat was unverified marks the login's claims: nothing comes back on the verified return, nothing is settled")

-- DU-2: an impostor renamed to a victim's login (a suspected rename) dies: the victim's claims stay
local vv = seat("du-v", mgT(203), 6, 10)
onlinePlayers = { vv }
tick()
assert(S.login(vv) == "du-v")
local lv = M.add("du-v", { item = "Base.Bandage", qty = 1, kind = "shop" })
assert(M.claim(vv, lv.id).ok)
local X_ = mgT(204)
local xx = seat("du-x", X_, 7, 3)
onlinePlayers = { xx }
tick()
assert(S.login(xx) == "du-x")
xx.dead = true
fire("OnCharacterDeath", xx)
fire("OnNewGame", seat("du-x", X_, nil, 0), nil)
local xv = seat("du-v", X_, 7, 0)            -- the respawned seat renamed to the victim
onlinePlayers = { xv }
tick()
local suspect = EC.Identity.observe(xv)
xv.dead = true
fire("OnCharacterDeath", xv)
check(suspect ~= nil and suspect.suspect == true and M.entryOf("du-v", lv.id).state == "claimed"
    and M.entryOf("du-v", lv.id).lifeBreak == nil and Rc.life("du-v") == 0 and settledFor("du-v") == nil,
    "DU-2: an impostor flagged as a rename dying under a victim's name touches nothing of the victim's")

-- DU-2b: an impostor the rename rules did not flag (it waited out the windows) dies under the
-- victim's name: the victim's letter is only marked, and the victim's next save spends the mark
local vw = seat("du-w", mgT(205), 13, 10)
onlinePlayers = { vw }
tick()
assert(S.login(vw) == "du-w")
local lw = M.add("du-w", { item = "Base.Bandage", qty = 1, kind = "shop" })
assert(M.claim(vw, lw.id).ok)
local iw = seat("du-w", mgT(206), 14, 2)
onlinePlayers = { iw }
tick()
local flagW = EC.Identity.observe(iw)
iw.dead = true
fire("OnCharacterDeath", iw)
local markedW = M.entryOf("du-w", lw.id).lifeBreak == true and M.entryOf("du-w", lw.id).state == "claimed"
local vw2 = seat("du-w", mgT(205), 13, 12)
onlinePlayers = { vw2 }
tick()
hello(vw2)
check(S.login(iw) == nil and flagW ~= nil and flagW.suspect ~= true and markedW and Rc.life("du-w") == 0
    and settledFor("du-w") == nil and M.entryOf("du-w", lw.id).lifeBreak == nil
    and M.entryOf("du-w", lw.id).state == "claimed" and vw2.inventory.count("Base.Bandage") == 0,
    "DU-2b: an unflagged impostor's death only marks the victim's letter, and the victim's next save spends the mark")

-- DU-6: the Steam-B death whose event never came (ConnectCoop took the seat first) and the object
-- was never verified: at the verified object's first sighting its claims are marked, not settled
local A6, B6 = mgT(207), mgT(208)
local na = seat("du-n", A6, 15, 10)
onlinePlayers = { na }
tick()
local ln = M.add("du-n", { item = "Base.Bandage", qty = 2, kind = "shop" })
assert(M.claim(na, ln.id).ok)
na.inventory.items = {}
local nb = seat("du-n", B6, 15, 12)
onlinePlayers = { nb }
tick()
assert(S.login(nb) == nil)
nb.dead = true                               -- no OnCharacterDeath, no CreatePlayer
local na2 = seat("du-n", A6, 15, 0.5)
onlinePlayers = { na2 }
tick()
hello(na2)
check(M.entryOf("du-n", ln.id).state == "claimed" and na2.inventory.count("Base.Bandage") == 0
    and Rc.life("du-n") == 0 and refusedCount(ln.id) == 1,
    "DU-6: a never-verified object dead without its event marks the name's claims at the next first sighting: no redelivery")
-- DU-6b: the same object pruned before the next one comes
local A7, B7 = mgT(209), mgT(210)
local oa = seat("du-o", A7, 16, 10)
onlinePlayers = { oa }
tick()
local lo = M.add("du-o", { item = "Base.Bandage", qty = 1, kind = "shop" })
assert(M.claim(oa, lo.id).ok)
oa.inventory.items = {}
local ob = seat("du-o", B7, 16, 12)
onlinePlayers = { ob }
tick()
ob.dead = true
onlinePlayers = {}
-- (the prune keeps a seat that left within RESPAWN_MS: the jump below is far past it)
tick(M.PRUNE_EVERY_MS + 1000)
local markedO = M.entryOf("du-o", lo.id).lifeBreak == true
local oa2 = seat("du-o", A7, 16, 0.5)
onlinePlayers = { oa2 }
tick()
hello(oa2)
check(markedO and M.entryOf("du-o", lo.id).state == "claimed" and oa2.inventory.count("Base.Bandage") == 0
    and Rc.life("du-o") == 0,
    "DU-6b: a never-verified dead object dropped by the prune marks the name's claims first: no redelivery")

-- DU-7..9: a mark lives in the rollback ledger too. A crash back to a world where the claim is
-- saved but the mark is not must not hand the letter to the new character's early row.
local function crashTo(snap)
    proofSettle()
    onlinePlayers = {}
    modDataStore[EC.MODDATA_KEY] = snap
    nowMs = nowMs + 1000
    fire("OnServerStarted")
end
-- DU-7: the unverified death's mark
local A8, B8 = mgT(211), mgT(212)
local qa = seat("du-q", A8, 17, 10)
onlinePlayers = { qa }
tick()
local lq = M.add("du-q", { item = "Base.Bandage", qty = 2, kind = "shop" })
assert(M.claim(qa, lq.id).ok)
qa.inventory.items = {}                      -- handed to another player, who saved
local snapQ = proofSnapshot()
local qb = seat("du-q", B8, 17, 12)
onlinePlayers = { qb }
tick()
qb.dead = true
fire("OnCharacterDeath", qb)
crashTo(snapQ)
local qa2 = seat("du-q", A8, 17, 0.5)
onlinePlayers = { qa2 }
tick()
hello(qa2)
check(M.entryOf("du-q", lq.id).state == "claimed" and M.entryOf("du-q", lq.id).lifeBreak ~= nil
    and qa2.inventory.count("Base.Bandage") == 0 and Rc.life("du-q") == 0 and refusedCount(lq.id) == 1,
    "DU-7: a rollback that forgot an unverified death's mark gets it back from the ledger: no redelivery, one refusal")
local qa3 = seat("du-q", A8, 17, 12)
onlinePlayers = { qa3 }
tick()
hello(qa3)
local spentQ = M.entryOf("du-q", lq.id).lifeBreak == nil and qa3.inventory.count("Base.Bandage") == 0
check(spentQ, "DU-7b: a save that holds the claim spends the mark the ledger put back")
crashTo(proofSnapshot())                     -- an ordinary restart: the mark stays spent
check(M.entryOf("du-q", lq.id).lifeBreak == nil and M.entryOf("du-q", lq.id).state == "claimed",
    "DU-7c: a mark already spent is not put back again by the next start")
-- DU-8: the same with a CreatePlayer beside the living seat
local rA = mgT(213)
local ra = seat("du-r", rA, 18, 10)
onlinePlayers = { ra }
tick()
local lr = M.add("du-r", { item = "Base.Bandage", qty = 1, kind = "shop" })
assert(M.claim(ra, lr.id).ok)
ra.inventory.items = {}
local snapR = proofSnapshot()
fire("OnNewGame", seat("du-r", rA, nil, 0), nil)
crashTo(snapR)
local ra2 = seat("du-r", rA, 18, 0)
onlinePlayers = { ra2 }
tick()
hello(ra2)
check(M.entryOf("du-r", lr.id).state == "claimed" and ra2.inventory.count("Base.Bandage") == 0
    and refusedCount(lr.id) == 1,
    "DU-8: a rollback that forgot a CreatePlayer's mark gets it back: the zero-hour row is refused the letter")
-- DU-9: the claim itself was rolled back too (a lost claim) and the mark after it: the new
-- character's save below the claim is no proof it never had it
local tA, tB = mgT(214), mgT(215)
local ta = seat("du-t", tA, 19, 10)
onlinePlayers = { ta }
tick()
local lt = M.add("du-t", { item = "Base.Bandage", qty = 1, kind = "shop" })
local snapT = proofSnapshot()
assert(M.claim(ta, lt.id).ok)
ta.inventory.items = {}
local tb = seat("du-t", tB, 19, 12)
onlinePlayers = { tb }
tick()
tb.dead = true
fire("OnCharacterDeath", tb)
crashTo(snapT)
local ta2 = seat("du-t", tA, 19, 0.5)
onlinePlayers = { ta2 }
tick()
hello(ta2)
local againT = M.claim(ta2, lt.id)
check(M.entryOf("du-t", lt.id).state == "claimed" and M.entryOf("du-t", lt.id).lifeBreak ~= nil
    and againT.ok ~= true and ta2.inventory.count("Base.Bandage") == 0,
    "DU-9: a lost claim older than a lost mark is claimed and marked, never left ready for the new character")

-- DU-10: CreatePlayer repeated without a death marks letters already marked: no new ledger line
local function brkLines(name)
    proofSettle()
    local n = 0
    for _, f in pairs(files) do
        for _, line in ipairs(f.lines or {}) do
            if string.find(line, '"k":"brk"', 1, true) and string.find(line, '"l":"' .. name .. '"', 1, true) then n = n + 1 end
        end
    end
    return n
end
local za = seat("du-z", mgT(216), 20, 10)
onlinePlayers = { za }
tick()
local lz = M.add("du-z", { item = "Base.Bandage", qty = 1, kind = "shop" })
assert(M.claim(za, lz.id).ok)
for _ = 1, 10 do fire("OnNewGame", seat("du-z", mgT(216), nil, 0), nil) end
local tenZ = brkLines("du-z")
local lz2 = M.add("du-z", { item = "Base.Bandage", qty = 1, kind = "shop" })
assert(M.claim(za, lz2.id).ok)
fire("OnNewGame", seat("du-z", mgT(216), nil, 0), nil)
check(tenZ == 1 and brkLines("du-z") == 2 and M.entryOf("du-z", lz.id).lifeBreak ~= nil
    and M.entryOf("du-z", lz2.id).lifeBreak ~= nil,
    "DU-10: ten CreatePlayers over the same claims write one ledger mark; a new claim after them one more")

-- DU-3..5 without Steam mode: the seat is the login, the question is only whether the death came
steamModeActive = false
-- DU-3: health 0, the event never came, and a new character took the seat in that window (its
-- CreatePlayer row has zero hours; the login's old row coming back alive is scenario RS): the new
-- object's first sighting settles the dead one
local d1 = seat("du-d", nil, 8, 10)
onlinePlayers = { d1 }
tick()
local ld = M.add("du-d", { item = "Base.Bandage", qty = 1, kind = "shop" })
assert(M.claim(d1, ld.id).ok)
d1.inventory.items = {}
d1.dead = true                               -- BodyDamage set health 0; die() never ran
local d2 = seat("du-d", nil, 8, 0)
onlinePlayers = { d2 }
tick()
hello(d2)
local evD = settledFor("du-d", "unseen")
check(M.entryOf("du-d", ld.id).state == "settled" and d2.inventory.count("Base.Bandage") == 0
    and Rc.life("du-d") == 1 and evD ~= nil,
    "DU-3: a dead object whose death event never came is settled when the login's next object is first seen")
fire("OnCharacterDeath", d1)                  -- the event after all: once is once
check(Rc.life("du-d") == 1, "DU-3b: a late death event for an object already settled starts no second life")

-- DU-4: the same, but the prune drops the departed dead object before the next one comes
local e1 = seat("du-e", nil, 9, 10)
onlinePlayers = { e1 }
tick()
local le = M.add("du-e", { item = "Base.Bandage", qty = 1, kind = "shop" })
assert(M.claim(e1, le.id).ok)
e1.inventory.items = {}
e1.dead = true
onlinePlayers = {}
-- (the prune keeps a seat that left within RESPAWN_MS: the jump below is far past it)
tick(M.PRUNE_EVERY_MS + 1000)
local settledByPrune = M.entryOf("du-e", le.id).state == "settled"
local e2 = seat("du-e", nil, 9, 0.5)
onlinePlayers = { e2 }
tick()
hello(e2)
check(settledByPrune and e2.inventory.count("Base.Bandage") == 0 and Rc.life("du-e") == 1,
    "DU-4: a dead object pruned before the login's next object is seen is settled by the prune")

-- DU-5: an ordinary logout and login of an alive character settles nothing (a V3 save still
-- gets its letter)
local f1 = seat("du-f", nil, 10, 10)
onlinePlayers = { f1 }
tick()
local lf = M.add("du-f", { item = "Base.Bandage", qty = 1, kind = "shop" })
assert(M.claim(f1, lf.id).ok)
f1.inventory.items = {}
onlinePlayers = {}
tick(M.PRUNE_EVERY_MS + 1000)
local f2 = seat("du-f", nil, 10, 5)
onlinePlayers = { f2 }
tick()
hello(f2)
check(M.entryOf("du-f", lf.id).state == "claimed" and f2.inventory.count("Base.Bandage") == 1
    and Rc.life("du-f") == 0 and settledFor("du-f") == nil,
    "DU-5: an alive character logging out and back settles nothing")
X.emit = realEmit
onlinePlayers = {}
end)()

-- 死掉的角色不能帶著死前的存檔回來：引擎可能不建新角色就把死掉的座位交回，讀回那個帳號死前最後
-- 一次存檔（活的），屍體身上也有同一批東西（E2E resurrect-mp 實機重現）。
io.write("scenario RS: a character that died does not come back on its old save\n")
;(function()
local M, Rc = S.Mailbox, S.Recovery
local md = mgWorld()
local adm = fakePlayer("rs-admin")
adm.role, adm.onlineId, adm.hours = "admin", 90, 1
-- the first online player is the probe: 0.01 h a tick makes the fresh band FRESH_STEPS of that
local function tick(ms)
    adm.hours = adm.hours + 0.01
    nowMs = nowMs + (ms or 100)
    fire("OnTickEvenPaused")
end
local function far() tick(Rc.RESPAWN_MS + 1000) end   -- past the seat rule's window
local function hello(who) nowMs = nowMs + 600; fire("OnClientCommand", EC.COMMAND_MODULE, "hello", who, {}) end
local function seat(name, text, id, hours, items)
    local p = mgPlayer(name, text)
    p.onlineId, p.hours, p.x, p.y = id, hours or 0, 101, 200
    p.inventory = fakeInventory(1000)
    for _ = 1, items or 0 do p.inventory:AddItem(instanceItem("Base.Hammer")) end
    p.primary, p.worn, p.attached = "hammer", 3, 1
    p.setPrimaryHandItem = function(_, it) p.primary = it end
    p.setSecondaryHandItem = function(_, it) p.secondary = it end
    p.clearWornItems = function() p.worn = 0 end
    p.clearAttachedItems = function() p.attached = 0 end
    p.getBodyDamage = function() return { setOverallBodyHealth = function(_, v) p.bodyHealth = v end } end
    p.setHealth = function(_, v) p.health = v; if v <= 0 then p.dead = true end end   -- isDead: health <= 0
    return p
end
local function online(...) onlinePlayers = { adm, ... } end
local function sent(p, command)
    local n = 0
    for _, c in ipairs(sentCommands) do if c.player == p and c.command == command then n = n + 1 end end
    return n
end
local function killed(p) return p.dead == true and p.health == 0 and p.inventory.count() == 0 end
local function untouched(p, n) return p.dead ~= true and p.health == nil and p.inventory.count() == n end
online()
tick()

-- RS-1: rs-a dies; the client re-adds the dead player object and the server loads the last saved
-- row: alive, a little under the death's hours, carrying what the corpse holds too
local a1 = seat("rs-a", mgT(301), 21, 10, 3)
online(a1)
tick()
a1.dead = true
fire("OnCharacterDeath", a1)
local lifeA = Rc.life("rs-a")
local b1 = seat("rs-a", mgT(301), 21, 9.5, 4)
-- the old row also carries an old pending out: a reconcile of it would act on that
b1.modData[EC.PLAYER_MODDATA_KEY] = { pendingOuts = { ["1600000000000:7"] = { protocol = 2, epoch = "1600000000000", seq = 7 } } }
local startsA = #(md.recovery.lives["rs-a"].starts or {})
online(b1)
tick()
check(killed(b1) and b1.worn == 0 and b1.attached == 0 and b1.primary == nil,
    "RS-1: the dead login's old row coming back alive is emptied and killed")
check(mgAudits("RESURRECTION", "carried") == 1 and sent(adm, "recovery.resurrection") == 1
    and sent(b1, "recovery.resurrection") == 0,
    "RS-1b: one RESURRECTION audit line, and one toast for the administrator online only")
hello(b1)
check(sent(b1, "hello.ack") == 0 and M.reconcile(b1) == true and Rc.isPhantom(b1) and Rc.heldCount("rs-a") == 0
    and #(md.recovery.lives["rs-a"].starts or {}) == startsA,
    "RS-1c: no economy command, reconcile or session start acts for it")
fire("OnCharacterDeath", b1)
check(Rc.life("rs-a") == lifeA, "RS-1d: its death is no character's death: no new life")
local b2 = seat("rs-a", mgT(301), 21, 9.5, 4)
online(b2)
tick()
check(killed(b2) and mgAudits("RESURRECTION", "carried") == 1 and sent(adm, "recovery.resurrection") == 1,
    "RS-1e: given back again at once it is killed again; one audit line a minute, one toast in ten seconds")

-- RS-2: rs-c dies and makes a new character: its CreatePlayer row has zero hours and is first
-- seen a tick later, within FRESH_STEPS of the probe's step. Left alone, the death's note goes,
-- and the new character's next login is just a login
local c1 = seat("rs-c", mgT(302), 22, 10, 3)
online(c1)
tick()
c1.dead = true
fire("OnCharacterDeath", c1)
fire("OnNewGame", seat("rs-c", mgT(302), nil, 0), nil)
local c2 = seat("rs-c", mgT(302), 22, 0.05, 2)
online(c2)
tick()
local freshKept = untouched(c2, 2)
online()
far()
local c3 = seat("rs-c", mgT(302), 23, 6, 2)
online(c3)
tick()
check(freshKept and untouched(c3, 2), "RS-2: a new character is left alone, and so is its next login")

-- RS-3: rs-d dies and its client leaves before the seat is given back (stage 1 alone): the row
-- stays the living one. The login comes back on a new connection in the same uptime: refused
local d1 = seat("rs-d", mgT(303), 24, 10, 3)
online(d1)
tick()
d1.dead = true
fire("OnCharacterDeath", d1)
online()
far()
tick(M.PRUNE_EVERY_MS + 1000)
-- an object made for OnNewGame (never online) is no sighting of the login
Rc.session(seat("rs-d", mgT(303), nil, 0))
local d2 = seat("rs-d", mgT(303), 25, 9.8, 4)
online(d2)
tick()
check(killed(d2), "RS-3: past a prune and an OnNewGame object, the login's old row on a new connection is refused")

-- RS-4: a death that reached the row (a disconnect saved it dead): the login's next object is
-- first seen dead and the note goes. That object's own death is an earlier session's: it does not
-- count as an unprocessed death (rs-e, before any prune), nor is it noted again when the prune
-- settles it (rs-e2). A later living row of the login is left alone either way
local e1 = seat("rs-e", mgT(304), 26, 10, 3)
online(e1)
tick()
e1.dead = true
fire("OnCharacterDeath", e1)
online()
far()
local e2 = seat("rs-e", mgT(304), 27, 10, 3)
e2.dead = true
online(e2)
tick()
online()
far()
local e3 = seat("rs-e", mgT(304), 59, 10, 3)
online(e3)
tick()
local ee1 = seat("rs-e2", mgT(321), 62, 10, 3)
online(ee1)
tick()
ee1.dead = true
fire("OnCharacterDeath", ee1)
online()
far()
local ee2 = seat("rs-e2", mgT(321), 63, 10, 3)
ee2.dead = true
online(ee2)
tick()
online()
tick(M.PRUNE_EVERY_MS + 1000)
local ee3 = seat("rs-e2", mgT(321), 64, 10, 3)
online(ee3)
tick()
check(e2.health == nil and e2.inventory.count() == 3 and untouched(e3, 3) and untouched(ee3, 3),
    "RS-4: an object of the login first seen dead shows the death was saved: the note goes, and its own death is not a new one")

-- RS-5: an impostor's death under a victim's name (another SteamID: unverified) is never noted,
-- and the victim's next login is left alone
local v1 = seat("rs-v", mgT(305), 28, 20, 2)
online(v1)
tick()
online()
far()
local i1 = seat("rs-v", mgT(306), 29, 3, 1)
online(i1)
tick()
i1.dead = true
fire("OnCharacterDeath", i1)
online()
far()
local v2 = seat("rs-v", mgT(305), 30, 20, 2)
online(v2)
tick()
check(untouched(v2, 2),
    "RS-5: a death the binding does not vouch for pins nothing on the name: the victim's login is left alone")

-- RS-6: the seat rule. a) rs-f's seat is given back at once under another name (a suspected
-- rename, unverified) - still the login's old row: refused
local f1 = seat("rs-f", mgT(307), 31, 10, 3)
online(f1)
tick()
f1.dead = true
fire("OnCharacterDeath", f1)
local f2 = seat("rs-x", mgT(307), 31, 9.9, 3)
online(f2)
tick()
check(S.login(f2) == nil and killed(f2), "RS-6a: a seat given back at once under another name is refused by the seat rule")
-- b) another SteamID on that onlineID is no return
local g1 = seat("rs-g", mgT(308), 32, 10, 3)
online(g1)
tick()
g1.dead = true
fire("OnCharacterDeath", g1)
local g2 = seat("rs-h", mgT(309), 32, 30, 2)
online(g2)
tick()
check(untouched(g2, 2), "RS-6b: the seat rule needs the same SteamID")
-- c) the occupant it replaced must be dead
local h1 = seat("rs-i", mgT(310), 33, 12, 2)
online(h1)
tick()
local h2 = seat("rs-i", mgT(310), 33, 12, 2)
online(h2)
tick()
check(untouched(h2, 2), "RS-6c: the seat rule needs the occupant it replaced to be dead")
-- d) without Steam mode: the seat rule holds within RESPAWN_MS of the replaced object's last
-- sighting (kept by a prune between the two stages); after it nothing does, and a name's
-- unprocessed death condemns nothing
steamModeActive = false
local k1 = seat("rs-k", nil, 34, 10, 3)
online(k1)
tick(M.PRUNE_EVERY_MS + 1000)               -- a prune with k1 online
tick(M.PRUNE_EVERY_MS - 3000)               -- k1 seen; the next prune is 3 s away
k1.dead = true
fire("OnCharacterDeath", k1)
online()                                    -- stage 1 took it
tick(3500)                                  -- the prune runs between the two stages and keeps it
local k2 = seat("rs-k", nil, 34, 9.5, 3)
online(k2)
tick()
local j1 = seat("rs-j", nil, 35, 10, 3)
online(j1)
tick()
j1.dead = true
fire("OnCharacterDeath", j1)
online()
tick(Rc.RESPAWN_MS + 1000)
local j2 = seat("rs-j", nil, 35, 9.5, 3)
online(j2)
tick()
local q1 = seat("rs-q", nil, 39, 3, 1)
online(q1)
tick()
q1.dead = true
local q2 = seat("rs-q", nil, 40, 20, 2)
online(q2)
tick()
check(killed(k2) and untouched(j2, 3) and untouched(q2, 2),
    "RS-6d: without Steam mode the seat rule holds within RESPAWN_MS and nothing is judged by name")
steamModeActive = true

-- RS-7: an animal on a dead seat's onlineID (IsoAnimal extends IsoPlayer) is never judged
local m1 = seat("rs-m", mgT(311), 36, 10, 3)
online(m1)
tick()
m1.dead = true
fire("OnCharacterDeath", m1)
local cow = seat("rs-m", mgT(311), 36, 50, 1)
cow.__class = "IsoAnimal"
online(cow)
tick()
check(untouched(cow, 1), "RS-7: an animal is never judged")

-- RS-8: a processed death that did not stick (the same object alive again) never reached the
-- row: the minute prune drops the note while the object is still around; the next login, after
-- that object's session is gone too, is left alone
local n1 = seat("rs-n", mgT(312), 37, 10, 2)
online(n1)
tick()
n1.dead = true
fire("OnCharacterDeath", n1)
n1.dead = false
tick(M.PRUNE_EVERY_MS + 1000)
online()
tick(M.PRUNE_EVERY_MS + 1000)               -- the next prune drops n1's session
local n2 = seat("rs-n", mgT(312), 38, 10.5, 2)
online(n2)
tick()
check(untouched(n2, 2), "RS-8: a death that did not stick is dropped from the notes by the prune")

-- RS-9: a verified death the server has not processed yet (health 0, no event yet: ConnectCoop can
-- take the seat in that window) counts too: the login on a new connection is refused
local z1 = seat("rs-z", mgT(313), 41, 10, 3)
online(z1)
tick()
z1.dead = true
online()
tick()
local z2 = seat("rs-z", mgT(313), 42, 9.7, 3)
online(z2)
tick()
check(killed(z2), "RS-9: a verified death not processed yet counts as well (another onlineID: not the seat rule)")
-- RS-9b: that refused object is no character: when the prune settles the old death later, it is
-- still the login's newest one and is noted, so the next reload is refused too
online()
tick(M.PRUNE_EVERY_MS + 1000)
local z3 = seat("rs-z", mgT(313), 53, 9.7, 3)
online(z3)
tick()
check(killed(z3), "RS-9b: a refused reload does not hide the death it came from")

local function crashTo(snap)
    proofSettle()
    onlinePlayers = {}
    modDataStore[EC.MODDATA_KEY] = snap
    nowMs = nowMs + 1000
    fire("OnServerStarted")
end

-- RS-10: a death, a world save, a new character (players.db keeps it, hours on) and a crash back
-- to that world save: the notes are process memory, so the new character logs in untouched
local r1 = seat("rs-r", mgT(314), 43, 10, 3)
online(r1)
tick()
r1.dead = true
fire("OnCharacterDeath", r1)
local snapR = proofSnapshot()
local r2 = seat("rs-r", mgT(314), 43, 0, 2)
online(r2)
tick()
crashTo(snapR)
online()
tick()
local r3 = seat("rs-r", mgT(314), 44, 4, 2)
online(r3)
tick()
check(untouched(r3, 2), "RS-10: a crash back to a world save made after the death: the new character is left alone")

-- RS-11: the death event never came and a new character took the seat; its first sighting
-- settles that death late, which notes nothing (not the newest object), and the new
-- character's next login is left alone
local w1 = seat("rs-w", mgT(315), 45, 10, 3)
online(w1)
tick()
w1.dead = true
local w2 = seat("rs-w", mgT(315), 45, 0, 2)
online(w2)
tick()
online()
tick(M.PRUNE_EVERY_MS + 1000)
local w3 = seat("rs-w", mgT(315), 46, 3, 2)
online(w3)
tick()
check(untouched(w3, 2) and Rc.life("rs-w") == 1,
    "RS-11: a death settled after a new character was seen notes nothing: the new character's next login is left alone")

-- RS-12: the object whose death set the note came back to life and logged out; the next login
-- comes before any prune: the judgment itself sees that the death did not stick
local y1 = seat("rs-y", mgT(316), 47, 10, 2)
online(y1)
tick()
y1.dead = true
fire("OnCharacterDeath", y1)
y1.dead = false
online()
tick(Rc.RESPAWN_MS + 1000)
local y2 = seat("rs-y", mgT(316), 48, 10.5, 2)
online(y2)
tick()
check(untouched(y2, 2), "RS-12: a death that did not stick is seen at the next login itself")

-- RS-13: an old row first seen while its SteamID cannot be read (unverified) is judged by login
-- once it is verified: a) at its first command, b) at the once-a-second first-sighting retry
local t1 = seat("rs-t", mgT(317), 49, 10, 3)
online(t1)
tick()
t1.dead = true
fire("OnCharacterDeath", t1)
online()
tick(Rc.RESPAWN_MS + 1000)
local t2 = seat("rs-t", mgT(317), 50, 9.6, 3)
local sidT = t2.steamId
t2.steamId = nil
online(t2)
tick()
local sparedT = untouched(t2, 3)
t2.steamId = sidT
hello(t2)
check(sparedT and killed(t2) and sent(t2, "hello.ack") == 0,
    "RS-13a: an object verified after its first sighting is judged by login at its first command")
local u1 = seat("rs-u", mgT(318), 51, 10, 3)
online(u1)
tick()
u1.dead = true
fire("OnCharacterDeath", u1)
online()
tick(Rc.RESPAWN_MS + 1000)
local u2 = seat("rs-u", mgT(318), 52, 9.6, 3)
local sidU = u2.steamId
u2.steamId = nil
online(u2)
tick()
local sparedU = untouched(u2, 3)
u2.steamId = sidU
tick(1100)
check(sparedU and killed(u2), "RS-13b: an object verified after its first sighting is judged by login at the retry")

-- RS-15: a new character (its CreatePlayer bound the name) first seen unverified dies before its
-- first verified sighting: that late judgment does not take its own death for a new
-- character's, and its old row is refused
fire("OnNewGame", seat("rs-xx", mgT(320), nil, 0), nil)
local x1 = seat("rs-xx", mgT(320), 60, 0, 2)
local sidX = x1.steamId
x1.steamId = nil
online(x1)
tick()
x1.steamId = sidX
x1.hours, x1.dead = 2, true
fire("OnCharacterDeath", x1)
tick(1100)
online()
far()
local x2 = seat("rs-xx", mgT(320), 61, 1.9, 2)
online(x2)
tick()
check(killed(x2), "RS-15: a judgment after the object's own death keeps that death noted")
steamModeActive = false
onlinePlayers = {}
end)()

-- ===== 情境 SD：刪除商店商品、服主的商品上限、硬上限 =====
io.write("scenario SD: removing shop items, the host's item limit and the hard ceiling\n")
;(function()
local Shop = S.Shop
modDataStore[EC.MODDATA_KEY] = nil
files, sentCommands, writerDeny = {}, {}, {}
nowMs = nowMs + 61000
local function catalog(rows)
    files[Shop.FILE] = { lines = { EC.jsonEncode({ items = rows }) }, opens = 0 }
end
local function fileText() return table.concat(files[Shop.FILE].lines, "\n") end
catalog({
    { id = "pack", item = "Base.Twine", qty = 1, dailyCap = 2, dailyCapScope = "lifetime", category = "material",
        prices = { survivor = { price = 20, bidPrice = 8, buyback = true } } },
    { id = "nail", item = "Base.Nails", qty = 1, category = "material", prices = { survivor = { price = 5 } } },
    { id = "plank", item = "Base.Plank", qty = 1, category = "material", prices = { survivor = { price = 9 } } },
})
fire("OnServerStarted")
worldSprites = { ["100,200,0"] = "MinidoracatEconomy_terminal_0" }
local boss = fakePlayer("sd-admin"); boss.role = "admin"
local mod = fakePlayer("sd-mod"); mod.role = "moderator"
local zed = fakePlayer("sd-zed"); zed.x, zed.y = 101, 200; zed.inventory = fakeInventory(80)
onlinePlayers = { boss, mod, zed }
local function cmd(who, name, args)
    nowMs = nowMs + 600
    args = args or {}
    args.requestId = args.requestId or (name .. nowMs)
    withCurrency(name, args)
    fire("OnClientCommand", EC.COMMAND_MODULE, name, who, args)
    local s = lastSent(name)
    return s and s.args or {}
end
local function pushedTo(who)
    for i = #sentCommands, 1, -1 do
        local s = sentCommands[i]
        if s.command == "shop.list" and s.player == who then return s.args end
    end
    return nil
end
cmd(boss, "terminal.register", { x = 100, y = 200, z = 0, kind = "atm" })
L.credit("sd-zed", "survivor", 1000, "SYSTEM_MINT", { requestId = "sd-seed", reasonCode = "t" })

-- 寫入閘門與整批不寫：一個不存在的 id 讓整份清單都不動
local before, rev0 = fileText(), Shop.revision()
local modTry = cmd(mod, "admin.catalog", { action = "remove", ids = { "nail" } })
local ghost = cmd(boss, "admin.catalog", { action = "remove", ids = { "nail", "ghost" }, reason = "sd" })
check(modTry.error == "forbidden" and ghost.ok == false and ghost.error == "unknown_sku" and ghost.extra ~= nil
    and ghost.extra.id == "ghost" and Shop.sku("nail") ~= nil and fileText() == before and Shop.revision() == rev0,
    "SD-1: removing needs the write gate, and one unknown id refuses the whole list without touching the file")
check(cmd(boss, "admin.catalog", { action = "remove", ids = { "nail", "nail" }, reason = "sd" }).error == "duplicate_id"
    and cmd(boss, "admin.catalog", { action = "remove", ids = {}, reason = "sd" }).error == "invalid_args"
    and cmd(boss, "admin.catalog", { action = "remove", ids = "nail", reason = "sd" }).error == "invalid_args"
    and cmd(boss, "admin.catalog", { action = "remove", ids = { "nail" }, revision = "0:stale", reason = "sd" }).error == "catalog_stale"
    and Shop.sku("nail") ~= nil and fileText() == before,
    "SD-2: a repeated id, an empty or malformed list and a stale revision are refused and remove nothing")
-- 刪除無法在面板上復原：原因跟其他管理寫入同一條規則，由伺服器自己檢查，不只靠對話框
local lastAudit = X.auditEntries(1)[1]
local noReason = cmd(boss, "admin.catalog", { action = "remove", ids = { "nail" } })
local blank = cmd(boss, "admin.catalog", { action = "remove", ids = { "nail" }, reason = "   " })
local ctrl = cmd(boss, "admin.catalog", { action = "remove", ids = { "nail" }, reason = "a\001b" })
local long = cmd(boss, "admin.catalog", { action = "remove", ids = { "nail" }, reason = string.rep("x", 1001) })
local notText = cmd(boss, "admin.catalog", { action = "remove", ids = { "nail" }, reason = { "x" } })
local newAudit = X.auditEntries(1)[1]
check(noReason.error == "reason_too_short" and blank.error == "reason_blank" and ctrl.error == "reason_invalid"
    and long.error == "reason_too_long" and notText.error == "reason_too_short"
    and Shop.sku("nail") ~= nil and fileText() == before and Shop.revision() == rev0
    and (newAudit == nil or newAudit == lastAudit or not (newAudit.field == "remove" and newAudit.target == "nail")),
    "SD-14: a removal without a real reason is refused by the server itself, with nothing written or audited")

-- 買過再刪：檔案、版本、推送、稽核
local rev1 = Shop.revision()
local bought = cmd(zed, "shop.buy", { id = "pack", currency = "survivor", revision = rev1, requestId = "sd-buy" })
local balAfter = L.getBalance("sd-zed", "survivor").available
sentCommands = {}
local removed = cmd(boss, "admin.catalog", { action = "remove", ids = { "pack" }, revision = Shop.revision(), reason = "retire" })
local push = pushedTo(zed)
local stillListed = false
for _, it in ipairs(push and push.items or {}) do if it.id == "pack" then stillListed = true end end
check(bought.ok == true and removed.ok == true and removed.extra ~= nil and removed.extra.count == 1
    and Shop.sku("pack") == nil and Shop.sku("nail") ~= nil and Shop.sku("plank") ~= nil
    and string.find(fileText(), '"pack"', 1, true) == nil and Shop.revision() ~= rev1
    and push ~= nil and not stillListed and #push.items == 2,
    "SD-3: a removal takes the row out of catalog.json itself, bumps the revision and pushes the shorter catalog to everyone online")
local audit = X.auditEntries(5)[1]
local doc = audit ~= nil and type(audit.before) == "string" and EC.jsonDecode(audit.before) or nil
check(audit ~= nil and audit.action == "catalog" and audit.field == "remove" and audit.target == "pack"
    and audit.reason == "retire" and type(doc) == "table" and doc.item == "Base.Twine" and doc.dailyCapScope == "lifetime"
    and doc.prices.survivor.price == 20 and doc.prices.survivor.bidPrice == 8 and doc.prices.survivor.buyback == true,
    "SD-4: the audit keeps the removed row's own catalog line, with the reason")
local again = cmd(zed, "shop.buy", { id = "pack", currency = "survivor", revision = rev1, requestId = "sd-buy" })
local fresh = cmd(zed, "shop.buy", { id = "pack", currency = "survivor", revision = Shop.revision(), requestId = "sd-buy-2" })
check(again.duplicate == true and again.txId == bought.txId and L.getBalance("sd-zed", "survivor").available == balAfter
    and fresh.error == "unknown_sku",
    "SD-5: a purchase resent after its row was removed answers with the original transaction; a new one finds no row")
-- 稽核那一行貼回檔案就是原本那一列；已購份數沒被動過
local cur = EC.jsonDecode(fileText())
cur.items[#cur.items + 1] = doc
catalog(cur.items)
local back = cmd(boss, "admin.catalog", { action = "reload" })
local p = Shop.sku("pack")
check(back.ok == true and p ~= nil and p.item == "Base.Twine" and p.dailyCap == 2 and p.dailyCapScope == "lifetime"
    and p.prices.survivor.price == 20 and p.prices.survivor.bidPrice == 8 and p.prices.survivor.buyback == true
    and Shop.used("sd-zed", "pack", nowMs) == 1,
    "SD-6: the audit line pasted back into catalog.json restores the row as it was, and the lifetime count it left behind still counts")

-- 服主的上限
check(Shop.maxItems() == 200 and cmd(zed, "shop.list").maxItems == 200 and Shop.MAX_SKUS == 1000
    and EC.OPTION_BY_KEY.ShopMaxItems.max == Shop.MAX_SKUS,
    "SD-7: the item limit is the ShopMaxItems option (200 by default), every snapshot carries it, and its top is the hard ceiling")
local bulk = {}
for i = 1, 200 do bulk[i] = { id = "b" .. i, item = "Base.Twine", qty = 1, prices = { survivor = { price = 7 } } } end
catalog(bulk)
local full = cmd(boss, "admin.catalog", { action = "reload" })
local refused = cmd(boss, "admin.catalog", { action = "add", id = "one_more", item = "Base.Nails", prices = { survivor = { price = 5 } } })
sentCommands = {}
local raised = cmd(boss, "admin.option", { key = "ShopMaxItems", value = 201 })
local push2 = pushedTo(zed)
local added = cmd(boss, "admin.catalog", { action = "add", id = "one_more", item = "Base.Nails", prices = { survivor = { price = 5 } } })
local over = cmd(boss, "admin.catalog", { action = "add", id = "two_more", item = "Base.Nails", prices = { survivor = { price = 5 } } })
check(full.ok == true and full.count == 200 and refused.error == "catalog_full" and raised.ok == true
    and push2 ~= nil and push2.maxItems == 201 and added.ok == true and Shop.fileStatus().count == 201
    and over.error == "catalog_full",
    "SD-8: at the limit an add is refused; raising ShopMaxItems pushes the new limit to everyone and lets exactly that many in")
check(cmd(boss, "admin.option", { key = "ShopMaxItems", value = 0 }).error == "invalid_args"
    and cmd(boss, "admin.option", { key = "ShopMaxItems", value = 1001 }).error == "invalid_args"
    and Shop.maxItems() == 201,
    "SD-9: the limit stays between 1 and the hard ceiling")
local lowered = cmd(boss, "admin.option", { key = "ShopMaxItems", value = 100 })
local reread = cmd(boss, "admin.catalog", { action = "reload" })
local stillFull = cmd(boss, "admin.catalog", { action = "add", id = "three_more", item = "Base.Nails", prices = { survivor = { price = 5 } } })
local one = cmd(boss, "admin.catalog", { action = "remove", ids = { "b1" }, reason = "sd" })
check(lowered.ok == true and reread.ok == true and reread.count == 201 and stillFull.error == "catalog_full"
    and one.ok == true and Shop.fileStatus().count == 200 and Shop.maxItems() == 100,
    "SD-10: lowering the limit removes nothing and a file over it still loads; adding stays refused, removing still works")

-- 硬上限：超過的檔案載入時被拒，前一份留著；最長的一列乘上硬上限仍放得進一個回覆
local huge = {}
for i = 1, Shop.MAX_SKUS + 1 do huge[i] = { id = "h" .. i, item = "Base.Twine", qty = 1, prices = { survivor = { price = 7 } } } end
catalog(huge)
local tooBig = cmd(boss, "admin.catalog", { action = "reload" })
check(tooBig.ok == false and tooBig.error == "catalog_invalid" and Shop.fileStatus().count == 200,
    "SD-11: a catalog.json over the hard ceiling is refused at load and the previous catalog stays")
catalog({
    { id = "w", item = "Base.Twine", qty = 50, dailyCap = 1000000, dailyCapScope = "lifetime", buybackCap = 1000000,
        category = "x", prices = { survivor = { price = 1000000000, bidPrice = 999999999, buyback = true },
            cat = { price = 1000000000, bidPrice = 999999999, buyback = true } } },
    { id = "v", item = "Base.Nails", qty = 1, category = "x", prices = { survivor = { price = 5 } } },
})
cmd(boss, "admin.catalog", { action = "reload" })
local snap = Shop.snapshot("sd-zed", nowMs)
local row = nil
for _, it in ipairs(snap.items) do if it.id == "w" then row = it end end
row.id, row.item, row.category = string.rep("i", Shop.ID_MAX), string.rep("t", 128), string.rep("\228\184\173", Shop.CATEGORY_MAX)
snap.items = {}
local per, rest = S.wireBytes(row), S.wireBytes(snap)
check(row.remaining ~= nil and row.buybackRemaining ~= nil and row.prices.cat ~= nil
    and per * Shop.MAX_SKUS + rest < S.REPLY_MAX_BYTES * 0.8,
    "SD-12: a catalog at the hard ceiling with every row at its longest fits one reply with room to spare (" .. per .. " bytes a row)")
-- 全部刪光：空目錄，重啟也不會寫回預設商品
local emptied = cmd(boss, "admin.catalog", { action = "remove", ids = { "w", "v" }, reason = "sd" })
fire("OnServerStarted")
check(emptied.ok == true and emptied.extra ~= nil and emptied.extra.count == 2 and Shop.fileStatus().count == 0
    and Shop.fileStatus().errorCode == nil and string.find(fileText(), "bandage", 1, true) == nil
    and #cmd(zed, "shop.list").items == 0,
    "SD-13: removing every row leaves an empty catalog, and a restart does not write the default items back")
Cfg.setOption("ShopMaxItems", nil, "sd-admin")
onlinePlayers = {}
end)()

-- ===== 情境 HV：雙手搬運的重物（ISEquipHeavyItem：放進主背包、兩隻手拿同一個物件） =====
io.write("scenario HV: heavy items carried in both hands\n")
;(function()
local M, Mk, Shop = S.Mailbox, S.Market, S.Shop
local STONE = "Base.LargeStone"
local serial = 0
modDataStore[EC.MODDATA_KEY] = nil
files, sentCommands, sentItemPackets, sentEquips = {}, {}, {}, {}
worldSprites = { ["100,200,0"] = "MinidoracatEconomy_terminal_0" }
SandboxVars.MinidoracatEconomy.ShopBuybackEnabled = true
SandboxVars.MinidoracatEconomy.ShopBuybackPerAccountDaily = 10000
SandboxVars.MinidoracatEconomy.ShopBuybackServerDaily = 100000
files[Shop.FILE] = { lines = { EC.jsonEncode({ items = {
    { id = "stone", item = STONE, qty = 1, price = 20, dailyCap = 0, buyback = true, bidPrice = 3, buybackCap = 0 },
} }) }, opens = 0 }
nowMs = nowMs + 61000
fire("OnServerStarted")
local function cmd(p, name, args)
    serial, nowMs = serial + 1, nowMs + 700
    args = args or {}
    args.requestId = args.requestId or ("hv-" .. serial)
    withCurrency(name, args)
    local first = #sentCommands + 1
    fire("OnClientCommand", EC.COMMAND_MODULE, name, p, args)
    for i = first, #sentCommands do
        local reply = sentCommands[i]
        if reply.player == p and reply.command == name then return reply.args end
    end
    error("missing reply: " .. name)
end
local boss = fakePlayer("hv-boss"); boss.role = "admin"
local seller, buyer, carrier, porter = fakePlayer("hv-seller"), fakePlayer("hv-buyer"), fakePlayer("hv-carrier"), fakePlayer("hv-porter")
onlinePlayers = { boss, seller, buyer, carrier, porter }
assert(cmd(boss, "terminal.register", { x = 100, y = 200, z = 0, kind = "atm" }).ok)
for _, p in ipairs({ seller, buyer, carrier, porter }) do
    assert(L.credit(p:getUsername(), "survivor", 10000, "SYSTEM_MINT", { requestId = "hv-seed-" .. p:getUsername(), reasonCode = "test" }).ok)
end
-- ISEquipHeavyItem.complete:59-86：主背包裡、兩隻手拿著同一個物件
local function carry(p, item)
    if not p.inventory:contains(item) then p.inventory:AddItem(item) end
    p:setPrimaryHandItem(item); p:setSecondaryHandItem(item)
    return item
end
local function drop(p, item) p:removeFromHands(item); p.inventory:Remove(item) end
-- 最後一個送給 p 的裝備封包，與 item 被移除／加入的物品封包序號
local function lastEquip(p)
    for i = #sentEquips, 1, -1 do if sentEquips[i].player == p then return sentEquips[i] end end
    return nil
end
local function packetOf(item, field)
    for i = #sentItemPackets, 1, -1 do
        local pk = sentItemPackets[i]
        if field == "remove" and pk.remove == item then return i end
        if field == "add" and pk.add then for _, it in ipairs(pk.add) do if it == item then return i end end end
    end
    return nil
end
-- the hands were emptied and the client told so before the object's remove packet
local function releasedFirst(p, item, equipsBefore)
    local eq, removedAt = lastEquip(p), packetOf(item, "remove")
    return p.primary == nil and p.secondary == nil and not p.inventory:contains(item) and #sentEquips > equipsBefore
        and eq ~= nil and eq.primary == nil and eq.secondary == nil and removedAt ~= nil and eq.after < removedAt
end
-- both hands hold item and the equip went out after the client had the object
local function heldAfterAdd(p, item)
    local eq, addedAt = lastEquip(p), packetOf(item, "add")
    return item ~= nil and p.primary == item and p.secondary == item and p.inventory:contains(item)
        and eq ~= nil and eq.primary == item and eq.secondary == item and addedAt ~= nil and eq.after >= addedAt
end

-- HV-1: the picker offers the stone in both hands; an ordinary equipped item stays refused
local stone = carry(seller, instanceItem(STONE))
local axe = instanceItem("Base.Axe"); seller.inventory:AddItem(axe); axe.equipped = true
local rows = {}
for _, r in ipairs(cmd(seller, "market.candidates").items) do rows[r.item] = r end
check(rows[STONE] ~= nil and rows[STONE].ok == true and rows["Base.Axe"] ~= nil and rows["Base.Axe"].ok == false
    and rows["Base.Axe"].reason == "equipped",
    "HV-1: a heavy item held in both hands is a listing candidate; an ordinary equipped item is still refused")
drop(seller, axe)

-- HV-2: the list-out empties both hands and tells the client before the remove packet
local equips = #sentEquips
local listed = cmd(seller, "market.list", { itemId = stone.id, price = 100 })
check(listed.ok == true and releasedFirst(seller, stone, equips),
    "HV-2: listing a heavy item clears both hands and sends the equip before its removal")

-- HV-3: the buyer gets it in both hands, past a backpack that could never hold 40
local bought = cmd(buyer, "market.buy", { listingId = listed.listingId, price = 100 })
local got = buyer.primary
check(bought.ok == true and bought.delivered == true and got ~= nil and got.fullType == STONE and got ~= stone
    and heldAfterAdd(buyer, got),
    "HV-3: buying a heavy listing delivers it into both hands, the equip after the item packet")

-- HV-4: hands already on a heavy item take nothing more; the letter waits and nothing is lost
local second = carry(seller, instanceItem(STONE))
local listed2 = cmd(seller, "market.list", { itemId = second.id, price = 100 })
local confirm = cmd(buyer, "market.buy", { listingId = listed2.listingId, price = 100 })
local shopConfirm = cmd(buyer, "shop.buy", { id = "stone", count = 1, revision = Shop.revision() })
check(listed2.ok == true and confirm.ok == false and confirm.error == "mail_confirmation_required" and confirm.heavy == true
    and shopConfirm.error == "mail_confirmation_required" and shopConfirm.heavy == true,
    "HV-4a: buying while holding a heavy item asks for the mailbox and says the letter is heavy (market and shop)")
local parked = cmd(buyer, "market.buy", { listingId = listed2.listingId, price = 100, acceptMail = true })
local full = cmd(buyer, "mail.claim", { mailId = parked.mailId })
local entry = M.entryOf("hv-buyer", parked.mailId)
check(parked.ok == true and parked.mailed == true and full.ok == false and full.error == "hands_full" and full.heavy == true
    and full.remainingQty == 1 and entry.state == "ready" and buyer.primary == got and buyer.secondary == got
    and buyer.inventory.count(STONE) == 1,
    "HV-4b: claiming with a heavy item in hand answers hands_full, adds nothing and leaves the letter ready")
drop(buyer, got)
local freed = cmd(buyer, "mail.claim", { mailId = parked.mailId })
check(freed.ok == true and entry.state == "claimed" and buyer.inventory.count(STONE) == 1 and heldAfterAdd(buyer, buyer.primary),
    "HV-4c: once the hands are free the same letter is claimed into both hands")

-- HV-5: the shop does not refuse a heavy unit for the backpack's size
carrier.inventory = fakeInventory(5); carrier.inventory.capacity = 5; carrier.inventory.character = carrier
local shopBuy = cmd(carrier, "shop.buy", { id = "stone", count = 1, revision = Shop.revision() })
check(shopBuy.ok == true and shopBuy.delivered == true and carrier.primary ~= nil and heldAfterAdd(carrier, carrier.primary),
    "HV-5: a heavy shop item is not unit_too_heavy: it is bought and delivered into both hands")

-- HV-6: a two-unit heavy letter hands over one unit per claim
local two = M.add("hv-porter", { kind = "shop", item = STONE, qty = 2, txId = "tx-hv-two" })
equips = #sentEquips
local firstClaim = cmd(porter, "mail.claim", { mailId = two.id })
local firstStone = porter.primary
check(firstClaim.error == "delivery_partial" and firstClaim.deliveredQty == 1 and firstClaim.remainingQty == 1
    and firstClaim.heavy == true and porter.inventory.count(STONE) == 1 and heldAfterAdd(porter, firstStone)
    and #sentEquips == equips + 1,
    "HV-6a: a two-unit heavy letter delivers one unit into both hands (one equip, after the item) and keeps the other in the letter")
local blocked = cmd(porter, "mail.claimAll", { mailIds = { two.id } })
blocked = blocked.results and blocked.results[1] or {}
drop(porter, firstStone)
local secondClaim = cmd(porter, "mail.claim", { mailId = two.id })
check(blocked.error == "hands_full" and blocked.heavy == true and secondClaim.ok == true and secondClaim.deliveredQty == 1 and two.state == "claimed"
    and porter.inventory.count(STONE) == 1 and heldAfterAdd(porter, porter.primary) and porter.primary ~= firstStone,
    "HV-6b: the second unit waits for free hands and then comes through the same way")

-- HV-7: an auction and a sale to the system take the item out through the same hands-first removal
local auctioned = carry(seller, instanceItem(STONE))
equips = #sentEquips
local auction = cmd(seller, "auction.create", { itemId = auctioned.id, startPrice = 100, hours = 24 })
check(auction.ok == true and releasedFirst(seller, auctioned, equips),
    "HV-7a: putting a held heavy item up for auction clears the hands before the removal")
local sold = carry(seller, instanceItem(STONE))
equips = #sentEquips
local sale = cmd(seller, "shop.sell", { id = "stone", itemIds = { sold.id }, revision = Shop.revision() })
check(sale.ok == true and releasedFirst(seller, sold, equips),
    "HV-7b: selling a held heavy item to the system clears the hands before the removal")

-- HV-8: an older player save still holding a listed stone in both hands: the login takes it back
local stale = carry(seller, instanceItem(STONE))
local function copy(v)
    if type(v) ~= "table" then return v end
    local out = {}
    for k, value in pairs(v) do out[k] = copy(value) end
    return out
end
local oldPlayer, oldData = copy(seller.modData), copy(stale:getModData())
local staleListing = cmd(seller, "market.list", { itemId = stale.id, price = 100 })
seller.modData, stale.modData = copy(oldPlayer), oldData
carry(seller, stale)
local meta = S.modData().meta
files[S.DURABLE_FILE] = { lines = { EC.jsonEncode({ realmId = meta.realmId, epoch = meta.epoch, seq = meta.seq, ts = nowMs }) } }
S.pollDurable(true)
equips = #sentEquips
M.reconcile(seller)
proofPump(seller:getUsername())
check(staleListing.ok == true and Mk.listingExists(staleListing.listingId) and releasedFirst(seller, stale, equips),
    "HV-8: a stale heavy copy held in both hands is reclaimed at login with its hands cleared first")

-- HV-9: a removal that fails puts the object back into the hands it came from
local kept = carry(seller, instanceItem(STONE))
local realRemove = seller.inventory.Remove
seller.inventory.Remove = function() error("removal rejected before mutation") end
local aborted = cmd(seller, "market.list", { itemId = kept.id, price = 100 })
seller.inventory.Remove = realRemove
local eq = lastEquip(seller)
check(aborted.error == "delivery_failed" and seller.primary == kept and seller.secondary == kept and seller.inventory:contains(kept)
    and eq.primary == kept and eq.secondary == kept,
    "HV-9: an aborted list-out puts the heavy item back into both hands and tells the client")

-- HV-10: a refusal after the removal (the listing fee) puts the object back into both hands too
local refused = carry(seller, instanceItem(STONE))
local realDebit = L.debit
L.debit = function() return { ok = false, error = "account_frozen" } end
local feeRefused = cmd(seller, "market.list", { itemId = refused.id, price = 100 })
L.debit = realDebit
check(feeRefused.ok == false and feeRefused.error == "account_frozen" and heldAfterAdd(seller, refused),
    "HV-10: a fee refused after the removal puts the heavy item back into both hands, the equip after the item")
onlinePlayers = {}
end)()

-- ===== 情境 LM：合併上架不看沒人讀的隱藏紀錄 =====
io.write("scenario LM: a lot leaves out the hidden records nothing reads back\n")
;(function()
modDataStore[EC.MODDATA_KEY] = nil
files, sentCommands = {}, {}
nowMs = nowMs + 61000
fire("OnServerStarted")
worldSprites = { ["100,200,0"] = "MinidoracatEconomy_terminal_0" }
local boss = fakePlayer("lm-admin"); boss.role = "admin"
local seller = fakePlayer("lm-seller"); seller.x, seller.y = 101, 200; seller.inventory = fakeInventory(80)
onlinePlayers = { boss, seller }
local function cmd(who, name, args)
    nowMs = nowMs + 600
    args = args or {}
    args.requestId = args.requestId or (name .. nowMs)
    withCurrency(name, args)
    fire("OnClientCommand", EC.COMMAND_MODULE, name, who, args)
    local s = lastSent(name)
    return s and s.args or {}
end
cmd(boss, "terminal.register", { x = 100, y = 200, z = 0, kind = "atm" })
L.credit("lm-seller", "survivor", 500, "SYSTEM_MINT", { requestId = "lm-seed", reasonCode = "t" })
local function plank(md)
    local it = instanceItem("Base.Plank")
    for k, v in pairs(md) do it.modData[k] = v end
    seller.inventory:AddItem(it)
    return it
end
-- the same plank moved in two different hours (MinidoracatCleaner), once dropped, once made from
-- rope (the vanilla crafting record); every copy has the same name flag and the same twine count
local a = plank({ customName = true, ["Base.Twine"] = 2, ["Base.Rope"] = 1, MIC42_t = "lm-seller,1790776800" })
local b = plank({ customName = true, ["Base.Twine"] = 2, MIC42_t = "lm-seller,1790780400", MIC42_d = "lm-seller" })
local c = plank({ customName = true, ["Base.Twine"] = 2, MIC42_lastMovedBy = "someone" })
-- not records: a key that names no item, a count stored as text
plank({ customName = true, ["Base.Twine"] = 2, ["Base.NotAnItem"] = 1 })
plank({ customName = true, ["Base.Twine"] = "2" })
-- a copy left with nothing once its stamp is set aside, and one that never had modData
local f = plank({ MIC42_d = "lm-seller" })
local g = plank({})
local counts = {}
for _, r in ipairs(cmd(seller, "market.candidates").items) do
    if r.item == "Base.Plank" then counts[#counts + 1] = r.count end
end
check(#counts == 4 and counts[1] == 3 and counts[2] == 1 and counts[3] == 1 and counts[4] == 2,
    "LM-1: copies differing only in mover stamps and crafting records are one row; a key naming no item or a count stored as text still split")
local listed = cmd(seller, "market.list", { itemIds = { a.id, b.id, c.id }, price = 30 })
local lot = listed.ok and S.modData().market.listings[listed.listingId]
local md = lot and lot.snapshot.modData or {}
check(listed.ok == true and lot.qty == 3 and md["Base.Twine"] == 2 and md.customName == true
    and md["Base.Rope"] == nil and md.MIC42_t == nil and md.MIC42_d == nil,
    "LM-2: the lot keeps a record only when every copy has the same one: the shared twine count stays, the first copy's rope and the differing stamps do not")
local auction = cmd(seller, "auction.create", { itemIds = { f.id, g.id }, startPrice = 20, hours = 24 })
local held = auction.ok and S.modData().auctions.items[auction.auctionId]
check(auction.ok == true and held.qty == 2 and held.snapshot.modData == nil,
    "LM-3: an auction lot is stored the same way: the first copy's stamp does not reach the copy that had none")
local h = plank({ ["Base.Rope"] = 1, MIC42_t = "lm-seller,1790776800" })
local single = cmd(seller, "market.list", { itemIds = { h.id }, price = 10 })
local one = single.ok and S.modData().market.listings[single.listingId].snapshot.modData or {}
check(single.ok == true and one["Base.Rope"] == 1 and one.MIC42_t == "lm-seller,1790776800",
    "LM-4: a single copy keeps every record it had")
onlinePlayers = {}
end)()

-- ===== 情境 WC：白名單依物品分類，選物格說出是哪一條規則擋下 =====
io.write("scenario WC: the category the whitelist goes by and the rule that refused an item\n")
;(function()
modDataStore[EC.MODDATA_KEY] = nil
files, sentCommands = {}, {}
nowMs = nowMs + 61000
fire("OnServerStarted")
local Codec = S.Codec
-- MOD scripts that set no DisplayCategory: the class decides (vanilla's inventory column does the same)
knownItems["WcMod.Jerky"] = { w = 0.2, main = "Food" }
knownItems["WcMod.Gadget"] = { w = 0.2, main = "Item" }
knownItems["Base.Animal_Brain"] = { w = 0.3, cat = "AnimalPart", main = "Food" }
worldSprites = { ["100,200,0"] = "MinidoracatEconomy_terminal_0" }
local boss = fakePlayer("wc-admin"); boss.role = "admin"
local seller = fakePlayer("wc-seller"); seller.x, seller.y = 101, 200; seller.inventory = fakeInventory(80)
onlinePlayers = { boss, seller }
local function cmd(who, name, args)
    nowMs = nowMs + 600
    args = args or {}
    args.requestId = args.requestId or (name .. nowMs)
    withCurrency(name, args)
    fire("OnClientCommand", EC.COMMAND_MODULE, name, who, args)
    local s = lastSent(name)
    return s and s.args or {}
end
cmd(boss, "terminal.register", { x = 100, y = 200, z = 0, kind = "atm" })
L.credit("wc-seller", "survivor", 500, "SYSTEM_MINT", { requestId = "wc-seed", reasonCode = "t" })
local function give(fullType)
    local it = instanceItem(fullType)
    seller.inventory:AddItem(it)
    return it
end
local jerky, gadget, brain, map = give("WcMod.Jerky"), give("WcMod.Gadget"), give("Base.Animal_Brain"), give("Base.Map")
local _, _, ruleMap = Codec.check(map)
local _, _, ruleBrain = Codec.check(brain)
check(ruleMap == "fixed" and ruleBrain == "category" and Codec.check(jerky) == true,
    "WC-1: a fixed class is refused as fixed, a closed category as category, and a MOD food with no DisplayCategory goes by its class (Food is open)")
;(function()
    -- a script's category must not create an item (Item.InstanceItem runs the script's Lua OnCreate)
    local real = instanceItem
    instanceItem = function() error("an item was created") end
    local okCat, jerkyCat, gadgetCat, brainCat = pcall(function()
        return EC.itemCategory(ScriptManager.instance:FindItem("WcMod.Jerky")), EC.itemCategory(ScriptManager.instance:FindItem("WcMod.Gadget")),
            EC.itemCategory(ScriptManager.instance:FindItem("Base.Animal_Brain"))
    end)
    instanceItem = real
    check(okCat and jerkyCat == "Food" and gadgetCat == "Item" and brainCat == "AnimalPart",
        "WC-2: a script with no DisplayCategory takes its class's category without creating an item; one that has it keeps it")
end)()
local rows = {}
for _, r in ipairs(cmd(seller, "market.candidates").items) do rows[r.item] = r end
check(rows["WcMod.Jerky"].ok == true and rows["WcMod.Jerky"].category == "Food"
    and rows["WcMod.Gadget"].ok == false and rows["WcMod.Gadget"].category == "Item" and rows["WcMod.Gadget"].rule == "category"
    and rows["Base.Animal_Brain"].category == "AnimalPart" and rows["Base.Animal_Brain"].rule == "category"
    and rows["Base.Map"].rule == "fixed",
    "WC-3: every picker row carries the category the whitelist went by and a refused one the rule that refused it")
local listed = cmd(seller, "market.list", { itemIds = { jerky.id }, price = 30 })
local lot = listed.ok and S.modData().market.listings[listed.listingId]
check(listed.ok == true and lot.category == "Food", "WC-4: the listing files a MOD item under the same category the whitelist used")
local refusedList = cmd(seller, "market.list", { itemIds = { gadget.id }, price = 30 })
local refusedAuction = cmd(seller, "auction.create", { itemIds = { gadget.id }, startPrice = 20, hours = 24 })
check(refusedList.error == "not_whitelisted" and refusedList.rule == "category" and refusedList.category == "Item"
    and refusedAuction.error == "not_whitelisted" and refusedAuction.rule == "category" and refusedAuction.category == "Item",
    "WC-6: a listing or an auction refused by the whitelist names the rule and the category, as the picker does")
files["MinidoracatEconomy/whitelist.json"] = { lines = { '{"categories":["AnimalPart"],"types":[],"excludeTypes":["Base.Animal_Brain"]}' }, opens = 0 }
local loaded = Codec.load()
local _, _, ruleExcluded = Codec.check(brain)
check(loaded == true and ruleExcluded == "excluded", "WC-5: an item the host excluded is refused as excluded even when its category is open")
onlinePlayers = {}
end)()

